INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('43f7d8cd-ccce-54cd-aa72-02a2f92b8c17', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 11, 11, 'እናንተም፦ ሰማይንና ምድርን ያልፈጠሩ እነዚህ አማልክት ከምድር ላይ፥ ከሰማይም በታች ፈጽመው ይጥፉ ትሉአቸዋላችሁ።'),
  ('23e0404e-9178-54c7-a12d-e504382c33db', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 12, 12, 'ምድርን በኀይሉ የፈጠረ፥ ዓለሙን በጥበቡ ያጸና፥ ሰማያትንም በማስተዋሉ የዘረጋ እርሱ ነው።'),
  ('c5c744dd-92fa-53dc-af04-fbf79cb4876c', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 13, 13, 'በላይ በሰማይ ውኆችን ይሰበስባል፤ ከምድርም ዳርቻ ደመናትን ከፍ ያደርጋል፤ ለዝናብም መብረቅን ያደርጋል፤ ነፋስንም ከቤተ መዛግብቱ ያወጣል።'),
  ('adcbd28f-3560-5704-a74e-ce0cfe425b9e', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 14, 14, 'ሰው ሁሉ ዕውቀት አጥቶ ሰንፎአል፤ አንጥረኛም ሁሉ ከቀረጸው ምስል የተነሣ አፍሮአል፤ ቀልጦ የተሠራ ምስሉ ውሸት ነውና፥ እስትንፋስም የለውምና።'),
  ('0b2b6d0f-105b-529e-ae21-9e995e3077d5', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 15, 15, 'አገጣጥመው የሚሠሩት ሥራ ከንቱ ነው፤ በተጐበኙ ጊዜም ይጠፋሉ።'),
  ('276e968b-2d0b-57f2-a94a-dfe23618db42', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e01287cd-e61c-5661-a31b-375df76c1830', 16, 16, 'የያዕቆብ ዕድል ፈንታ እንደ እነዚህ አይደለም፤ እርሱ ሁሉን የፈጠረ ነውና እስራኤልም የርስቱ ነገድ ነውና፤ ስሙም የሠራዊት ጌታ እግዚአብሔር ነው።'),
  ('c30c4cdd-e7ef-56dd-a855-3547c628bd86', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 1, 17, 'በምሽግ ውስጥ የተቀመጥሽ ሆይ! ኀይልሽን ከውጭ ሰብስቢ፤'),
  ('b54eb6b0-3b15-53e1-a09f-484ac23f96ff', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 2, 18, 'እግዚአብሔር እንዲህ ይላልና፦ እነሆ በምድሪቱ የሚኖሩትን በመከራ አሰናክላቸዋለሁ፤ መቅሠፍትሽም እንዲያገኛቸው አስጨንቃቸዋለሁ።'),
  ('03b8342d-322b-54db-aa11-62fc5627657b', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 3, 19, 'ስለ ስብራቴ ወዮልኝ! ቍስሌም ክፉ ነው፤ እኔ ግን፦ በእውነት የመከራ ቁስሌ ነው፤ እርሱንም መሸከም ይገባኛል አልሁ።'),
  ('ef5b7fff-f3f4-5002-ab6f-c4eea35e3383', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 4, 20, 'ድንኳኔም ተበዘበዘ፤ አውታሬም ሁሉ ተቈረጠ፤ ልጆችና በጎችም የሉም ከእንግዲህ ወዲህ ለድንኳኔም ቦታ የለም ለመንጎችም መሰማሪያ የለም፤'),
  ('754bd88a-1ee3-5248-aee0-7a8d8ee8f6aa', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 5, 21, 'እረኞች አእምሮአቸውን አጥተዋልና፥ እግዚአብሔርንም አልፈለጉትምና፤ ስለዚህም መሰማሪያውን አላወቁም፤ መንጎቻቸውም ሁሉ ተበትነዋል።'),
  ('4d2bed24-88ce-5c18-ab3c-202f0509da2d', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 6, 22, 'የወሬ ድምፅ ተሰማ፤ እነሆም የይሁዳን ከተሞች ባድማና የሰገኖ ማደሪያ ያደርጋቸው ዘንድ ከሰሜን ምድር ታላቅ መነዋወጥ መጥቶአል።'),
  ('42adb15d-1bf3-5cad-acf9-4d656ac69618', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 7, 23, 'አቤቱ! የሰው መንገድ ከራሱ እንደ አይደለ አውቃለሁ፤ ሰውም አይሄድባትም፤ መንገዱንም ጥርጊያ አላደረገም።'),
  ('e1f7af8d-c9d2-5c60-ab9e-587c2b54ca07', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 8, 24, 'አቤቱ! ቅጣን፤ ነገር ግን ፈጽመህ እንዳታጠፋን በፍርድህ ይሁን እንጂ በቍጣህ አይሁን።'),
  ('7d400627-b56c-5700-a075-4a7006e5b2d9', 'cee467a9-2d1c-58dc-a32c-20803a54f70a', 'e485e3db-169d-5e0c-a15e-bc9b52a65bf4', 9, 25, 'ያዕቆብን በልተውታልና፥ አጥፍተውትማልና፥ ማደሪያውንም አፍርሰዋልና በማያውቁህ አሕዛብ፥ ስምህንም በማይጠሩ ትውልድ ላይ መዓትህን አፍስስ።'),
  ('30259f21-5a4b-588e-a772-4e18adda026d', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 1, 1, 'ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣው ቃል ይህ ነው።'),
  ('f27bcb5a-f6a6-5803-a775-52d6fd221e68', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 2, 2, 'የዚህን ቃል ኪዳን ቃል ስሙ፤ ለይሁዳም ሰዎች በኢየሩሳሌምም ለሚኖሩ ተናገሩ፤'),
  ('a90c7e09-bfec-571a-a0fc-733186ffe4a9', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 3, 3, 'እንደዚህም በሏቸው፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “የዚህን ቃል ኪዳን ቃል የማይሰማ ሰው ርጉም ይሁን፤'),
  ('eeef98f0-b3be-54e1-a8f0-6387ce1c7921', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 4, 4, 'ከግብፅ ሀገር ከብረት ምድጃ ባወጣኋቸው ቀን ለአባቶቻችሁ ያዘዝሁትን፥ ያዘዝኋችሁንም ሁሉ አድርጉ፤ እንዲሁም እናንተ ሕዝብ ትሆኑኛላችሁ፤ እኔም አምላክ እሆናችኋለሁ” ያልሁትን ቃሌን ስሙ።'),
  ('5ed6beb0-838a-59ea-a6ff-67a7b3a35fba', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 5, 5, 'ይህም ዛሬ እንደ ሆነ ወተትና ማር የምታፈስሰውን ምድር እሰጣቸው ዘንድ ለአባቶቻችሁ የማልሁትን መሐላ አጸና ዘንድ ነው። እኔም፥ “አቤቱ! ጌታ ሆይ! ይሁን” ብዬ መለስሁለት።'),
  ('3dce8c2d-05e0-5a38-a460-286a4e3f885a', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 6, 6, 'እግዚአብሔርም እንዲህ አለኝ፥ “ይህችን ቃል ሁሉ በይሁዳ ከተሞችና በኢየሩሳሌም አደባባይ ተናገር፤ እንዲህም በል፦ የዚህን ቃል ኪዳን ቃል ስሙ፤ አድርጉትም።'),
  ('c4322423-4d94-5286-a5e0-cd35fa233ca8', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 7, 7, 'አባቶቻችሁን ከግብፅ ምድር ከአወጣሁበት ቀን ጀምሮ እስከ ዛሬ ድረስ፥ በማለዳ ተነሥቼ እያስጠነቀቅሁ፦ ቃሌን ስሙ በማለት አስጠንቅቄአቸው ነበር።'),
  ('46eb842d-7a60-5f05-ac40-56c1162211ce', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 8, 8, 'እነርሱ ሁሉ ግን በክፉ ልባቸው እልከኝነት ሄዱ እንጂ አልሰሙም፤ ጆሮአቸውንም አላዘነበሉም፤ ስለዚህ ያዘዝኋቸውን እነርሱም ያላደረጉትን የዚህን ቃል ኪዳን ቃል ሁሉ አመጣሁባቸው።”'),
  ('5354b521-f72c-5adc-a2fc-4a6a88f99b6b', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 9, 9, 'እግዚአብሔርም እንዲህ አለኝ፦ በይሁዳ ሰዎችና በኢየሩሳሌም በሚኖሩ ዘንድ አድማ ተገኝቶአል።'),
  ('ad2b143e-6fc3-57f6-a13d-8d75ec67393f', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 10, 10, 'ቃሌን ይሰሙ ዘንድ እንቢ ወደ አሉ ወደ አባቶቻቸው ኀጢአት ተመለሱ፥ ያመልኩአቸውም ዘንድ እንግዶችን አማልክት ተከተሉ፤ የእስራኤል ቤትና የይሁዳ ቤት ከአባቶቻቸው ጋር ያደረግሁትን ቃል ኪዳን አፈረሱ።'),
  ('17ae76a7-8481-50a2-a814-56f021c4de03', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 11, 11, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ ሊያመልጡት የማይችሉትን ክፉ ነገር በዚህ ሕዝብ ላይ አመጣለሁ፤ ወደ እኔም ይጮኻሉ፤ እኔ ግን አልሰማቸውም።'),
  ('504ff12d-8540-57f4-a9a9-6dae12e342e4', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 12, 12, 'በይሁዳም ከተሞችና በኢየሩሳሌም የሚኖሩ ሄደው ወደሚያጥኑላቸው፥ በመከራቸው ጊዜ ከቶ ወደማያድኗቸው አማልክት ይጮኻሉ።'),
  ('d7051fa6-bae1-536b-a794-5206f79881cf', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 13, 13, 'ይሁዳ ሆይ! አማልክትህ እንደ ከተሞችህ ቍጥር እንዲሁ ናቸው፤ እንደ ኢየሩሳሌምም መንገዶች ቍጥር ለነውረኛ ነገር ለበዓል ታጥኑባቸው ዘንድ መሠዊያዎችን አድርጋችኋል።'),
  ('984734c9-bc01-5bce-ac8d-55401fadbd5d', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 14, 14, 'አንተም ስለዚህ ሕዝብ አትጸልይ፤ በመከራቸው ቀን ወደ እኔ በጮኹ ጊዜ አልሰማቸውምና ስለ እነርሱ አትጸልይ፤ በምልጃና በጸሎት አትማልድ።'),
  ('0d3cf6cd-e99a-53fa-a2dd-2919ca7f3abf', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 15, 15, 'ወዳጄ በቤቴ ውስጥ ለምን ርኵሰትን አደረገች? ስእለት ወይም የተቀደሰ ሥጋ ክፋትሽን ከአንቺ ያስወግዳልን? ወይስ በእነዚህ ታመልጫለሽን?'),
  ('f2647110-a52f-5cf6-ad1e-02ac66e7912a', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 16, 16, 'እግዚአብሔር ስምሽን፦ በመልካም ፍሬ የተዋበችና የለመለመች የወይራ ዛፍ ብሎ ጠራው፤ ከመቈረጥዋም ድምፅ የተነሣ በላይዋ እሳት ነደደባት፤ ቅርንጫፎችዋም ተሰብረዋል።'),
  ('568c8242-d74d-595a-a714-33ad3c2dd083', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '6fcd6a89-6a31-5f96-a1b9-f4df2fef0c8c', 17, 17, 'ለበዓልም በማጠናቸው ያስቈጡኝ ዘንድ ለራሳቸው ስለ ሠሩአት ስለ እስራኤልና ስለ ይሁዳ ቤት ክፋት የተከለሽ የሠራዊት ጌታ እግዚአብሔር ክፉን ነገር ተናግሮብሻል።'),
  ('bedc6266-2419-536d-ab3c-5539b1dd056c', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 1, 18, 'ጌታ ሆይ! አስታውቀኝ፤ እኔም አውቃለሁ፤ ያንጊዜም ሥራቸውን ገለጥህልኝ።'),
  ('c1bd746b-3b6e-5457-a56f-8ec8b20180c7', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 2, 19, 'እኔም ለመታረድ እንደሚነዳ እንደ የዋህ ጠቦት በግ ሆንሁ፤ እነርሱም በእንጀራው ዕንጨት እንጨምር ስሙም ከእንግዲህ ወዲህ እንዳይታሰብ ከሕያዋን ምድር እናጥፋው ብለው ክፉ ምክርን እንዳሰቡብኝ አላወቅሁም ነበር።'),
  ('e04c8dbd-071c-58f8-a41e-679936ce1cad', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 3, 20, 'ኵላሊትንና ልብን የምትፈትን፥ በቅንም የምትፈርድ እግዚአብሔር ሆይ! ክርክሬን ገልጬልሃለሁና ከእነርሱ ፍረድልኝ።'),
  ('a916fd59-3c4f-57ea-a00c-0dbe19edcace', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 4, 21, 'ስለዚህም፥ “በእጃችን እንዳትሞት በእግዚአብሔር ስም ትንቢት አትናገር” ብለው ነፍሴን ስለሚሹ ስለ አናቶት ሰዎች እግዚአብሔር እንዲህ ይላል፦'),
  ('54a695b3-2ea8-51f2-a3d4-efad1e4b8421', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 5, 22, 'ስለዚህ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በመዓት እጐበኛቸዋለሁ፤ ጐበዛዝቶቻቸው በሰይፍ ይሞታሉ፤ ወንዶችና ሴቶች ልጆቻቸውም በራብ ይሞታሉ፤'),
  ('cc2955c4-68b9-5bd2-aa85-5daf30bd1d38', '47566b27-a43f-5ec7-aaa5-b9387d3f5009', '07fd1218-9f03-5f80-a487-818b076363be', 6, 23, 'በምጐበኛቸውም ዓመት በዓናቶት ሰዎች ላይ ክፉ ነገር አመጣባቸዋለሁና ማንም ከእነርሱ የሚተርፍ የለም።'),
  ('95d0e18c-9484-5151-a6af-bb9bad6756d1', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 1, 1, 'አቤቱ! ከአንተ ጋር በተምዋገትሁ ጊዜ አንተ ጻድቅ ነህ፤ ነገር ግን ከአንተ ጋር ስለ ፍርድ ልናገር። የኀጢአተኞች መንገድ ስለ ምን ይቀናል? በደልንስ የሚያደርጉ ሁሉ ስለ ምን ደስ ይላቸዋል?'),
  ('9fe827a5-1da4-5efa-a468-295151c04ddd', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 2, 2, 'አንተ ተክለሃቸዋል፤ ሥር ሰድደዋል፤ ወልደዋል አፍርተውማል፤ በአፋቸውም አንተ ቅርብ ነህ፤ ከልባቸው ግን ሩቅ ነህ።'),
  ('85148709-813f-5201-a7ed-fc564c75391e', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 3, 3, 'አንተ ግን አቤቱ! ዐውቀኸኛል፤ አይተኸኛል፤ ልቤንም በፊትህ ፈትነሃል፤ እንደ በጎች ለመታረድ ጐትተህ ለያቸው፤ ለመታረድም ቀን አዘጋጃቸው።'),
  ('ffa2ef51-0a70-5745-acb4-fcbf04674326', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 4, 4, 'በሚኖሩባት ሰዎች ክፋት ምድሪቱ የምታለቅሰውና የዱሩ ሣርስ ሁሉ የሚደርቀው እስከ መቼ ነው? እግዚአብሔር ፍጻሜያችንን አያይም ብለዋልና እንስሶችና ወፎችም ጠፍተዋል።'),
  ('0c0e57f3-20ec-567b-a26b-f0cfd40324f7', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 5, 5, 'እግሮችህ ሮጠው ይደክማሉ፤ ፈረሶችን ለምን ታስጌጣለህ? በሰላምም ምድር ላይ ለምን ትታመናለህ? በዮርዳኖስስ ጩኸት ለምን እንዲህ ታደርጋለህ?'),
  ('6f0da7f7-abd4-5c65-aec8-53e95064e078', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 6, 6, 'ወንድሞችህና የአባትህ ቤት እነርሱ ጭምር ክደውሃልና፥ ጮኸውም በስተኋላህ ተሰበሰቡ፤ በመልካምም ቢናገሩህ አትመናቸው።'),
  ('59be8bca-bb42-5832-a4cb-5bc6b96463df', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 7, 7, 'ቤቴን ትችአለሁ፤ ርስቴንም ጥያለሁ፤ ነፍሴ የምትወድዳትንም በጠላቶችዋ እጅ አሳልፌ ሰጥቻለሁ።'),
  ('6d23d4a8-8faf-5935-afcf-3140e9b5eab9', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 8, 8, 'ርስቴ በዱር እንደ አለ አንበሳ ሆናብኛለች፤ ድምፅዋንም አንሥታብኛለች፤ ስለዚህ ጠልቻታለሁ።'),
  ('cf9acdc4-b7c3-50c9-a8bd-c1b2838e6622', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 9, 9, 'ርስቴ እንደ ጅብ ጕድጓድ ናትን? ወይስ በዙሪያዋ የሚከቡአት የሽፍቶች ዋሻ ናትን? የምድር አራዊት ሁሉ ይበሉአት ዘንድ ተሰብስበው ይመጣሉ።'),
  ('98e91143-85cd-57ab-ad0c-f8fd8e758fd5', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 10, 10, 'ብዙ እረኞች የወይኑን ቦታዬን አጥፍተዋል፤ እድል ፈንታዬንም አርክሰዋል፤ የምወድዳትንም እድል ፈንታ ምድረ በዳ አድርገዋታል።'),
  ('132630f0-7192-52fd-a9fe-d9b008183e0d', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 11, 11, 'እርስዋም ለፍጹም ጥፋት ሆናለች፤ ስለ እኔም ምድር ሁሉ ባድማ ሆናለች፤ በልቡም የሚያኖራት የለም።'),
  ('06e5b004-dcad-5431-a4cc-78ede04edbc4', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 12, 12, 'ወራዶች ወደ ዱር ሁሉ መጥተዋል፤ የእግዚአብሔር ሰይፍ ከምድር ዳር ጀምሮ እስከ ምድር ዳር ድረስ ይበላልና፤ ለሥጋ ለባሽ ሁሉ ሰላም የለም።'),
  ('f6d0ddb2-926f-57b0-a191-853af474a422', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 13, 13, 'ስንዴን ትዘራላችሁ፤ እሾህንም ታጭዳላችሁ፤ ዕጣችሁም ምንም አይጠቅማችሁም፤ ከእግዚአብሔር ጽኑ ቍጣ የተነሣ በአዝመራችሁ ታፍራላችሁ።'),
  ('83b4b2a6-491c-58ab-a2ff-2c19ae09ea34', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 14, 14, 'እግዚአብሔር ለሕዝቤ ለእስራኤል ያወረስሁትን ርስት ለሚነኩት ክፉዎች ጎረቤቶች ሁሉ እንዲህ ይላልና፥ “እነሆ ከምድራቸው እነቅላቸዋለሁ፤ የይሁዳንም ቤት ከመካከላቸው እነቅለዋለሁ።'),
  ('1ad3b78c-bc1f-5697-a138-d50be0be0ca5', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 15, 15, 'ከነቀልኋቸውም በኋላ መልሼ ይቅር እላቸዋለሁ፥ ሁላቸውንም በርስታቸው፥ እያንዳንዳቸውንም በምድራቸው አኖራቸዋለሁ።'),
  ('b337b69c-da40-55e7-a8e0-c5a9ab244cda', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 16, 16, 'በበዓል ይምሉ ዘንድ ሕዝቤን እንዳስተማሩ በስሜ፦ ሕያው እግዚአብሔርን! ብለው ይምሉ ዘንድ የሕዝቤን መንገድ ፈጽመው ቢማሩ፥ በዚያ ጊዜ በሕዝቤ መካከል ይመሠረታሉ።'),
  ('cf0da44f-d38a-5690-afdd-1b7471c35b84', 'c2224aea-a81d-5102-ae97-a766d2b78ed3', 'fdeec2da-e9a7-5abd-a570-a7260f03bcce', 17, 17, 'ባይመለሱ ግን ያን ሕዝብ እነቅለዋለሁ፤ አስወግደዋለሁ፤ አጠፋውማለሁ፤” ይላል እግዚአብሔር።'),
  ('6bdded87-70d2-5ac9-a808-b8dfb1660c7f', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 1, 1, 'እግዚአብሔር እንዲህ ይለኛል፦ ሂድ፥ ከተልባ እግር የተሠራችን መታጠቂያ ለአንተ ግዛ፤ ወገብህንም ታጠቅባት፤ በውኃውም ውስጥ አትንከራት።'),
  ('71648734-8e9e-54a4-aaa8-f3110ef725a1', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 2, 2, 'እግዚአብሔርም እንዳለኝ የተልባ እግር መታጠቂያን ገዛሁ፤ ወገቤንም ታጠቅሁባት።'),
  ('0890cdf6-2b8f-5300-a9b6-b3dee0c33e53', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 3, 3, 'ዳግመኛም እግዚአብሔር እንዲህ ብሎ ተናገረኝ፦'),
  ('217f91ca-1523-5095-a755-4405b12ccc8d', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 4, 4, '“ለወገብህ የገዛሃትን ያቺን መታጠቂያ ወስደህ ተነሥ፤ ወደ ኤፍራጥስም ሂድ፤ በዚያም በተሰነጠቀ ዓለት ውስጥ ሸሽጋት።”'),
  ('a66a82d2-63a7-58d3-a8d8-585d43029b1f', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 5, 5, 'እግዚአብሔርም እንዳዘዘኝ ሄድሁ፤ በኤፍራጥስም ወንዝ አጠገብ ሸሸግኋት።'),
  ('b11f3ca5-9695-569e-a836-8aa09f5d73f1', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 6, 6, 'ከብዙ ቀንም በኋላ እግዚአብሔር፥ “ተነሥተህ ወደ ኤፍራጥስ ሂድ፥ በዚያም ትሸሽጋት ዘንድ ያዘዝሁህን መታጠቂያ ከዚያ ውስጥ ውሰድ” አለኝ።'),
  ('f92503c3-fc6a-5cdb-a34a-141b9fab32aa', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 7, 7, 'እኔም ወደ ኤፍራጥስ ወንዝ ሄድሁ፤ ቈፈርሁም፤ ከቀበርሁበትም ስፍራ መታጠቂያዪቱን ወሰድሁ። እነሆም መታጠቂያዪቱ ተበላሽታ ነበር፤ ለምንም አልረባችም።'),
  ('ba5830e4-196c-560b-ae21-36b1a045bc1f', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 8, 8, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፤'),
  ('338f60df-c9c7-58b9-aa47-180be204377b', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 9, 9, 'እግዚአብሔር እንዲህ ይላል፥ “እንዲሁ የይሁዳን ትዕቢት፥ ታላቁንም የኢየሩሳሌምን ትዕቢት አበላሻለሁ።'),
  ('0f81e284-e065-5228-aa77-81274104f76a', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 10, 10, 'ቃሌን ይሰሙ ዘንድ እንቢ የሚሉ፥ በክፉ ልባቸውም እልከኝነት የሚሄዱ፥ ያገለግሏቸውና ይሰግዱላቸው ዘንድ ሌሎችን አማልክት ተከትለው የሚሄዱ እነዚህ ክፉ ሕዝብ አንዳች እንደማትረባ እንደዚች መታጠቂያ ይሆናሉ።'),
  ('4bec5cea-5b8e-5192-a6a1-1ce84c2405d1', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '9ed1c441-df24-52b2-a020-98e8a12adbda', 11, 11, 'መታጠቂያ በሰው ወገብ ላይ እንደምትጣበቅ፥ እንዲሁ ለስም፥ ለመመኪያና ለክብር ሕዝብ ይሆኑልኝ ዘንድ የእስራኤልን ቤት ሁሉ፥ የይሁዳንም ቤት ሁሉ ከእኔ ጋር አጣብቄአለሁ፥ ይላል እግዚአብሔር፤ ነገር ግን አልሰሙም።”'),
  ('b8ebab51-07dd-5c94-a626-44d088f04c57', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '1b022b4f-d958-5fa5-a4b4-4007e1d79899', 1, 12, 'ስለዚህ፦ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “ማድጋ ሁሉ የወይን ጠጅ ይሞላል” ብለህ ትነግራቸዋለህ፤ እነርሱም፥ “ማድጋ ሁሉ የወይን ጠጅ እንዲሞላ በውኑ እኛ አናውቅምን?” ቢሉህ፤'),
  ('979426a4-9a02-56ab-acff-ff35453bc650', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '1b022b4f-d958-5fa5-a4b4-4007e1d79899', 2, 13, 'አንተም እንዲህ ትላቸዋለህ፥ “እግዚአብሔር እንዲህ ይላል፦ እነሆ በዚህች ምድር የሚኖሩትን ሁሉ፥ በዳዊት ዙፋን የሚቀመጡትን ነገሥታት፥ ካህናቱንም፥ ነቢያቱንም፥ በይሁዳና በኢየሩሳሌምም የተቀመጡትን ሁሉ በስካር እሞላቸዋለሁ።'),
  ('8557b566-7fe5-5a18-aa17-1b23e63af89e', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', '1b022b4f-d958-5fa5-a4b4-4007e1d79899', 3, 14, 'ሰውንና ወንድሙን፥ አባቶችንና ልጆችን በአንድ ላይ እበትናቸዋለሁ፥ ይላል እግዚአብሔር፤ አጠፋቸዋለሁ እንጂ አልራራላቸውም፤ አላዝንላቸውም፤ አልምራቸውምም።”'),
  ('767aab32-8145-52a6-a728-ade1981e08e5', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 1, 15, 'ስሙ፤ አድምጡ፤ እግዚአብሔር ተናግሮአልና አትታበዩ።'),
  ('b6166d37-384e-5f2e-aefc-0a100586207f', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 2, 16, 'ሳይጨልምባችሁ፥ ጨለማም ባለባቸው ተራሮች እግሮቻችሁ ሳይሰነካከሉ ለአምላካችሁ ለእግዚአብሔር ክብርን ስጡ፤ በዚያም የሞት ጥላ አለና በጨለማውም ውስጥ ያኖራችኋልና ብርሃንን ተስፋ ታደርጋላችሁ።'),
  ('7abb5ad0-8b9a-588c-a4e5-6ca8b2f7ff97', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 3, 17, 'ይህን ባትሰሙ ነፍሴ ስለ ትዕቢታችሁ በስውር ታለቅሳለች፤ የእግዚአብሔርም መንጋ ተሰብሮአልና ዐይኔ ታነባለች፤ እንባንም ታፈስሳለች።'),
  ('64eb44fc-f76c-558d-ade5-b77fc2b2ca79', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 4, 18, 'ለነገሥታቱና ለመኳንንቱ፦ የክብራችሁ አክሊል ከራሳችሁ ወርዶአልና ራሳችሁን አዋርዳችሁ ተቀመጡ በላቸው።'),
  ('e5bb82b2-b18d-5747-ac61-d13bb006b716', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 5, 19, 'የደቡብ ከተሞች ተዘግተዋል፤ የሚከፍታቸውም የለም፤ ይሁዳ ሁሉ ተሰድዶአል፤ ፈጽሞም ተሰድዶአል።'),
  ('99cca775-002e-5ee3-afb2-5d84f138fcaf', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 6, 20, 'ኢየሩሳሌም ሆይ! ዐይንሽን አንሥተሽ እነዚህን ከሰሜን የሚመጡትን ተመልከቺ፤ ለአንቺ የሰጠሁሽ መንጋ፤ የክብር በጎችሽ ወዴት አሉ?'),
  ('c61de17e-18ba-50a5-a34e-d91ab317749d', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 7, 21, 'አንቺ ትምህርት ያስተማርሻቸው አለቆችሽ ሆነው በጐበኙሽ ጊዜ ምን ትያለሽ? እንደ ወላድ ሴት ምጥ አይዝሽምን?'),
  ('cd0f314d-dba8-5c79-afa9-bc35ee467b20', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 8, 22, 'በልብሽም፦ እንዲህ ያለ ነገር ስለ ምን ደረሰብኝ? ብትዪ፥ ከኀጢአትሽ ብዛት የተነሣ ልብስሽ በስተኋላሽ ተገፎአል፤ ተረከዝሽም ተገልጦአል።'),
  ('4e183ac9-1316-5af4-ab4b-9feed8a340c3', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 9, 23, 'በውኑ ኢትዮጵያዊ መልኩን ወይስ ነብር ዝንጕርጕርነቱን ይለውጥ ዘንድ ይችላልን? በዚያ ጊዜ ክፋትን የለመዳችሁ እናንተ ደግሞ በጎ ለማድረግ ትችላላችሁን?'),
  ('5e7f0814-98e7-5b26-a35f-23ec8a2512a4', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 10, 24, 'ነፋስ በምድረ በዳ እንደሚበትነው እብቅ እበትናችኋለሁ።'),
  ('2a30df1c-bba0-5a10-a2a9-b600cc4a121b', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 11, 25, 'ረስተሽኛልና፥ በሐሰትም ታምነሻልና ዕጣሽና እድል ፈንታሽ ይህ ነው፥ ይላል እግዚአብሔር።'),
  ('35e05b3e-6b67-5aea-ad56-231428c6a212', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 12, 26, 'ስለዚህም የልብስሽን ዘርፍ በስተኋላሽ ወደ ፊትሽ እገልጣለሁ እፍረትሽም ይታያል።'),
  ('105a807d-b965-5133-a9ec-1cc88e5f7805', '5f93ca64-a943-5f91-a3aa-c0015fa74bb9', 'e1179678-89ef-5fa0-ab96-9b6adc75ae01', 13, 27, 'አስጸያፊ ሥራሽን፥ ምንዝርናሽን፥ ማሽካካትሽን፥ የዝሙትሽንም መዳራት በኮረብቶች ላይ፥ በሜዳም ላይ አይቻለሁ። ኢየሩሳሌም ሆይ! ወዮልሽ! ለመንጻት እንቢ ብለሻል፤ ይህስ እስከ መቼ ነው?'),
  ('5f3e989e-9390-5ebc-a351-36a5b143692c', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 1, 1, 'ስለ ድርቅ ወደ ኤርምያስ የመጣው የእግዚአብሔር ቃል ይህ ነው።'),
  ('d3ac627b-1e96-5845-a13b-346ac0734c1d', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 2, 2, 'ይሁዳ አለቀሰች፤ ደጆችዋም ባዶ ሆኑ፤ በምድርም ላይ ጨለሙ፤ የኢየሩሳሌምም ጩኸት ከፍ ከፍ ብሎአል።'),
  ('d6f2f0e6-4773-520e-abdc-34e7ffa11fd2', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 3, 3, 'ታላላቆችዋም ብላቴኖቻቸውን ወደ ውኃ ሰደዱ፤ ወደ ጕድጓድ መጡ፤ ውኃም አላገኙም፤ ዕቃቸውንም ባዶውን መለሱ፤ ዐፈሩም፤ ተዋረዱም፤ ራሳቸውንም ተከናነቡ።'),
  ('c09d40c4-6cbc-5486-a236-8a095512fb7e', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 4, 4, 'በምድር ላይ አልዘነበምና መሬቱ ስንጥቅጥቅ ስለ ሆነ አራሾች ዐፈሩ፤ ራሳቸውንም ተከናነቡ።'),
  ('6ab9d438-2cc2-59c0-ad17-8cf489a306c3', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 5, 5, 'ዋሊያዎች ደግሞ በምድረ በዳ ወለዱ፤ ሣርም የለምና ግልገሎቻቸውን ተዉ።'),
  ('f3c4a586-f3fd-58ee-ac07-071880dc6db6', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 6, 6, 'የሜዳ አህዮችም በወና ኮረብታ ላይ ቆመዋል፤ እንደ ሰገኖም ወደ ነፋስ አለከለኩ፤ ሣርም የለምና ዐይኖቻቸው ጠወለጉ።'),
  ('7fd743b2-d571-59f4-a6ac-9aac6f3ae5af', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 7, 7, 'አቤቱ! ኀጢአታችን ብዙ ነውና፥ በአንተም ላይ ኀጢአት ሠርተናልና ኀጢአታችን ተቃውሞናል፤ ነገር ግን ስለ ስምህ ብለህ አድርግ።'),
  ('661c3e72-71b1-5bfa-a5af-770c71dec89f', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 8, 8, 'ጌታ ሆይ! አንተ የእስራኤል ተስፋ ነህ፤ በመከራም ጊዜ ታድነዋለህ፤ በምድር እንደ እንግዳ፥ ወደ ማደሪያም ዘወር እንደሚል መንገደኛ ስለ ምን ትሆናለህ?'),
  ('e0dd6be0-af48-58e1-aeab-669efc7597ac', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 9, 9, 'እንዳንቀላፋ ሰው፥ ያድንም ዘንድ እንደማይችል ኀያል ስለ ምን ትሆናለህ? አንተ ግን አቤቱ! በመካከላችን ነህ፤ ስምህም በእኛ ላይ ተጠርትዋል፤ አትርሳንም።'),
  ('4f979e45-9399-5555-a959-9399872af369', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 10, 10, 'እግዚአብሔር ለዚህ ሕዝብ እንዲህ ይላል፥ “መቅበዝበዝን ወድደዋል፤ እግራቸውንም አልከለከሉም፤ ስለዚህ እግዚአብሔር በእነርሱ ደስ አይለውም፤ በደላቸውንም አሁን ያስባል፤ ኀጢአታቸውንም ይጐበኛል።”'),
  ('b7d55faa-3662-58d3-a266-a3a687b40613', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 11, 11, 'እግዚአብሔርም አለኝ፥ “ለዚህ ሕዝብ ስለ መልካም አትጸልይላቸው።'),
  ('239e778b-b647-5ecc-ab4a-9508cc60eb77', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 12, 12, 'ቢጾሙ ጸሎታቸውን አልሰማም፤ የሚቃጠለውን መሥዋዕትና የእህሉን ቍርባን ቢያቀርቡም ደስ አልሰኝባቸውም፤ በሰይፍና በራብ በቸነፈርም አጠፋቸዋለሁ።”'),
  ('1c5d94ce-2f8b-5246-a99d-cf1f6048fa42', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 13, 13, 'እኔም፥ “ጌታ እግዚአብሔር ሆይ! ወዮ! እነሆ ነቢያት፦ እውነትንና ሰላምን በዚህ ስፍራ እሰጣችኋለሁ እንጂ ሰይፍን አታዩም፤ ራብም አያገኛችሁም ይሉአቸዋል” አልሁ።'),
  ('362151d6-0fa4-5988-a1e1-c456a73cfcf1', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 14, 14, 'እግዚአብሔርም እንዲህ አለኝ፥ “ነቢያቱ በስሜ የሐሰት ትንቢት ይናገራሉ፤ አላክኋቸውም፤ አላዘዝኋቸውም፤ አልተናገርኋቸውም፤ የሐሰቱን ራእይ፥ ምዋርትንም፥ ከንቱንም ነገር፥ በልባቸውም የፈጠሩትን ይተነብዩላችኋል።”'),
  ('a6526379-413f-5be2-a6fa-ef354ec57fe7', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 15, 15, 'ስለዚህ እግዚአብሔር በስሜ የሐሰት ትንቢት ስለሚናገሩ ነቢያት ስላላክኋቸው፦ በዚህች ሀገር ሰይፍና ረሃብ አይሆንም ስለሚሉ ነቢያት እንዲህ ይላል፥ “እነዚያ ነቢያት በሰይፍና በራብ ይጠፋሉ።'),
  ('e77126b6-c2fe-55ed-a966-340eee49dcfb', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 16, 16, 'ትንቢት የሚናገሩላቸውም ሰዎች ከራብና ከሰይፍ የተነሣ በኢየሩሳሌም መንገዶች ይበተናሉ፤ ክፋታቸውንም አፈስስባቸዋለሁና እነርሱንና ሚስቶቻቸውን፥ ወንዶችና ሴቶች ልጆቻቸውንም የሚቀብራቸው አይገኝም።'),
  ('ef18c2f9-3929-5912-a483-7ffe9508e627', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 17, 17, '“እንደዚህም ብለህ ትነግራቸዋለህ፦ የወገኔ ልጅ ድንግሊቱ በታላቅ ስብራትና እጅግ ክፉ በሆነ ቍስል ተሰብራለችና ዐይኖቻችሁ ሌሊትና ቀን ሳያቋርጡ እንባን ያፍስሱ።'),
  ('85006c3c-a4db-55b8-ab00-d4669b3eda5a', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '9828e734-33eb-59cd-a5bc-a261b1a2df0c', 18, 18, 'ወደ ሜዳ ብወጣ፥ እነሆ በሰይፍ የሞቱ አሉ፤ ወደ ከተማም ብገባ፥ እነሆ በራብ የከሱ አሉ፤ ነቢዩና ካህኑ ወደማያውቋት ሀገር ሄደዋልና።”'),
  ('afe87b87-af0c-52ee-a9ee-d10641269392', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '0e5e2296-b2cf-5ca7-a112-105bdf83d751', 1, 19, 'በውኑ ይሁዳን ፈጽመህ ጥለኸዋልን? ነፍስህስ ጽዮንን ጠልታታለችን? ስለ ምን መታኸን? ፈውስስ ስለ ምን የለንም? ስለ ምን ተስፋ አደረግን? ነገር ግን መልካም ነገር አልተገኘም፤ የፈውስን ጊዜ ተስፋ አደረግን፤ ነገር ግን ድንጋጤ ሆነ።'),
  ('3e7681fd-c8b6-5aa5-af6c-e08770b1c971', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '0e5e2296-b2cf-5ca7-a112-105bdf83d751', 2, 20, 'አቤቱ በአንተ ላይ ኀጢአትን ሠርተናልና ክፋታችንንና የአባቶቻችንን በደል እናውቃለን።'),
  ('0aaf6348-aa9e-5504-ac30-b2184c151f03', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '0e5e2296-b2cf-5ca7-a112-105bdf83d751', 3, 21, 'ስለ ስምህ ብለህ ተመለስልን፤ የክብርህንም ዙፋን አታጥፋ፤ ከእኛ ጋርም ያደረግኸውን ቃል ኪዳንህን አስብ እንጂ አታፍርስ።'),
  ('3945906d-8521-5d2b-a7cc-03bf15649813', '15cb0d80-bf3e-5cdd-af8c-11a84f853cdd', '0e5e2296-b2cf-5ca7-a112-105bdf83d751', 4, 22, 'በውኑ በአሕዛብ ጣዖታት መካከል ያዘንብ ዘንድ የሚችል ይገኛልን? ወይስ ሰማይ ዝናብ ሊሰጥና ሊያጠግብ ይችላልን? አቤቱ አምላካችን ሆይ አንተ አይደለህምን? አንተ ይህን ነገር ሁሉ አድርገሃልና ስለዚህ አንተን በተስፋ እንጠባበቃለን።'),
  ('5678b783-32ae-5623-a1ff-01d646500691', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 1, 1, 'እግዚአብሔርም እንዲህ አለኝ፥ “ሙሴና ሳሙኤል በፊቴ ቢቆሙም፥ ልቤ ወደዚህ ሕዝብ አያዘነብልም፤ እነዚህን ሕዝቦች ከፊቴ አባርራቸው፤ ይውጡ።'),
  ('030b58ff-54df-53a1-a9c3-b30a2e0f5a6c', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 2, 2, 'እነርሱም፦ ወዴት እንሂድ ቢሉህ፥ አንተ እግዚአብሔር እንዲህ ይላል፦ ለሞት የሆነ ወደ ሞት፥ ለሰይፍም የሆነ ወደ ሰይፍ፥ ለራብም የሆነ ወደ ራብ፥ ለምርኮም የሆነ ወደ ምርኮ ትላቸዋለህ።'),
  ('5e2c8c0f-672e-5246-a193-d0e51ff68fa1', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 3, 3, 'ሰይፍን ለመግደል፥ ውሾችንም ለመጐተት፥ የሰማያትንም ወፎች፥ የምድርንም አራዊት ለመብላትና ለማጥፋት፥ አራቱን ዓይነት ጥፋት አዝዝባቸዋለሁ፥ ይላል እግዚአብሔር።'),
  ('146036b8-d027-50a6-a6c9-a5f3cdc558f3', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 4, 4, 'የይሁዳ ንጉሥ የሕዝቅያስ ልጅ ምናሴ በኢየሩሳሌም ስለ አደረገው ሁሉ በምድር መንግሥታት ሁሉ መካከል ለመከራ አሳልፌ እሰጣቸዋለሁ።'),
  ('0fffdde9-26bf-5b33-a2d2-bbe536aa14fb', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 5, 5, '“ኢየሩሳሌም ሆይ! የሚራራልሽ ማን ነው? የሚያዝንልሽስ ማን ነው? ወይስ ስለ ደኅንነትሽ ይጠይቅ ዘንድ ፈቀቅ የሚል ማን ነው?'),
  ('aad36ead-9ce2-5bb6-af77-132efa7f5157', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 6, 6, 'አንቺ እኔን ከድተሽኛል፤ እኔንም መከተል ትተሻል፤ ይላል እግዚአብሔር፤ ወደ ኋላሽም ተመልሰሻል፤ ስለዚህ እጄን በአንቺ ላይ ዘርግቼ አጠፋሻለሁ፤ ይቅርም አልላቸውም።'),
  ('3327e600-c2d9-5f5f-ad7f-898515b0491e', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 7, 7, 'ሕዝቤንም ወደ ዳርቻ ፈጽሜ እበትናቸዋለሁ፤ የወላድ መካን አድርጌአቸዋለሁ፤ ሕዝቤንም ስለ ኀጢአታቸው አጥፍቻቸዋለሁ፤ ከመንገዳቸውም አልተመለሱም።'),
  ('a51b37c5-f073-56ea-a3b3-f4b8bc056a14', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 8, 8, 'መበለቶቻቸውም ከባሕር አሸዋ ይልቅ በዝተዋል፤ በብላቴኖች እናት ላይ በቀትር ጊዜ አጥፊውን አምጥቻለሁ፤ ጭንቀትንና ድንጋጤን በድንገት አምጥቼባታለሁ።'),
  ('ab11cbc4-075b-5276-a858-52c837acffee', '3e66b509-fb21-5cab-a535-9272f870405b', 'f3320312-c886-5816-a4f8-f90fe8dba1a6', 9, 9, 'ሰባት የወለደች ባዶ ቀረች፤ ነፍስዋም ተጨንቃለች፤ በቀትር ጊዜ ፀሐይዋ ገብታባታለች፤ አፍራለች፤ ተዋርዳማለች፤ የተረፉትንም በጠላቶቻቸው ፊት ለሰይፍ አሳልፌ እሰጣለሁ፥” ይላል እግዚአብሔር።'),
  ('e0cc1312-9620-536a-a8ad-f6bd50b2228b', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 1, 10, 'እናቴ ሆይ! ለምድር ሁሉ የክርክርና የጥል ሰው የሆንሁትን እኔን ወልደሽኛልና ወዮልኝ! ለማንም አልጠቀምሁም፤ ማንም እኔን አልጠቀመኝም፤ ከሚረግሙኝም የተነሣ ኀይሌ አለቀ።'),
  ('3b577494-5731-58b5-a0ed-e7684b8243ca', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 2, 11, 'አቤቱ! በመከራቸውና በጭንቃቸው ጊዜ በጠላቶቻቸው ዘንድ ስለ እነርሱ በጎ ነገር በአንተ ፊት የቆምሁ ባልሆን ይህ ለእነርሱ መከናወን ይሁን።'),
  ('4cbbd0a3-340a-597b-a0c2-bff2a11310fc', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 3, 12, 'በውኑ ብረትን፥ የሰሜንን ብረት፥ ናስንም የሚሰብር አለን?'),
  ('033b34a8-77e9-5532-a0aa-4e5cbdc1e069', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 4, 13, 'በዳርቻህ ሁሉ ስላለ ኀጢአትህ ሁሉ ፋንታ ባለጠግነትህንና መዝገብህን ለመበዝበዝ በከንቱ እሰጣለሁ።'),
  ('9437c3f1-d500-5755-ae8b-8f04c0b0af43', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 5, 14, 'እሳት ከቍጣዬ ትነድዳለችና፥ እናንተንም ታቃጥላችኋለችና በማታውቀው ሀገር ለጠላቶችህ አስገዛሃለሁ።'),
  ('2b94e906-230e-5897-a09b-c40106dc4a9b', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 6, 15, 'አቤቱ! አንተ ታውቃለህ፤ አስበኝ፤ ጐብኘኝም፤ ከሚያሳድዱኝም አድነኝ እንጂ፥ አትታገሣቸው፤ ስለ አንተ እንደ ሰደቡኝ አስብ።'),
  ('3a84c980-0d93-5a0e-a58b-f146d33180db', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 7, 16, 'ቃልህ ተገኝቶአል፤ እኔም በልችዋለሁ፤ አቤቱ! የሠራዊት አምላክ ሆይ! ቃልህን የከዱ ሰዎችን አጥፋቸው፤ ስምህ በእኔ ላይ ተጠርትዋልና፥ ቃልህ ሐሤትና የልብ ደስታ ሆነኝ።'),
  ('8cd83072-f17d-5c86-a12d-2d77220d1322', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 8, 17, 'በዋዘኞች ጉባኤ አልተቀመጥሁም፤ ነገር ግን በእጅህ ፊት ፈርቻለሁ፤ ምሬትን ሞልተህብኛልና ለብቻዬ ተቀመጥሁ።'),
  ('ee715ecb-f51e-5b03-a965-8c2106c87037', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 9, 18, 'የሚያሳዝኑኝ በእኔ ላይ ለምን ይበረታሉ? ቍስሌስ ስለ ምን የማይፈወስ ሆነ? ስለ ምንስ አልሽርም አለ? እንደ ሐሰተኛ ምንጭ፥ እንዳልታመነች ውኃም ሆነብኝ።'),
  ('5bc86dc1-01e0-5516-a641-9e27534352f0', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 10, 19, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ ብትመለስ እመልስሃለሁ፤ በፊቴም ትቆማለህ፤ የከበረውንም ከተዋረደው ብትለይ እንደ አፌ ትሆናለህ፤ እነርሱ ወደ አንተ ይመለሳሉ፤ አንተ ግን ወደ እነርሱ አትመለስም።'),
  ('6a08f7e1-4d0e-5139-ae80-d3e490851493', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 11, 20, 'ለዚህም ሕዝብ የተመሸገ የናስ ቅጥር አደርግሃለሁ፤ ይዋጉሃል፤ እኔ ግን ለማዳን ከአንተ ጋር ነኝና አያሸንፉህም።'),
  ('c3f6e08e-7ccb-52a2-a7bc-e6527b987a47', '3e66b509-fb21-5cab-a535-9272f870405b', 'c925609d-92b8-59df-a2a7-0f2635ec9df5', 12, 21, 'ከክፉ ሰዎችም እጅ እታደግሃለሁ፤ ከጨካኞችም ጡጫ እቤዥሃለሁ።'),
  ('7043dbac-34a9-5725-a0e5-0d41e4b264d2', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 1, 1, 'የእግዚአብሔር ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('42d509f4-69b5-542a-ab6c-bb8769137adb', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 2, 2, 'በዚህ ስፍራ ሚስት አታግባ፥ ወንዶችና ሴቶች ልጆችንም አትውለድ።'),
  ('c6b7058b-458e-595c-ac82-1d909d35dee8', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 3, 3, 'እግዚአብሔር በዚህ ስፍራ ስለ ተወለዱ ወንዶችና ሴቶች ልጆች፥ ስለ ወለዱአቸውም ስለ እናቶቻቸው፥ በዚህችም ምድር ስለ ወለዱአቸው ስለ አባቶቻቸው እንዲህ ይላልና፦'),
  ('a356846a-5d11-522e-a7ae-5d615f98b0dd', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 4, 4, '“በክፉ ሞት ይሞታሉ፤ አይለቀስላቸውም፤ አይቀበሩምም፤ ነገር ግን በመሬት ላይ እንደ ጕድፍ ይሆናሉ፤ በሰይፍም ይወድቃሉ፤ በራብም ይጠፋሉ፤ ሬሳዎቻቸውም ለሰማይ ወፎችና ለዱር አራዊት መብል ይሆናሉ።”'),
  ('2fe76853-b7b2-5824-a15f-175f227a9789', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 5, 5, 'እግዚአብሔር እንዲህ ይላል፥ “ሰላሜን፥ ቸርነቴንና ምሕረቴን፥ ከዚህ ሕዝብ አስወግጄአለሁና ልቅሶ ወዳለበት ቤት አትግባ፤ ታለቅስና ታዝንም ዘንድ አትሂድ።'),
  ('d8d4e790-e790-5d67-ac67-bf280c77c53c', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 6, 6, 'ታላላቆችና ታናናሾች በዚች ምድር ይሞታሉ ፥ አይቀበሩም ሰዎችም አያለቅሱላቸውም፤ ስለ እነርሱም ፊት አይነጩላቸውም፤ ራስንም አይላጩላቸውም፤'),
  ('3b5b5339-4627-56a2-a29b-8d83cda3e8ed', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 7, 7, 'ሰዎችም ስለ ሞቱት ለማጽናናት የእዝን እንጀራ አይቈርሱላቸውም፤ ስለ አባታቸውና ስለ እናታቸውም የመጽናናት ጽዋ አያጠጡአቸውም።'),
  ('08c7cddb-96fc-586c-ae9f-785c835ab97d', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 8, 8, 'ትበላና ትጠጣ ዘንድ ከእነርሱ ጋር ለመቀመጥ ወደ ግብዣ ቤት አትግባ።”'),
  ('4151e9ba-d3a5-5545-aec6-83ab6fb42e18', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 9, 9, 'ስለዚህም የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በዐይናችሁ ፊት በዘመናችሁም የእልልታን ድምፅና የደስታን ድምፅ፥ የወንድ ሙሽራን ድምፅና የሴት ሙሽራን ድምፅ ከዚህ ስፍራ አስቀራለሁ።'),
  ('b40eb2a1-1db3-5bc9-af5d-12d468328a30', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 10, 10, '“ለዚህም ሕዝብ ይህን ቃል ሁሉ በተናገርህ ጊዜ፦ ይህን ሁሉ ትልቅ የሆነ ክፉ ነገርን ስለ ምን እግዚአብሔር ተናገረብን? በደላችንስ ምንድን ነው? በአምላካችንስ በእግዚአብሔር ፊት ያደረግነው ኀጢአት ምንድን ነው? ቢሉህ፥'),
  ('5dc40d44-a367-590e-aae3-d4a1504e8b70', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 11, 11, 'አንተ እንዲህ ትላቸዋለህ፦ አባቶቻችሁ እኔን ስለ ተዉ ነው፥ ይላል እግዚአብሔር፤ ሌሎችንም አማልክት ተከተሉ፤ አመለኩአቸውም፤ ሰገዱላቸውም፤ እነርሱም ትተውኛል፤ ሕጌንም አልጠበቁም፤'),
  ('5dc51ff3-fe1a-597a-a87d-1eb5e4e116a7', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 12, 12, 'እናንተም ከአባቶቻችሁ ይልቅ ክፉ አድርጋችኋል፤ እነሆም ሁላችሁ እንደ ክፉ ልባችሁ ፍላጎት ሄዳችኋል፤ እኔንም አልሰማችሁም።'),
  ('0d20b81b-50b6-5280-a89e-0e22a491601b', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '270de1b2-7aae-54c2-af53-3fb18d5eab9a', 13, 13, 'ስለዚህ ከዚች ምድር እናንተና አባቶቻችሁ ወደ አላወቃችኋት ምድር እጥላችኋለሁ፤ በዚያም ምሕረትን ለማያደርጉላችሁ ሌሎች አማልክት ቀንና ሌሊት ታገለግላላችሁ።”'),
  ('8c488dab-8067-54fa-ab9f-4d500eb3b652', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '1b21d596-03aa-5403-a9bb-e98df97f9f7a', 1, 14, 'ስለዚህ እነሆ፥ “የእስራኤልን ልጆች ከግብፅ ምድር ያወጣ ሕያው እግዚአብሔርን! ዳግመኛ የማይባልበት ዘመን ይመጣል፥” ይላል እግዚአብሔር፤'),
  ('a93bcc86-a26c-5e61-ad58-7e04cfed3bc9', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', '1b21d596-03aa-5403-a9bb-e98df97f9f7a', 2, 15, 'ነገር ግን፥ “የእስራኤልን ልጆች ከሰሜን ምድር፥ ከተሰደዱበትም ምድር ሁሉ ያወጣ ሕያው እግዚአብሔርን! ይባላል፤ እኔም ለአባቶቻቸው ወደ ሰጠኋት ወደ ምድራቸው እመልሳቸዋለሁ።'),
  ('118aed5f-d92f-5190-a5b0-2e90b64af20a', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf9a110a-f654-5e4b-a397-eaa5bee59647', 1, 16, '“እነሆ፥ ብዙ ዓሣ አጥማጆችን እልካለሁ፥” ይላል እግዚአብሔር፤ እነርሱም ያጠምዱአቸዋል፤ ከዚያም በኋላ ብዙ አድዳኞችን እልካለሁ፤ እነርሱም ከየተራራውና ከየኮረብታው ሁሉ ከየድንጋዩም ስንጣቂ ውስጥ ያድድኑአቸዋል።'),
  ('963c7659-bfbe-55a9-a928-6a2422c53788', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf9a110a-f654-5e4b-a397-eaa5bee59647', 2, 17, 'ዐይኖች በመንገዳቸው ሁሉ ይመለከታሉ፤ ከፊቴም አልተሰወሩም፤ ኀጢአታቸውም ከዐይኖች አልተሸሸገም።'),
  ('344fbacc-b65b-5c83-aec4-067ad63d7cdb', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf9a110a-f654-5e4b-a397-eaa5bee59647', 3, 18, 'ምድሬንም በተጠሉ በጣዖቶቻቸው ሬሳዎች አርክሰዋልና፥ ርስቴንም አስጸያፊ በሆኑ ነገሮች ሞልተዋልና አስቀድሜ የበደላቸውንና የኀጢአታቸውን ዕዳ ሁለት እጥፍ እከፍላቸዋለሁ።”'),
  ('eeb1c530-8190-5482-a96e-885dd33269bf', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf5e597e-c277-5092-ac0b-64f720a79ff8', 1, 19, 'ጌታ ሆይ! አንተ ኀይሌና ረዳቴ፥ በመከራም ቀን መጠጊያዬ ነህ፤ ከምድር ዳርቻ አሕዛብ ወደ አንተ መጥተው፥ “በእውነት አባቶቻችን ውሸትንና ከንቱን ነገር ለምንም የማይረባቸውን ጣዖትን ሠርተዋል” ይላሉ።'),
  ('c09a9e25-a731-597a-a597-d12c7e018903', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf5e597e-c277-5092-ac0b-64f720a79ff8', 2, 20, 'በውኑ ሰው አማልክት ያልሆኑትን ለራሱ አማልክትን አድርጎ ይሠራልን?'),
  ('6d44fd62-ec86-55d1-aff7-55c803aed1da', '3beaf5ea-9e1f-5726-a993-8a4f12dd95e9', 'bf5e597e-c277-5092-ac0b-64f720a79ff8', 3, 21, '“ስለዚህ እነሆ በዚህ ወራት አስታውቃቸዋለሁ፤ እጄንና ኀይሌንም አሳያቸዋለሁ፤ እነርሱም ስሜ እግዚአብሔር እንደ ሆነ ያውቃሉ።”'),
  ('dbc8f2f3-cb82-5d54-a841-019400d3d3c0', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 1, 1, 'የይሁዳ ኀጢአት በብረት ብርዕ በደንጊያ ሰሌዳ ተጽፎአል፤ በልባቸው ጽላትና በመሠዊያቸው ቀንዶችም ተቀርጾአል።'),
  ('ab4679fe-f5f3-5093-a791-95ab4e83de77', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 2, 2, 'ልጆቻቸውም ከለመለሙ ዛፎች በታችና በረዘሙት ኮረብቶች ላይ ያሉትን መሠዊያቸውንና የማምለኪያ ዐፀዳቸውን ያስባሉ።'),
  ('48b2a9ef-f058-55e9-a48a-f2a3bfbe3181', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 3, 3, 'በሜዳ ያለው ተራራዬ ሆይ! ባለጠግነትህንና መዝገብህን ሁሉ፥ የኮረብታውን መስገጃዎችህንም ስለ ኀጢአትህ በድንበሮችህ ሁሉ ለመበዝበዝ እሰጣለሁ።'),
  ('b478cb73-13d8-5e5a-a6bf-e505089f11d0', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 4, 4, 'አንተም የሰጠሁህን ርስት ትለቅቃለህ፤ ለዘለዓለምም በማታውቃት ምድር ለጠላቶችህ አስገዛሃለሁ፤ ቍጣዬ ለዘለዓለም እንደ እሳት ትነድዳለችና።'),
  ('8bd6b99b-ed22-5667-adbf-b20807428992', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 5, 5, 'እግዚአብሔር እንዲህ ይላል፥ “በሰው የሚታመን የሥጋ ክንዱንም በእርሱ የሚያስደግፍ፥ ልቡም ከእግዚአብሔር የሚርቅ ሰው ርጉም ነው።'),
  ('2c1c9e88-9cef-581a-aa62-015f8acef925', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 6, 6, 'በምድረ በዳ እንደ አለ ቍጥቋጦ ይሆናል፤ መልካምም በመጣ ጊዜ አያይም፤ ሰውም በማይኖርበት፥ ጨው ባለበት ምድር በምድረ በዳ በደረቅ ስፍራ ይቀመጣል።'),
  ('17fbb6ac-108d-553f-a784-877f088f408b', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 7, 7, 'በእግዚአብሔር የሚታመን፥ ተስፋውም እግዚአብሔር የሆነ ሰው ቡሩክ ነው።'),
  ('a31642fa-d4dc-54ba-a15d-0b2a5688f1c7', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 8, 8, 'በውኃ አጠገብ እንደ ተተከለ፥ በወንዝም ዳር ሥሩን እንደሚዘረጋ፥ ሙቀትም ሲመጣ እንደማይፈራ፥ ቅጠሉም እንደሚለመልም፥ በድርቅ ዓመትም እንደማይሠጋ ፍሬውንም እንደማያቋርጥ ዛፍ ይሆናል።'),
  ('ae513830-e15e-571b-a7e1-f4de670242ec', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 9, 9, '“የሰው ልብ ከሁሉ ይልቅ ጥልቅ ነው፤ ማንስ ያውቀዋል?'),
  ('f24c02d0-af5c-5ae9-a171-84d835f3515e', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 10, 10, 'እኔ እግዚአብሔር ለሰው ሁሉ እንደ መንገዱና፥ እንደ ሥራው ፍሬ እሰጥ ዘንድ ልብን እመረምራለሁ፤ ኵላሊትንም እፈትናለሁ።”'),
  ('ac76660c-9860-53a5-a25a-94f947463621', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 11, 11, 'ቆቅ ጮኸች፤ ያልወለደችውንም ዐቀፈች፤ በዐመፅ ባለጠግነትን የሚሰበስብ ሰውም እንደዚሁ ነው፤ በእኩሌታ ዘመኑ ይተወዋል፤ በፍጻሜውም ሰነፍ ይሆናል።'),
  ('1f05aa84-8282-5e97-a9d6-a5bf62785f71', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 12, 12, 'የመቅደሳችን ስፍራ ከጥንት ጀምሮ ከፍ ያለ የክብር ዙፋን ነው።'),
  ('8fb24734-00be-527e-af45-746827d8493a', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 13, 13, 'አቤቱ! የእስራኤል ተስፋ ሆይ! የሚተዉህ ሁሉ ያፍራሉ፤ ከአንተም የሚለዩ የሕይወትን ውኃ ምንጭ እግዚአብሔርን ትተዋልና በምድር ላይ ይጻፋሉ።'),
  ('ec672377-3718-5c2a-ac1b-95517d744bc3', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 14, 14, 'አቤቱ! ፈውሰኝ፤ እኔም እፈወሳለሁ፤ አድነኝ፤ እኔም እድናለሁ፤ አንተ መመኪያዬ ነህና።'),
  ('0b903097-396d-54b0-abc5-933fe5686d85', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 15, 15, 'እነሆ የእግዚአብሔር ቃል ወዴት አለ? አሁን ይምጣ ይሉኛል።'),
  ('5406c926-5291-5f46-a0b6-e89b90226e82', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 16, 16, 'እኔም አንተን ተከትዬ አልደከምሁም፥ የሰውንም ቀን አልተመኘሁም፤ አንተ ታውቃለህ፤ ከከንፈሬ የወጣውም በፊትህ ነው።'),
  ('e7748d3f-e26e-5eb1-aeaf-a624dba0717d', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 17, 17, 'እንግዳ አትሁንብኝ፤ በክፉም ቀን አንተ መጠጊያዬ ነህ።'),
  ('8c4da7ab-ab60-50f9-a556-8c6aa5a0c9c3', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 18, 18, 'አሳዳጆች ይፈሩ፤ እኔ ግን አልፈር፤ እነርሱ ይደንግጡ፤ እኔ ግን አልደንግጥ፤ ክፉንም ቀን አምጣባቸው፤ በሁለት እጥፍ ጥፋት ቀጥቅጣቸው።'),
  ('0dbd743e-e98d-5837-a2f2-18a8bb6db848', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 19, 19, 'እግዚአብሔር እንዲህ ይለኛል፥ “ሂድ፤ የይሁዳም ነገሥታት በሚገቡበትና በሚወጡበት በሕዝብህ ልጆች በር በኢየሩሳሌምም በሮች ሁሉ ቁም።”'),
  ('1a62fae5-bd11-54e4-a60f-26a1779d5717', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 20, 20, 'እንዲህም በላቸው፥ “በእነዚህ በሮች የምትገቡ እናንተ የይሁዳ ነገሥታት፥ ይሁዳም ሁሉ፥ በኢየሩሳሌምም የምትኖሩ ሁሉ የእግዚአብሔርን ቃል ስሙ።”'),
  ('c78aee44-ff8c-56b5-aa5f-33f28101e7d2', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 21, 21, 'እግዚአብሔር እንዲህ ይላል፥ “ራሳችሁን ጠብቁ፥ በሰንበትም ቀን ምንም ሸክም አትሸከሙ፤ በኢየሩሳሌምም በሮች አታግቡ፤'),
  ('d52f07f0-d776-5a1a-ac53-2ab68eb47e96', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 22, 22, 'ከቤቶቻችሁ በሰንበት ቀን ሸክምን አታውጡ፤ ሥራንም ሁሉ አትሥሩ፤ አባቶቻችሁንም እንዳዘዝኋቸው የሰንበትን ቀን ቀድሱ።'),
  ('7a4eb2e3-0395-5c4b-a5d2-9650f6fe2e2f', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 23, 23, 'እነርሱ ግን አልሰሙም፤ ጆሮአቸውንም አላዘነበሉም፤ እንዳይሰሙና ተግሣጼን እንዳይቀበሉም ከአባቶቻቸው ይልቅ አንገታቸውን አደነደኑ።”'),
  ('6d8d0c65-babb-5524-a1be-81584ad547a2', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 24, 24, 'እኔን ፈጽሞ ብትሰሙ፥ ይላል እግዚአብሔር፤ በሰንበትም ቀን በዚህች ከተማ በሮች ሸክም ባታገቡ፥ የሰንበትንም ቀን ብትቀድሱ፥ ሥራንም ሁሉ ባትሠሩባት፥'),
  ('f61197fc-f055-5183-a8d9-ff9569c85800', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 25, 25, 'በዳዊት ዙፋን ላይ የሚቀመጡ ነገሥታትና መሳፍንት በሰረገሎችና በፈረሶች ላይ እየተቀመጡ በዚህች ከተማ በሮች ይገባሉ፤ እነርሱና አለቆቻቸው የይሁዳም ሰዎች፥ በኢየሩሳሌምም የሚቀመጡ ይገባሉ፤ ይህችም ከተማ ለዘለዓለም የሰው መኖሪያ ትሆናለች።'),
  ('e9d6719a-39ff-59c0-aa59-7d52678d08cf', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 26, 26, 'የሚቃጠለውን መሥዋዕትና የእህሉንም ቍርባን፥ እጅ መንሻውንና ዕጣኑን፥ የምስጋናውንም መሥዋዕት ይዘው ከይሁዳ ከተሞችና ከኢየሩሳሌም ዙሪያ፥ ከብንያምም ሀገር፥ ከቆላውም፥ ከደጋውም፥ ከደቡብም ወደ እግዚአብሔር ቤት ይመጣሉ።'),
  ('8081a7a0-feee-598a-ac3e-be7864f682ed', 'bceeac36-05f8-5dfb-a3a4-ba57f5e72419', '8dce0fd3-3b3d-5e5b-a34d-999bab11e4ad', 27, 27, 'ነገር ግን የሰንበትን ቀን እንድትቀድሱ፥ በሰንበትም ቀን ሸክምን ተሸክማችሁ በኢየሩሳሌም በሮች እንዳትገቡ የነገርኋችሁን ባትሰሙኝ፥ በበሮችዋ ላይ እሳትን አነድዳለሁ፤ የኢየሩሳሌምንም ግንቦች ትበላለች፤ አትጠፋምም።'),
  ('e00a8643-517f-564d-af34-0ae98969bfff', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 1, 1, 'ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል፥ እንዲህም አለው፦'),
  ('b23f4573-b509-5d8a-a35e-2c656c899ffe', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 2, 2, '“ተነሥተህ ወደ ሸክላ ሠሪው ቤት ውረድ፤ በዚያም ቃሌን አሰማሃለሁ።”'),
  ('13aae70a-0510-5020-afae-6ad66ea69d74', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 3, 3, 'ወደ ሸክላ ሠሪውም ቤት ወረድሁ፤ እነሆም ሥራውን በዓለት ላይ ሲሠራ አገኘሁት።'),
  ('c7b53eab-264b-51f2-a3b0-14734137d29d', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 4, 4, 'ከጭቃም ይሠራው የነበረው ዕቃ ከሸክላ ሠሪው እጅ ወደቀ፤ ሸክላ ሠሪውም እንደ ወደደ ዳግመኛ ሌላ ዕቃ አድርጎ ሠራው።'),
  ('0cd47db7-0415-52ef-a630-9b50cfeff733', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 5, 5, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ።'),
  ('3c7af592-ed83-5817-a3f2-b68e2616c7b3', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 6, 6, '“የእስራኤል ቤት ሆይ! ይህ ሸክላ ሠሪ እንደሚሠራ በውኑ እኔ በእናንተ ዘንድ መሥራት አይቻለኝምን? እነሆ ጭቃው በሸክላ ሠሪ እጅ እንዳለ፥ እንዲሁ እናንተ በእኔ እጅ አላችሁ።'),
  ('342abb83-1253-5d17-a9a7-1260dbb2b6f2', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 7, 7, 'አጠፋቸውና እደመስሳቸው ዘንድ በሕዝብ ላይና በመንግሥት ላይ ቍርጥ ነገርን ተናገርሁ፤'),
  ('c627182f-2798-56c3-a3ec-c16ef5d48075', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 8, 8, 'ስለ እነርሱ የተናገርሁባቸው ሕዝብ ከክፋታቸው ቢመለሱ፥ እኔ አደርግባቸው ዘንድ ካሰብሁት ክፉ ነገር እጸጸታለሁ።'),
  ('33477777-41a7-5b41-a5cc-2aeee3f2cc3a', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 9, 9, 'በሕዝብም በመንግሥታትም ላይ እሠራቸውና እተክላቸው ዘንድ ቍርጥ ነገርን እናገራለሁ፤'),
  ('bd38ca2c-8e3b-5b05-a239-f847687a35bf', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 10, 10, 'በፊቴ ክፉን ነገር ቢያደርጉ ቃሌንም ባይሰሙ፥ እኔ አደርግላቸው ዘንድ ስለ ተናገርሁት መልካም ነገር እጸጸታለሁ።”'),
  ('2e92b742-8fc7-5358-a671-29439ec2e2b5', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 11, 11, 'አሁን እንግዲህ ለይሁዳ ሰዎችና በኢየሩሳሌም ለሚኖሩ፦ እግዚአብሔር እንዲህ ይላል፥ “እነሆ ክፉ ነገር እፈጥርባችኋለሁ፤ ምክርንም እመክርባችኋለሁ፤ አሁንም ሁላችሁ ከክፉ መንገዳችሁ ተመለሱ፤ መንገዳችሁንና ሥራችሁንም አቅኑ ብለህ ተናገራቸው።”'),
  ('5b82591c-90a7-5ddc-a421-aab08bbe78ca', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 12, 12, 'እነርሱ ግን፥ “እንጨክናለን፤ ክዳታችንን ተከትለን እንሄዳለን፥ ሁላችንም ክፉ ልባችንን ደስ የሚያሰኛትን እናደርጋለን” አሉ።'),
  ('e87bd504-26e8-57f9-a75a-3ac766c7fa58', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 13, 13, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፥ “የእስራኤል ድንግል ያደረገችውን በጣም የሚያስደነግጠውን ነገር የሚሰሙት እንዳለ አሕዛብን ጠይቁ።”'),
  ('11f542af-cbfc-540e-ae21-271292e69561', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 14, 14, 'ምንጭ ከዓለት ይጠፋልን? በረዶስ ከሊባኖስ ይጠፋልን? ወራጅ ውኃስ በኀይለኛ ነፋስ ይመለሳልን?'),
  ('d30e4191-31dc-56c4-aa78-5240922bb76d', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 15, 15, 'ሕዝቤ ግን ረስተውኛል፤ ለከንቱ ነገርም አጥነዋል፤ የቀድሞውን ጐዳና ትተው ወደ ጠማማውና ወደ ሰንከልካላው መንገድ ለመሄድ በመንገዳቸው ተሰናከሉ።'),
  ('0663887a-d3ca-5b58-a22e-169b0d79231c', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 16, 16, 'ምድራቸውን ለጥፋትና ለዘለዓለም ማፍዋጫ አድርገዋል፤ የሚያልፍባት ሁሉ ይደነቃል፤ ራሱንም ያነቃንቃል።'),
  ('340d2460-becc-5077-aea2-c2195e628adb', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', '965f3901-8961-53f9-a201-6ed2ae292550', 17, 17, 'በጠላት ፊት እንደ በረሃ ዐውሎ ነፋስ እበትናቸዋለሁ፤ በጥፋታቸውም ቀን ጀርባዬን እንጂ ፊቴን አላሳያቸውም።'),
  ('70c5aa33-8a91-5958-a71c-726d31fb7db8', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 1, 18, 'እነርሱም፥ “ሕግ ከካህን፥ ምክርም ከጠቢብ፥ ቃልም ከነቢይ አይጠፋምና ኑ፤ በኤርምያስ ላይ ምክርን እንምከር። ኑ፤ በምላስ እንምታው፤ ቃሉንም ሁሉ አናዳምጥ” አሉ።'),
  ('225129ce-3e16-5a2c-af21-6c889b1b73c9', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 2, 19, '“አቤቱ! አድምጠኝ፤ የክርክሬንም ቃል ስማ።'),
  ('79c8e9f8-61a7-5cc0-aa6f-cc2e137dd5dd', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 3, 20, 'ለሰውነቴ ጕድጓድን ቈፍረዋል፤ በውኑ በመልካም ፈንታ ክፉ ይመለሳልን? ስለ እነርሱ በመልካም እናገር ዘንድ፥ ቍጣህንም ከእነርሱ ትመልስ ዘንድ በፊትህ እንደ ቆምሁ አስብ።'),
  ('fc3729b2-bd9e-5216-a800-d845d31fc0af', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 4, 21, 'ስለዚህ ልጆቻቸውን ለራብ ስጥ፤ ለሰይፍም እጅ አሳልፈህ ስጣቸው፤ ሚስቶቻቸውም የወላድ መካንና መበለቶች ይሁኑ፤ ወንዶቻቸውም በሞት ይጥፉ፤ ጐልማሶቻቸውም በጦርነት ጊዜ በሰይፍ ይመቱ።'),
  ('c2a45756-1990-5e46-a859-0b94b20a1f0f', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 5, 22, 'ሊይዙኝ ጕድጓድ ቈፍረዋልና፥ ለእግሮችም ወጥመድ ሸሽገዋልና፥ በቤታቸው ጩኸት ይሰማ፤ ድንገትም በላያቸው ወንበዴን አምጣባቸው።'),
  ('baceed7d-8e59-5605-a8c8-abf578d306aa', '66c4052b-1cf3-55d8-a6a9-ce4410f8109c', 'f61a14e6-c36c-5403-ac0c-c647d96720c7', 6, 23, 'አንተ ግን አቤቱ! ይገድሉኝ ዘንድ በላዬ የመከሩትን ምክር ሁሉ ታውቃለህ፤ በደላቸውንም ይቅር አትበል፤ ኀጢአታቸውንም ከፊትህ አትደምስስ፤ በፊትህም ይውደቁ፤ በቍጣህ ጊዜ እንዲሁ አድርግባቸው።”'),
  ('05e0703e-d537-531f-aaf0-ccb1c1cd08d7', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 1, 1, 'እግዚአብሔርም እንዲህ አለኝ፥ “ሂድ፤ የሸክላ ሠሪ የሠራውን ገምቦ ግዛ፤ ከሕዝቡም ሽማግሌዎችና ከካህናት ሽማግሌዎች ከአንተ ጋር ውሰድ፤'),
  ('9246398a-edf6-57a8-add0-d7c44f9b11e2', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 2, 2, 'በከርሲት በር መግቢያ አጠገብ ወዳለው ወደ ሄኖም ልጅ ሸለቆ ሂድ፥ በዚያም የምነግርህን ቃል አንብብ፤ እንዲህም በል፦'),
  ('f063862d-c8ad-597e-a970-7eb407450a4f', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 3, 3, '“የይሁዳ ነገሥታትና በኢየሩሳሌም የምትኖሩ ሆይ፤ የእግዚአብሔርን ቃል ስሙ፤ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በዚህ ስፍራ ክፉ ነገርን አመጣለሁ፤ የሰማውም ሰው ሁሉ ይደነግጣል፤ ጆሮዎቹንም ይይዛል።'),
  ('0168c3e2-a142-53b2-a464-38ca807304ec', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 4, 4, 'ትተውኛልና፥ ይህንም ስፍራ እንግዳ አድርገውታልና፥ እነርሱና አባቶቻቸውም ለማያውቋቸው ለሌሎች አማልክት ዐጥነዋልና፥ የይሁዳም ነገሥታት ይህን ስፍራ በንጹሓን ደም ሞልተዋልና፥'),
  ('fb651c62-a051-5be6-a9ee-a06c61d3880e', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 5, 5, 'እኔም ያላዘዝሁትን፥ ያልተናገርሁትንም፥ ወደ ልቤም ያልገባውን የሚቃጠል መሥዋዕት አድርገው ለበዓል ልጆቻቸውን በእሳት ያቃጥሉ ዘንድ የበዓልን የኮረብታውን መስገጃዎች ሠርተዋልና፤'),
  ('61c38d82-7385-5726-a0e5-c71aa3de6aa1', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 6, 6, 'ስለዚህ እነሆ ይህ ስፍራ የእርድ ሸለቆ ይባላል እንጂ ቶፌት ወይም የሄኖም ልጅ ሸለቆ ዳግመኛ የማይባልበት ዘመን ይመጣል፥” ይላል እግዚአብሔር።'),
  ('98292ed7-fc45-5b34-ac3f-c8c79316a573', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 7, 7, 'በዚህም ስፍራ የይሁዳንና የኢየሩሳሌምን ምክር አፈርሳለሁ፤ በጠላቶቻቸው ፊት በጦርና ነፍሳቸውን በሚሹት እጅ እጥላቸዋለሁ፤ ሬሳቸውንም ለሰማይ ወፎችና ለምድር አራዊት መብል አድርጌ እሰጣለሁ።'),
  ('25aa21d8-5718-5131-a3e6-d96cbd8270b8', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 8, 8, 'ይህችንም ከተማ ለጥፋትና ለማፍዋጫ አደርጋታለሁ፤ በእርስዋም የሚያልፍ ሁሉ ስለ ተደረገባት መቅሠፍት ሁሉ ይደነግጣል፤ ያፍዋጫልም።'),
  ('bc9591ad-ed49-542c-a902-a9e2f8ac5b96', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 9, 9, 'የወንዶችና የሴቶች ልጆቻቸውንም ሥጋ አበላቸዋለሁ፤ ሁሉም እያንዳንዳቸው ጠላቶቻቸውና ነፍሳቸውን የሚሹት በሚያስጨንቋቸው ጭንቀትና መከበብ የባልንጀሮቻቸውን ሥጋ ይበላሉ።'),
  ('379666fd-8ca3-529a-af95-ba36719ec138', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 10, 10, '“ገምቦውንም ከአንተ ጋር በሚሄዱ ሰዎች ፊት ትሰብራለህ፤'),
  ('b6259194-fef0-5d4d-ac52-cb5dd093c090', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 11, 11, 'እንዲህም ትላቸዋለህ፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ የሸክላ ማድጋ እንደሚሰባበር ደግሞም ይጠገን ዘንድ እንደማይቻል፥ እንዲሁ ይህን ሕዝብና ይህችን ከተማ እሰብራለሁ፤ የሚቀበሩበትም ስፍራ ሌላ የለምና በቶፌት ይቀበራሉ።'),
  ('f2442eb8-2227-5205-a73b-50caa49c0cda', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 12, 12, 'እንዲሁ በዚህ ስፍራና በሚኖሩበት ላይ አደርጋለሁ፥ ይላል እግዚአብሔር፤ ይህችንም ከተማ እንደ ቶፌት አደርጋለሁ፤ አፈርሳታለሁም።'),
  ('03029c14-37fe-52b5-ae00-b553c1fa6232', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 13, 13, 'የኢየሩሳሌም ቤቶችና የይሁዳ ነገሥታት ቤቶች እንደ ቶፌት የረከሱ ይሆናሉ፤ እነዚያም በሰገነታቸው ላይ ለሰማይ ሠራዊት ሁሉ ያጠኑባቸው፥ ለሌሎችም አማልክት የመጠጥ ቍርባን ያፈሰሱባቸው ቤቶች ሁሉ ይፈርሳሉ።”'),
  ('d026392c-3493-5924-ad33-4da95326285d', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 14, 14, 'ኤርምያስም እግዚአብሔር ትንቢት ሊናገር ወደዚያ ልኮት ከነበረው ስፍራ ከቶፌት ተመለሰ፤ በእግዚአብሔርም ቤት አደባባይ ቆሞ ለሕዝቡ ሁሉ እንዲህ አላቸው፦'),
  ('08d3069e-df50-5963-a3a8-39df43030e96', 'efd8c35e-8909-5b51-aaa7-5febc2d196f8', 'dbcc0b85-fdfb-5f48-a24b-554bc5a04057', 15, 15, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “ቃሌን እንዳይሰሙ አንገታቸውን አደንድነዋልና እነሆ በዚች ከተማና በመንደሮችዋ ሁሉ ላይ የተናገርሁባትን ክፉ ነገር ሁሉ አመጣለሁ።”'),
  ('5b8b1dcf-ee90-54e2-ae71-a3945d7536f4', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 1, 1, 'በእግዚአብሔርም ቤት የተሾመው አለቃ የካህኑ የኢሜር ልጅ ጳስኮር ኤርምያስ በዚህ ነገር ትንቢት ሲናገር ሰማ።'),
  ('288336cc-55ec-53fd-a67c-92161350a8c8', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 2, 2, 'ጳስኮርም ነቢዩን ኤርምያስን ገረፈው፤ በእግዚአብሔርም ቤት በነበረው በላይኛው በብንያም በር ባለው አዘቅት ውስጥ ጣለው።'),
  ('86139bf4-659e-50cb-a652-317e4c05a0e3', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 3, 3, 'በነጋውም ጳስኮር ኤርምያስን ከአዘቅት ውስጥ አወጣው። ኤርምያስም እንዲህ አለው፥ “እግዚአብሔር ስምህን፦ ዘዋሪ ስደተኛ እንጂ ጳስኮር ብሎ አይጠራህም።'),
  ('bdfd4ff3-69f1-5c79-a70f-bdc5d85a99e1', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 4, 4, 'እግዚአብሔር እንዲህ ይላልና፦ እነሆ አንተን ከወዳጆችህ ሁሉ ጋር አፈልስሃለሁ፤ እነርሱም በጠላቶቻቸው ሰይፍ ይወድቃሉ፤ ዐይኖችህም ያያሉ፤ አንተንና ይሁዳንም ሁሉ በባቢሎን ንጉሥ እጅ አሳልፌ እሰጣለሁ፤ እርሱም ወደ ባቢሎን ያፈልሳቸዋል፤ በሰይፍም ይገድላቸዋል።'),
  ('e2d35c1a-5e3e-568b-a5dd-a74ece4e078c', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 5, 5, 'የዚችንም ከተማ ኀይል ሁሉ፥ ጥሪቷንም ሁሉ፥ ክብርዋንም ሁሉ፥ የይሁዳንም ነገሥታት መዝገብ ሁሉ በጠላቶቻቸው እጅ አሳልፌ እሰጣለሁ፤ እነርሱ ይበዘብዙአቸዋል፤ ይዘውም ወደ ባቢሎን ያስገቡአቸዋል።'),
  ('c2c52a40-e973-5f16-a7b5-519d9fca2a42', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '823695d8-a7f3-52cc-afac-b91eeec20eb7', 6, 6, 'አንተም ጳስኮር ሆይ! በቤትህም የሚኖሩት ሁሉ ተማርካችሁ ትሄዳላችሁ፤ አንተም በሐሰት ትንቢት የተናገርህላቸው ወዳጆችህ ሁሉ ወደ ባቢሎን ትገባላችሁ፤ በዚያም ትሞታላችሁ፤ በዚያም ትቀበራላችሁ።”'),
  ('7395a827-d65a-5738-a7c9-a2e05d4e90fc', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 1, 7, 'አቤቱ! አታለልኸኝ፤ እኔም ተታለልሁ፤ ከእኔም በረታህ አሸነፍህም፤ ቀኑን ሁሉ መሳቂያ ሆኛለሁ፤ ሁሉም ያፌዙብኛል።'),
  ('60a66dbe-946f-595c-a7b3-860ee7f5e654', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 2, 8, 'በተናገርሁ ቍጥር እጮኻለሁ፤ ግፍና ጥፋት ብዬ እጠራለሁ፤ የእግዚአብሔር ቃል ቀኑን ሁሉ ስድብና ዋዛ ሆኖብኛልና።'),
  ('00c90005-3531-545f-adae-f9ce1a1c1026', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 3, 9, 'እኔም እንዲህ አልሁ፥ “የእግዚአብሔርን ስም አላነሣም፤ ከእንግዲህ ወዲህ በስሙ አልናገርም፥” በአጥንቶች ውስጥ እንደ ገባ እንደሚነድድ እሳት ያለ በልቤ ሆነብኝ፤ ደከምሁ፤ መሸከምም አልቻልሁም።'),
  ('4555de69-2c36-51df-a6a1-af1ac5b3bf1f', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 4, 10, 'በእኔ ላይ የተሰበሰቡና የከበቡኝን የብዙ ሰዎችን ስድብ ሰምቻለሁ፤ መውደቄን የሚጠብቁ የሰላሜ ሰዎች ሁሉ፥ “ምናልባት ይታለል እንደ ሆነ፥ እናሸንፈውም እንደ ሆነ፥ እርሱንም እንበቀል እንደ ሆነ፥ ተነሡ እኛም እንነሣለን” ይላሉ።'),
  ('90b48b3b-85e6-5b3b-af88-059ecb22fb4c', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 5, 11, 'እግዚአብሔር ግን እንደ ኀያል ተዋጊ ከእኔ ጋር ነው፤ ስለዚህ አሳዳጆች ይሰናከላሉ፤ አያሸንፉም፤ ለዘለዓለምም የማይረሳ ጕስቍልናቸውን አላወቁምና ፈጽመው አፈሩ።'),
  ('fe252f65-9897-582f-aa79-690a060c5f52', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 6, 12, 'አቤቱ! ጽድቅን የምትፈትን ኵላሊትንና ልብን የምትመረምር የሠራዊት ጌታ ሆይ! ክርክሬን ገልጬልሃለሁና ፍረድልኝ።'),
  ('9182df1b-1b90-55db-ad47-2ed3f3abcfa6', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 7, 13, 'ለእግዚአብሔር ዘምሩ፤ አመስግኑትም፤ የችግረኛውን ነፍስ ከክፉ አድራጊዎች እጅ አድኖአልና።'),
  ('67e87d11-44a2-58a9-a845-df18a47f67e5', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 8, 14, 'የተወለድሁባት ቀን፥ እናቴ እኔን የወለደችባት ቀን የተረገመች ትሁን፤ የተባረከችም አትሁን።'),
  ('e9b3afe5-9699-5ee3-a5d0-5ddd30af51f9', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 9, 15, 'ወንድ ልጅ ተወልዶልሃል ብሎ ለአባቴ የምሥራች ነግሮ ደስ ያሰኘው ሰው የተረገመ ይሁን።'),
  ('55a5da3a-4ba3-5ea3-ad26-4322c0a7b653', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 10, 16, 'ያም ሰው እግዚአብሔር በቍጣው እንደ ገለበጣቸው፥ ይቅርም እንደ አላላቸው ከተሞች ይሁን፥ በማለዳም ልቅሶን፥ በቀትርም ጩኸትን ይስማ፤'),
  ('58f66c63-1267-5d0a-a891-4902a0cecce1', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 11, 17, 'እናቴ መቃብር ትሆነኝ ዘንድ፥ ማኅፀንዋም ዘወትር ይዞኝ ያቈይ ዘንድ በማኅፀን ውስጥ አልገደለኝምና።'),
  ('37b9fee7-491c-5241-a286-6139f2e60ba8', 'b19640aa-9ae6-524b-a435-59b1f865d82b', '53bbac0c-f4cc-597d-a3b8-5216c37b68b0', 12, 18, 'ድካምንና ጣርን አይ ዘንድ፥ ዘመኔም በእፍረት ታልቅ ዘንድ ስለ ምን ከማኅፀን ወጣሁ?'),
  ('d6fd2ff0-b00e-5c23-a780-b3d0c6b57266', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 1, 1, 'የይሁዳ ንጉሥ ሴዴቅያስ የመልክያን ልጅ ጳስኮርንና የካህኑን የመዕሴይን ልጅ ሶፎንያስን ወደ ኤርምያስ በላከ ጊዜ ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል ይህ ነው፦ እንዲህም አለ፦'),
  ('a4397265-5e50-54a3-a814-cf87cf10c289', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 2, 2, '“የባቢሎን ንጉሥ ናቡከደነፆር ይወጋን ዘንድ መጥቶአልና ከእኛ ይመለስ ዘንድ፥ ምናልባትም እግዚአብሔር ከእኛ ጋር እንደ ተአምራቱ ሁሉ ያደርግ እንደ ሆነ ስለ እኛ፥ እባክህ እግዚአብሔርን ጠይቅ።”'),
  ('9320f74c-8d95-514b-a265-38a5f3032fe1', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 3, 3, 'ኤርምያስም እንዲህ አላቸው፥ “የይሁዳን ንጉሥ ሴዴቅያስን እንዲህ በሉት፦'),
  ('5ad84c78-13e0-5d05-a994-d01f620e02e7', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 4, 4, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ እነሆ የባቢሎንን ንጉሥ በቅጥርም ውጭ የከበቡአችሁን ከለዳውያንን የምትወጉበትን በእጃችሁ ያለውን የጦር መሣሪያችሁን እሰጣችኋለሁ፤ እነዚያንም በዚህች ከተማ መካከል እሰበስባቸዋለሁ።'),
  ('a299c020-6203-5f1d-a2cc-e3655bb9e310', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 5, 5, 'እኔም በተዘረጋች እጅና በብርቱ ክንድ፥ በቍጣና በመዓት፥ በታላቅም መቅሠፍት አወጋችኋለሁ።'),
  ('97432027-7ef6-5496-afbf-abece11de08b', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 6, 6, 'በዚህችም ከተማ የሚኖሩትን ሁሉ ሰዎችንና እንስሶችን እመታለሁ፤ በጽኑም ቸነፈር ይሞታሉ።'),
  ('db02f4d2-1b7f-597a-ad8b-9530b23eba50', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 7, 7, 'ከዚህ በኋላ እግዚአብሔር እንዲህ ይላል፦ የይሁዳን ንጉሥ ሴዴቅያስንና አገልጋዮቹን፥ ከቸነፈርና ከሰይፍ፥ ከራብም በዚህች ከተማ የቀሩትን ሕዝቡንም በባቢሎን ንጉሥ በናቡከደነፆር እጅ፥ በጠላቶቻቸውና ነፍሳቸውንም በሚሹት እጅ አሳልፌ እሰጣቸዋለሁ፤ እርሱም በሰይፍ ስለት ይመታቸዋል፤ አያዝንላቸውም፤ አይራራላቸውም፤ አይምራቸውም።”'),
  ('700124ef-b471-5221-ad20-b741b212fb00', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 8, 8, 'ለዚህም ሕዝብ እንዲህ በል፥ “እግዚአብሔር እንዲህ ይላል፦ እነሆ በፊታችሁ የሕይወትን መንገድና የሞትን መንገድ አድርጌአለሁ።'),
  ('fd24b24a-abbb-517a-ab91-7c4197e7027d', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 9, 9, 'በዚህች ከተማ ውስጥ የሚቀመጥ በሰይፍና በራብ፥ በቸነፈርም ይሞታል፤ ወጥቶ ወደ ከበቡአችሁ ወደ ከለዳውያን የሚገባ ግን በሕይወት ይኖራል፤ ሰውነቱም ምርኮ ትሆናለች።'),
  ('1176d076-3992-5a84-a6a7-57675b894cb2', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 10, 10, 'ለመልካም ሳይሆን ለክፉ ፊቴን በዚህች ከተማ ላይ አድርጌአለሁና፤ ለባቢሎን ንጉሥ እጅ ትሰጣለች፤ እርሱም በእሳት ያቃጥላታል።”'),
  ('df6d3954-fe68-5f00-ab87-d9b9214ee7b6', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 11, 11, 'የይሁዳ ንጉሥ ቤት ሆይ! የእግዚአብሔርን ቃል ስሙ።'),
  ('f1333a43-d725-5cc3-a504-bd1e894e7ceb', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 12, 12, 'የዳዊት ቤት ሆይ እግዚአብሔር እንዲህ ይላል፥ “ስለ ሥራችሁ ክፋት ቍጣዬ እንደ እሳት እንዳይነድድና ማንም ሳያጠፋው እንዳያቃጥል፥ በማለዳ ፍርድን አድርጉ፤ የተነጠቀውንም ከአስጨናቂው እጅ አድኑ።'),
  ('cfe8dacf-9b09-5a16-ac75-ab41d7169ef9', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 13, 13, 'እነሆ በሜዳ ላይ ባለው ድንጋያማ ሸለቆ የምትቀመጥ ሆይ! እኔ በአንተ ላይ ነኝ፤ እናንተም፦ የሚያስደነግጠን ወይም ወደ መኖሪያችን የሚገባ ማን ነው? የምትሉ ሆይ! እኔ በእናንተ ላይ ነኝ፤'),
  ('6fbcd625-e448-5188-a54d-10107449a1a7', 'd826e593-046e-514f-a325-7349696b22fc', '6e37eb0f-9038-5264-a542-627c066709ca', 14, 14, 'እንደ ሥራችሁም ፍሬ እቀጣችኋለሁ፥ ይላል እግዚአብሔር በዱርዋም ውስጥ እሳትን አነድዳለሁ፤ በዙሪያዋም ያለውን ሁሉ ይበላል።”'),
  ('a0b49234-3cd3-5f6a-a3c3-9a2134f6dda5', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 1, 1, 'እግዚአብሔር እንዲህ ይላል፥ “ወደ ይሁዳ ንጉሥ ቤት ውረድ፤ በዚያም ይህን ቃል ተናገር፥ እንዲህም በል፦'),
  ('5bb2af59-127c-5820-aedd-c3f852276c98', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 2, 2, 'በዳዊት ዙፋን የምትቀመጥ የይሁዳ ንጉሥ ሆይ! አንተና አገልጋዮችህ በእነዚህም በሮች የሚገባ ሕዝብህ፥ የእግዚአብሔርን ቃል ስሙ።'),
  ('1f82b602-755e-562f-a55d-8ca7c678f46d', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 3, 3, 'እግዚአብሔር እንዲህ ይላል፦ ፍርድንና ጽድቅን አድርጉ፤ የተነጠቀውንም ከአስጨናቂው እጅ አድኑ፤ መጻተኛውንና ድሃአደጉን፥ ባልቴቲቱንም አትበድሉ፤ አታምፁባቸውም፤ በዚህም ስፍራ ንጹሕ ደምን አታፍስሱ።'),
  ('4700bd75-879a-59a2-a78a-af0b5374ef46', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 4, 4, 'ይህንም ነገር ብታደርጉ፥ በዳዊት ዙፋን የሚቀመጡ ነገሥታት በሰረገሎችና በፈረሶች ላይ ተቀምጠው፥ በዚህ ቤት በሮች ይገባሉ፤ እነርሱም፥ አገልጋዮቻቸውም፥ ሕዝቡም እንዲሁ ይገባሉ።'),
  ('e63ae2cd-c33a-5843-a2fe-dbcc8dc51fe8', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 5, 5, 'ነገር ግን ይህን ቃል ባትሰሙ፥ ይህ ቤት ወና እንዲሆን በራሴ ምያለሁ፥” ይላል እግዚአብሔር።'),
  ('48842ace-2262-5cb5-a0a9-f7ed166e3606', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 6, 6, 'እግዚአብሔር ስለ ይሁዳ ንጉሥ ቤት እንዲህ ይላልና፥ “አንተ በእኔ ዘንድ እንደ ገለዓድና እንደ ሊባኖስ ራስ ነህ፤ በርግጥ ምድረ በዳና ማንም የማይቀመጥባቸው ከተሞች አደርግሃለሁ።'),
  ('a1be17af-17bd-5ed3-aa96-f67601c53e8e', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 7, 7, 'የሚአጠፋህን ሰው በአንተ ላይ አመጣለሁ፤ የሚያምረውን ዛፍህንም በምሳር ይቈርጣል፤ በእሳትም ያቃጥላል።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c00e4f27-916e-5da2-aaa3-51c48a26d84d', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 8, 8, 'ብዙ አሕዛብም በዚች ከተማ ላይ ያልፋሉ፤ ሁሉም ባልንጀሮቻቸውን፦ እግዚአብሔር በዚች ታላቅ ከተማ ለምን እንዲህ አደረገ? ይላሉ።'),
  ('82690f72-ef4f-5009-a3cc-f51ca2e719d3', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 9, 9, 'እነርሱም፦ የአምላካቸውን የእግዚአብሔርን ቃል ኪዳን ትተው ለሌሎች አማልክት ስለ ሰገዱ፥ ስለ አመለኳቸውም ነው ብለው ይመልሳሉ።”'),
  ('3e5976b9-15e5-522b-a0e9-98b0747b9970', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 10, 10, 'ከእንግዲህ ወዲህ አይመለስምና፥ የተወለደባትንም ሀገር አያይምና ለሚወጣ እጅግ አልቅሱ እንጂ ለሞተ አታልቅሱ፤ አትዘኑለትም።'),
  ('e3bceade-40c4-51c1-aa42-de21ddbbe873', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 11, 11, 'በአባቱ በኢዮስያስ ፋንታ ስለ ነገሠው፥ ከዚህም ስፍራ ስለ ወጣውና ስለማይመለሰው ስለ ይሁዳ ንጉሥ ስለ ኢዮስያስ ልጅ፥ ስለ ሳሌም እግዚአብሔር እንዲህ ይላልና፦'),
  ('0a63fa52-ed65-58b1-ae7e-d57504bd1638', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 12, 12, '“በተማረከበት ሀገር ይሞታል፤ እንግዲህም ወዲህ ሀገሩን አያይም።”'),
  ('4be4d8d6-76ad-5c2c-ac0e-196167cd4190', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 13, 13, 'ቤቱን በዐመፅ፥ አዳራሹንም ያለ እውነት ለሚሠራ፥ ባልንጀራውንም እንዲያው በከንቱ ለሚያሠራ፥ ዋጋውንም ለማይሰጠው ወዮለት!'),
  ('7820ee7b-9f7f-554c-aaab-9cc7c9947300', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 14, 14, '“ለራሴ ሰፊ ቤት፥ ትልቅም ሰገነት እሠራለሁ ለሚል፥ መስኮትንም ለሚያወጣ፥ በዝግባም ሥራ ለሚያስጌጥ፥ በቀይ ቀለምም ለሚቀባው ወዮለት፤'),
  ('c79b3006-c976-5a31-ae01-27c6e47f3eb4', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 15, 15, 'በአባትህ ዝግባ አዳራሽ ስለ ሠራህ በውኑ ትነግሣለህን? በውኑ አባትህ አይበላና አይጠጣም ነበርን? ፍርድንና ጽድቅንስ አያደርግም ነበርን? በዚያም ጊዜ መልካም ሆኖለት ነበር።'),
  ('70a32f5f-fe21-59cb-a692-015974483bf6', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 16, 16, 'የድሃውንና የችግረኛውን ፍርድ ይፈርድ ነበር፤ በዚያም ጊዜ መልካም ሆኖ ነበር። ይህ እኔን ማወቅ አይደለምን? ይላል እግዚአብሔር።'),
  ('bce1a5f5-652a-5df9-a71e-72d1d73c2e43', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 17, 17, 'እነሆ ዐይንህና ልብህ መልካም አይደለም፤ ነገር ግን ለቅሚያ፥ ንጹሕ ደምንም ለማፍሰስ፥ ግድያንና ግፍንም ለመሥራት ብቻ ነው።”'),
  ('a3e96609-3216-5dff-a7b7-fb7fa9c51f30', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 18, 18, 'ስለዚህ እግዚአብሔር ስለ ይሁዳ ንጉሥ ስለ ኢዮስያስ ልጅ ስለ ኢዮአቄም እንዲህ ይላል፥ “ወንድሜ ሆይ፥ ወዮ! ጌታዬ ሆይ፥ ወዮ! እያለ የሚያለቅስለት ለሌለው ለዚያ ሰው ወዮለት!'),
  ('32eb92d6-49d9-5c91-a80e-214814cefc45', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 19, 19, 'አህያም እንደሚቀበር ይቀበራል፤ ከኢየሩሳሌምም በር ወደ ውጭ ተጐትቶ፥ በውራጅ ጨርቅ ተጠቅልሎ ይጣላል።”'),
  ('dc9a1bc2-f999-5ec6-abc2-b7362d39653f', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 20, 20, 'ወዳጆችሽ ሁሉ ጠፍተዋልና ወደ ሊባኖስ ወጥተሽ ጩኺ፤ በባሳንም ላይ ድምፅሽን አንሺ፤ በባሕሩም ማዶ ጩኺ።'),
  ('ffbb3e7f-dec0-5904-ac34-ac49c7685e7b', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 21, 21, 'በጐሰቈልሽ ጊዜ ተናገርሁሽ፤ አንቺም፦ አልሰማም አልሽ፤ ከሕፃንነትሽ ጀምሮ ቃሌን አለመስማትሽ መንገድሽ ነው።'),
  ('661173ec-b731-5ba8-af7f-e64b9a98134a', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 22, 22, 'በግ ጠባቂዎችሽን ሁሉ ነፋስ ይወስዳቸዋል፤ ወዳጆችሽም ተማርከው ይሄዳሉ፤ በዚያን ጊዜም ስለ ክፋትሽ ሁሉ ታፍሪያለሽ፤ በወዳጆችሽም ፊት ቷረጃለሽ።'),
  ('bbfc2f31-ba7a-5cb9-a277-9d3a1256df52', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', 'e6cea654-1745-5a1a-a4b5-617cba80cead', 23, 23, 'አንቺ በሊባኖስ የምትቀመጪ፥ በዝግባ ዛፍም ውስጥ የምታለቅሺ ሆይ! ምጥ እንደ ያዛት ሴት ሕማም በያዘሽ ጊዜ እንዴት ትጨነቂያለሽ!'),
  ('f7b680b3-97f1-5db7-a68a-c6a7612f5633', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 1, 24, '“እኔ ሕያው ነኝ የይሁዳ ንጉሥ የኢዮአቄም ልጅ ኢኮንያን ሆይ፥ አንተን በሰወርሁበት ቀኝ እጄ እንዳለ ማሕተም ነበርህ፤ እንግዲህ ወዲህ ግን እንደማትኖር እኔ ሕያው ነኝ፤” ይላል እግዚአብሔር፤'),
  ('8ca9c9ce-5629-55fe-ac87-a05d5cb3c7b8', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 2, 25, 'ነፍስህንም ለሚሹአት፥ ከፊታቸውም የተነሣ ለምትፈራቸው እጅ፥ ለባቢሎን ንጉሥ ለናቡከደነፆርና ለከለዳውያንም እጅ እሰጥሃለሁ።'),
  ('de4e5fa3-3157-584d-a645-2308a58e99d1', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 3, 26, 'አንተንም፥ የወለደችህን እናትህንም ወዳልተወለዳችሁባት ወደ ሌላ ሀገር እጥላችኋለሁ፤ በዚያም ትሞታላችሁ።'),
  ('fc8dd6b5-4b00-52f7-a435-c7de68a3209c', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 4, 27, 'ነፍሳችሁም ወደምትመኛት ወደዚያች ምድር አትመለሱም።'),
  ('edb9f65e-9cb6-5a76-a4a1-b1dc974bd023', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 5, 28, 'ኢኮንያን ተዋረደ፤ ለምንም እንደማይጠቅም የሸክላ ዕቃ ሆነ፤ እርሱንና ዘሩን ወደማያውቀው ሀገር ወርውረው ጥለውታልና።'),
  ('8472985f-4a87-512a-a388-971f2cd7fc32', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 6, 29, 'ምድር ሆይ! ምድር ሆይ! ምድር ሆይ! የእግዚአብሔርን ቃል ስሚ።'),
  ('2b8355c3-07e7-5164-ad58-7fb7a1edb8c3', '30a3abfe-bb74-5f37-a46d-823b0bcd5d49', '330197db-d067-53f0-a5ed-9e9b164cffc8', 7, 30, 'እግዚአብሔር እንዲህ ይላል፥ “በዘመኑ አይከናወንምና፥ ከዘሩም በዳዊት ዙፋን የሚቀመጥ አይነሣምና፥ እንግዲህ ወዲህም ለይሁዳ ገዢ አይሾምምና ይህን ሰው እንደ ሞተ ቍጠሪው” አለ።'),
  ('0a42ef46-f631-5e62-ac73-13445d068321', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 1, 1, '“የማሰማርያዬን በጎች ለሚያጠፉና ለሚበትኑ እረኞች ወዮላቸው!” ይላል እግዚአብሔር።'),
  ('46025293-8a9b-5e44-a31e-2c2c0ff51bb2', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 2, 2, 'ስለዚህ የእስራኤል አምላክ እግዚአብሔር ሕዝቤን ስለሚጠብቁ እረኞች እንዲህ ይላል፥ “በጎችን በትናችኋል፤ አባርራችኋቸውማል፥ አልጐበኛችኋቸውምም፤ እነሆ! እንደ ሥራችሁ ክፋት እጐበኛችኋለሁ፤ ይላል እግዚአብሔር።'),
  ('3ef491e5-10e9-5ade-a9ce-860c8a7f96e9', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 3, 3, 'የሕዝቤን ቅሬታ ከበተንኋቸው ምድር ሁሉ ወደ መሰማሪያቸው ሰብስቤ እመልሳቸዋለሁ፤ እነርሱም ይበዛሉ፤ ይባዛሉም።'),
  ('e78db646-7b3e-5d4d-a2c1-7c15472526a1', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 4, 4, 'የሚጠብቋቸውን እረኞች አስነሣላቸዋለሁ፤ ዳግመኛም አይፈሩም፤ አይደነግጡምም፥ ይላል እግዚአብሔር።'),
  ('78c0c156-3bb1-5a06-af52-21c1910d9791', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 5, 5, '“እነሆ ለዳዊት የጽድቅ ቍጥቋጥ የማስነሣበት ዘመን ይመጣል፥” ይላል እግዚአብሔር፤ ንጉሥ ይነግሣል፤ ያስባል፤ በምድርም ፍርድንና ጽድቅን ያደርጋል።'),
  ('7f89b7c3-ad03-5301-acbf-ab1dffbbee02', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 6, 6, 'በዘመኑም ይሁዳ ይድናል፤ እስራኤልም ተዘልሎ ይቀመጣል፤ ይህም ስም እግዚአብሔር በነቢያት ኢዮሴዴቅ ብሎ የጠራው ነው።'),
  ('fe4719ee-c2a8-54f4-aabd-f9e267f6f0dc', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 7, 7, 'ስለዚህ እነሆ፥ “የእስራኤልን ሕዝብ ከግብፅ ምድር ያወጣ ሕያው እግዚአብሔርን! ዳግመኛ የማይባልበት ዘመን ይመጣል፥” ይላል እግዚአብሔር፤'),
  ('1d8487d3-42dd-5300-a6c1-ae83e017ab39', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', '1e82128d-f1e9-5797-a978-7e1c4c8c8829', 8, 8, 'ነገር ግን፥ “የእስራኤልን ቤት ዘር ከሰሜን ሀገርና ካሳደዷቸውም ሀገር ሁሉ ያወጣና የመራ ሕያው እግዚአብሔርን!” ይባላል፤ በምድራቸውም መልሶ ያኖራቸዋል።'),
  ('c20c8cc0-2fc5-5879-afe2-2af5894c6c95', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 1, 9, 'ስለ ነቢያት ልቤ በውስጤ ተሰብሮአል፤ አጥንቶችም ሁሉ ታውከዋል፤ ከእግዚአብሔር ፊት የተነሣ፤ ከጌትነቱም ክብር የተነሣ እኔም በመከራ እንደ ተቀጠቀጠ ሰው፥ የወይን ጠጅ እንዳሸነፈውም እንደ ሰካራም ሰው ሆኛለሁ።'),
  ('f01f0579-5587-5457-acb7-6827fa254b58', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 2, 10, 'ዝሙታቸው ምድርን ሞልትዋልና፥ ከመርገም ፊት የተነሣ ምድር አልቅሳለች፤ የምድረ በዳ ማሰሪያው ሁሉ ደርቆአል፤ ሥራቸውና ድካማቸው ከንቱ ሆነ።'),
  ('371dd366-7e3a-53ed-a85e-6489e6484d96', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 3, 11, '“ነቢዩና ካህኑም ረክሰዋልና፥ በቤቴም ውስጥ ክፋታቸውን አግኝቻለሁ፥ ይላል እግዚአብሔር።'),
  ('7fa2c8a4-5ab5-5f68-a74b-4043916dcad1', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 4, 12, 'ስለዚህ መንገዳቸው ድጥና ጨለማ ትሆንባቸዋለች፤ እነርሱም ፍግምግም ብለው ይወድቁባታል፤ እኔም በምጐበኛቸው ዓመት ክፉ ነገርን አመጣባቸዋለሁና፥” ይላል እግዚአብሔር።'),
  ('e8f65cf2-d9bf-5113-a3d8-ed6fab4f9123', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 5, 13, 'በበዓል ትንቢት የተናገሩበትን የሰማርያን ነቢያት ኀጢአታቸውን አይቻለሁ፤ ሕዝቤን እስራኤልንም አሳትዋቸው።'),
  ('1b9dbb1d-2b4c-5b6b-ad27-c93e28c79286', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 6, 14, 'በኢየሩሳሌምም ነቢያት ላይ የሚያስደነግጥን ነገር አይቻለሁ፤ ያመነዝራሉ፤ በሐሰትም ይሄዳሉ፤ ማንም ከክፋቱ እንዳይመለስ የክፉ አድራጊዎችን እጅ ያበረታሉ፤ ሁሉም እንደ ሰዶም፥ የሚኖሩባትም እንደ ገሞራ ሆኑብኝ።'),
  ('a6270ed4-d05d-5449-a0cf-4f2308ca63a3', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 7, 15, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፥ “እነሆ ከኢየሩሳሌም ነቢያት ዘንድ ርኵሰት በምድር ሁሉ ላይ ወጥቶአልና ሕማምን አበላቸዋለሁ፤ መራራ ውኃንም አጠጣቸዋለሁ።”'),
  ('44fb0a1b-a6a8-5180-ad54-cc0aae763bae', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 8, 16, 'ኀያል እግዚአብሔር እንዲህ ይላል፥ “ትንቢት የሚናገሩላችሁን የነቢያትን ቃል አትስሙ፤ ከንቱነትን ያስተምሩአችኋል፤ ከእግዚአብሔር አፍ ሳይሆን ከገዛ ልባቸው የወጣውን ራእይ ይናገራሉ።'),
  ('8e50846b-29fb-5c7d-a8da-4770faeef11e', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 9, 17, 'የእግዚአብሔርን ቃል ለሚያቃልሉ ሰላም ይሆንላችኋል፥ በፍላጎታቸውና በልቡናቸው ክፋት ለሚሄዱም ሁሉ፦ ክፉ ነገር አያገኛችሁም” ይላሉ።'),
  ('9889bc65-123e-520d-a5a1-90659622e292', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 10, 18, 'በእግዚአብሔር ምክር የሚቆም፥ ቃሉን የሚያይና የሚሰማ ማን ነው? ቃሉንስ ያዳመጠ፥ የሰማስ ማንነው?'),
  ('6a27d786-83be-55ec-a4b1-c9e9445c7430', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 11, 19, 'እነሆ ከእግዚአብሔር ዘንድ ንውጽውጽታ ይመጣል፤ ኃጥኣንን ያነዋውጣቸውና ይገለብጣቸው ዘንድ መቅሠፍት ይመጣባቸዋል፤ የዐመፀኞችን ራስ ይገለባብጣል።'),
  ('4ac36540-3c99-533c-a7e3-2b08890e5eea', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 12, 20, 'የእግዚአብሔር ቍጣ የልቡን ዐሳብ ሠርቶ እስኪፈጽም ድረስ አይመለስም፤ በኋለኛውም ዘመን ያውቁታል።'),
  ('237fd036-8d67-5302-a142-b066e4ed560a', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 13, 21, '“እኔ ሳልልካቸው እነዚህ ነቢያት ሮጡ፤ እኔም ሳልነግራቸው ትንቢትን ተናገሩ።'),
  ('8ac886e3-596d-5405-a219-d377844c79fa', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 14, 22, 'በቃሌ ቢቆሙና ምክሬን ቢሰሙ ኖሮ ግን ሕዝቤን ከክፉ ሥራቸው በመለሱአቸው ነበር።'),
  ('f1f8dc34-14d2-51b9-a188-56ccb1303ac9', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 15, 23, '“እኔ ቅርብ አምላክ ነኝ እንጂ ሩቅ አምላክ አይደለሁም ይላል እግዚአብሔር።'),
  ('dc4a9ce9-69f1-5026-af5f-3d126ef80a96', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 16, 24, 'ሰው በስውር ቦታ ቢሸሸግ፥ እኔ አላየውምን? ሰማይንና ምድርንስ የሞላሁ እኔ አይደለሁምን? ይላል እግዚአብሔር።'),
  ('ebf2724d-b2de-5b8d-a103-165925510b58', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 17, 25, 'ሕልምን አለምን እያሉ በስሜ ሐሰተኛ ትንቢት የሚናገሩትን የነቢያትን ነገር ሰምቻለሁ።'),
  ('98cabc39-0744-5360-a2c6-7adf07633dab', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 18, 26, 'ትንቢትን በሐሰት በሚናገሩ፥ የልባቸውንም ሽንገላ በሚናገሩ በነቢያት ልብ ይህ የሚሆነው እስከ መቼ ነው?'),
  ('515ea64b-51cc-591d-a92b-2c9dd6cbc189', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 19, 27, 'አባቶቻቸው ስለ በዓል ስሜን እንደ ረሱ፥ እያንዳንዱ ለባልንጀራው በሚናገራት ሕልማቸው ሕዝቤን ስሜን ለማስረሳት ያስባሉ።'),
  ('dbfcaac7-5be0-5597-a093-ed263bc8dbcd', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 20, 28, 'የሚያልም ነቢይ ሕልምን ይናገር፤ ቃሌም ያለበት ቃሌን በእውነት ይናገር። ገለባ ከስንዴ ጋር ምን አለው? ይላል እግዚአብሔር።'),
  ('278f4bb9-b385-5133-a5bd-68afa512f04c', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 21, 29, 'በውኑ ቃሌ እንደ እሳት፥ ድንጋዩንም እንደሚያደቅቅ መዶሻ አይደለምን? ይላል እግዚአብሔር።'),
  ('1d9f6ed8-702b-544c-a4e2-7f5db8d261dd', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 22, 30, 'ስለዚህ እነሆ እያንዳንዱ ከባልንጀራው ዘንድ ቃሌን በሚሰርቁ ነቢያት ላይ ነኝ፥ ይላል እግዚአብሔር።'),
  ('f13b8567-9e14-5d52-ae9c-317f37aad21f', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 23, 31, 'እነሆ ከምላሳቸው ትንቢትን አውጥተው፦ እርሱ የእግዚአብሔር ሸክም ነው በሚሉ ነቢያት ላይ ነኝ፤ ይላል እግዚአብሔር፤'),
  ('695cfd3d-9871-52f1-aeda-037a45c2ab59', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 24, 32, 'እነሆ ሐሰትን በሚያልሙ፥ በሚናገሩም፥ በሐሰታቸውና በድፍረታቸውም ሕዝቤን በሚያስቱ በነቢያት ላይ ነኝ፥ ይላል እግዚአብሔር፤ እኔም አልላክኋቸውም፤ አላዘዝኋቸውምም፤ ለእነዚህ ሕዝብ በማናቸውም አይረቡአቸውም፥” ይላል እግዚአብሔር።'),
  ('244c991b-b0f9-565f-a884-1b0d2b88ed1c', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 25, 33, 'ይህ ሕዝብ ወይም ነቢይ ወይም ካህን፥ “የእግዚአብሔር ሸክም ምንድር ነው?” ብሎ ቢጠይቅህ፥ አንተ፥ “ሸክሙ እናንተ ናችሁ፤ እጥላችሁማለሁ፥ ይላል እግዚአብሔር” ትላቸዋለህ።'),
  ('2695674d-3165-5f5e-a40e-2f61fc64b9e3', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 26, 34, 'የእግዚአብሔር ሸክም የሚለውን ነቢይንና ካህንን፥ ሕዝብንም ያን ሰውና ቤቱን እቀጣለሁ።'),
  ('1c07c753-3033-59fb-a516-0484c16dcc15', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 27, 35, 'አንዱም አንዱ ለባልንጀራው፥ አንዱም አንዱ ለወንድሙ እንዲህ ይበል፥ “እግዚአብሔር የመለሰው ምንድን ነው? እግዚአብሔርስ ምን ነገር ተናገረ?”'),
  ('0f6f4540-ec83-5425-ae0f-441c324966e9', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 28, 36, 'ለሰው ሁሉ ቃሉ ሸክም ይሆንበታልና የእግዚአብሔር ሸክም ብላችሁ ከእንግዲህ ወዲህ አትጥሩ፤ የሠራዊትን ጌታ የአምላካችንን የእግዚአብሔርን የሕያውን አምላክ ቃል ለውጣችኋልና።'),
  ('4bc78280-c74a-57bc-a9c3-058abd7d8615', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 29, 37, 'ለነቢዩ፥ “እግዚአብሔር ምን መለሰልህ እግዚአብሔርስ የተናገረው ምንድን ነው?” በሉ ምን ተናገረ?'),
  ('e4fafa63-bd52-5e85-ac13-5d25d2e72fd1', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 30, 38, 'ነገር ግን፥ “የእግዚአብሔር ሸክም” ብትሉ፥ እግዚአብሔር እንዲህ ይላል፥ “እኔ፦ የእግዚአብሔር ሸክም አትበሉ ብዬ ልኬባችኋለሁና፥ እናንተም ይህን ቃል፦ የእግዚአብሔር ሸክም ብላችኋልና፥'),
  ('0185bf55-ca2e-5101-afd6-e112112d1cdd', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 31, 39, 'ስለዚህ፥ እነሆ- ፈጽሜ እረሳችኋለሁ እናንተንም፥ ለእናንተና ለአባቶቻችሁም የሰጠኋትን ከተማ ከፊቴ አንሥቼ እጥላለሁ።'),
  ('770c3fa0-f5e4-5832-afb2-c69b92cc5bbc', 'bb2fdbf0-ef1b-50d8-a8fe-0b2416ab501f', 'f14388a4-c458-5c3a-aee4-6cfd4893c752', 32, 40, 'የዘለዓለምንም ስድብና ከቶ ተረስቶ የማይጠፋውን የዘለዓለምን ውርደት አመጣባችኋለሁ።”'),
  ('a80d5b0d-da77-5160-a591-a390504da122', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 1, 1, 'የባቢሎን ንጉሥ ናቡከደነፆር የይሁዳን ንጉሥ የኢዮአቄምን ልጅ ኢኮንያንን፥ የይሁዳንም አለቆች፥ ብልሃተኞችንና እስረኞችን፥ ጓደኞቻቸውንም ከኢየሩሳሌም ማርኮ ወደ ባቢሎን ከአፈለሳቸው በኋላ፥ እነሆ እግዚአብሔር በእግዚአብሔር መቅደስ ፊት የተቀመጡ ሁለት የበለስ ቅርጫቶችን አሳየኝ።'),
  ('6b5cb67d-b323-58b2-a7f6-885f026717ed', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 2, 2, 'በአንደኛዪቱ ቅርጫት አስቀድሞ እንደ ደረሰ በለስ የሚመስል እጅግ መልካም በለስ ነበረባት፤ በሁለተኛዪቱም ቅርጫት ከክፋቱ የተነሣ ይበላ ዘንድ የማይቻል እጅግ ክፉ በለስ ነበረባት።'),
  ('06ca4bf7-5337-5149-a199-d30ad4c8db66', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 3, 3, 'እግዚአብሔርም፥ “ኤርምያስ ሆይ! የምታየው ምንድን ነው?” አለኝ። እኔም፥ “በለስን አያለሁ፤ እጅግ መልካም የሆነ መልካም በለስ፥ ከክፋቱም የተነሣ ይበላ ዘንድ የማይቻል እጅግ ክፉ የሆነ ክፉ በለስ ነው” አልሁ።'),
  ('6e0b6dab-da1f-5baa-ad8b-efd4e50e40f0', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 4, 4, 'የእግዚአብሔርም ቃል ወደ እኔ እንዲህ ሲል መጣ፦'),
  ('085f328d-5ce7-5ae3-ab31-b9f54985da50', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 5, 5, '“የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ እንደዚህ እንደ መልካሙ በለስ፥ እንዲሁ ከዚህ ስፍራ ወደ ከለዳውያን ምድር የሰደድሁትን የይሁዳን ምርኮ ለበጎነት እመለከተዋለሁ።'),
  ('f2f1171b-6b5b-5ef6-aeb3-33eb97cf8c6f', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 6, 6, 'ዐይኔንም ለበጎነት በእነርሱ ላይ አደርጋለሁ፤ ወደዚህችም ምድር ለመልካም እመልሳቸዋለሁ፤ እሠራቸዋለሁ እንጂ አላፈርሳቸውም፤ እተክላቸዋለሁ እንጂ አልነቅላቸውም።'),
  ('d090e929-cf49-5d71-a064-1de74e00f24f', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 7, 7, 'እኔም እግዚአብሔር እንደ ሆንሁ የሚያውቅ ልብ እሰጣቸዋለሁ፤ በፍጹምም ልባቸው ወደ እኔ ይመለሳሉና ሕዝቤ ይሆኑኛል፤ እኔም አምላክ እሆናቸዋለሁ።”'),
  ('758d742b-fcc7-55e7-aa47-c2930e8d86e8', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 8, 8, 'እግዚአብሔርም እንዲህ ይላል፥ “ከክፋቱ የተነሣ ይበላ ዘንድ እንደማይቻል እንደ ክፉው በለስ፥ እንዲሁ የይሁዳን ንጉሥ ሴዴቅያስን፤ አለቆቹንም፥ በዚች ሀገር የሚቀሩትንም የኢየሩሳሌምን ቅሬታ፥ በግብጽም ሀገር የሚቀመጡትን እንዲሁ አደርጋቸዋለሁ።'),
  ('0925d7f1-2395-5835-a49d-37be34c802ee', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 9, 9, 'በማሳድዳቸውም ስፍራ ሁሉ ለስድብና ለምሳሌ፥ ለጥላቻና ለርግማን ይሆኑ ዘንድ በምድር መንግሥታት ሁሉ እንዲበተኑ አደርጋለሁ።'),
  ('2a0ad1f9-4f6e-5b1e-a1b9-c545b9d23dd0', '2347d824-ae40-5d6f-a119-869b08c35457', '86a77eba-013d-5301-acf1-aa4f6e2c5519', 10, 10, 'ለእነርሱ፥ ለዘራቸውና ለአባቶቻቸውም ከሰጠኋቸው ምድር እስኪጠፉ ድረስ በመካከላቸው ሰይፍንና ራብን ቸነፈርንም እሰድዳለሁ።”'),
  ('121cdf0b-ef4b-5294-a57d-c8d523092904', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 1, 1, 'በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም በአራተኛው ዓመት፥ በባቢሎን ንጉሥ በናቡከደነፆር በመጀመሪያው ዓመት፥ ስለ ይሁዳ ሕዝብ ሁሉ ወደ ኤርምያስ የመጣው ቃል ይህ ነው።'),
  ('98f976bf-939a-5e9b-a735-6d4070c80eab', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 2, 2, 'ይህንም ቃል ነቢዩ ኤርምያስ ለይሁዳ ሕዝብ ሁሉና በኢየሩሳሌም ለተቀመጡ ሁሉ እንዲህ ሲል ተናገረ፦'),
  ('08a40c64-f1e9-58eb-a686-b8cca4d0706c', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 3, 3, '“ከይሁዳ ንጉሥ ከአሞጽ ልጅ ከኢዮስያስ ከዐሥራ ሦስተኛው ዓመት ጀምሮ እስከ ዛሬ ድረስ ባሉት በእነዚህ በሃያ ሦስቱ ዓመታት፥ የእግዚአብሔር ቃል ወደ እኔ መጣ፤ እኔም ማልጄ ተነሥቼ ተናገርኋችሁ፤ ነገር ግን አልሰማችሁኝም።”'),
  ('e405c525-4b7e-5f44-a235-16780e2bccc4', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 4, 4, 'እግዚአብሔርም ባሪያዎቹን ነቢያትን ወደ እናንተ ላከ፤ እነርሱም ማልደው ገሠገሡ፤ እናንተም አልሰማችኋቸውም፤ ለመስማትም ጆሮአችሁን አላዘነበላችሁም።'),
  ('5d92ea2b-9bc3-53e8-ae66-332f78c3c91c', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 5, 5, 'እርሱም፥ “ሁላችሁ እናንተ ከክፉ መንገዳችሁና ከሥራችሁ ክፋት ተመለሱ፤ እግዚአብሔርም ከዘለዓለም እስከ ዘለዓለም ለእናንተና ለአባቶቻችሁ በሰጣችሁ ምድር ትቀመጣላችሁ አለ።'),
  ('d5b409d8-054e-5db2-a335-53572516dea6', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 6, 6, 'ትገዙላቸውና ትሰግዱላቸውም ዘንድ ሌሎችን አማልክት አትከተሉ፤ ክፉም እንዳላደርግባችሁ በእጃችሁ ሥራ አታስቈጡኝ።'),
  ('b928fd73-a912-59bc-a6f4-a0fcebd7d992', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 7, 7, 'ለእናንተ ጕዳት እንዲሆን በእጃችሁ ሥራ ታስቈጡኝ ዘንድ አልሰማችሁኝም፥” ይላል እግዚአብሔር።'),
  ('eb085eda-7784-52cd-a20c-efa34248bc53', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 8, 8, 'ስለዚህ ኀያል እግዚአብሔር እንዲህ ይላል፥ “ቃሌን አልሰማችሁምና፤'),
  ('97d5facc-d8ed-561b-a41c-cedab1efea01', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 9, 9, 'እነሆ ልኬ የሰሜንን ወገኖች ሁሉ፤ ባሪያዬንም የባቢሎን ንጉሥ ናቡከደነፆርን እወስዳለሁ፤ በዚችም ምድርና በሚቀመጡባትም ሰዎች ላይ፥ በዙሪያዋም ባሉ በእነዚህ አሕዛብ ሁሉ ላይ አመጣቸዋለሁ፤ ፈጽሜም አጠፋቸዋለሁ፤ ለጥፋትና ለፉጨት ለዘለዓለምም ዕፍረት ባድማ አደርጋቸዋለሁ።'),
  ('7fb52a5e-5e4f-54cd-a010-da296bdec862', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 10, 10, 'ከእነርሱም የሐሤትን ድምፅና የደስታን ድምፅ፥ የወንድ ሙሽራን ድምጽና የሴት ሙሽራን ድምፅ፥ የወፍጮንም ድምፅ የመብራትንም ብርሃን አስቀራለሁ።'),
  ('685b029d-17a5-56b8-a7a2-cf6ce4fab5e5', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 11, 11, 'ይህችም ምድር ሁሉ ትጠፋለች፤ ለእነዚህም አሕዛብና ለባቢሎን ንጉሥ ሰባ ዓመት ይገዛሉ።'),
  ('d9ae530f-5385-5b9c-a22b-ffa062ffce06', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 12, 12, '“ሰባው ዓመትም በተፈጸመ ጊዜ፥ የባቢሎንን ንጉሥና ያን ሕዝብ ስለ ኀጢአታቸው እቀጣለሁ፥ ይላል እግዚአብሔር፤ የከለዳውያንንም ምድር ለዘለዓለም አጠፋቸዋለሁ።'),
  ('20757163-db2e-51f2-a3a9-a74aae808848', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 13, 13, 'በእርስዋም ላይ የተናገርሁትን ቃሌን ሁሉ፥ ኤርምያስ በአሕዛብ ሁሉ ላይ በትንቢት የተናገረውን በዚች መጽሐፍ የተጻፈውን ሁሉ፥ በዚያች ምድር ላይ አመጣለሁ።'),
  ('7c92d911-7c0e-5baf-a542-5b52ee300032', '61bc6de8-d163-5d37-aaea-a2041a1cb159', 'b0e62551-ee0b-5d44-a06b-9ef4b5090015', 14, 14, 'ብዙ አሕዛብና ታላላቆች ነገሥታት እነርሱን ይገዙአቸዋል፤ እኔም እንደ አደራረጋቸውና እንደ እጃቸው ሥራ እከፍላቸዋለሁ።”'),
  ('eed8ef31-25f1-5739-a7ab-99e5c8955b06', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 1, 15, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይለኛል፥ “ያልተበረዘ የዚህን ቍጣ የወይን ጠጅ ጽዋ ከእጄ ውሰድ፤ አንተን የምሰድድባቸውን አሕዛብን ሁሉ አጠጣቸው።'),
  ('9f79d4e5-dc5f-5c3b-a630-dbd8686674ea', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 2, 16, 'ከምሰድድባቸውም ሰይፍ የተነሣ ይጠጣሉ፤ ይወላገዳሉ፤ ያብዳሉም።”'),
  ('182979cf-eda3-5447-af60-ec13eec70583', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 3, 17, 'ከእግዚአብሔርም እጅ ጽዋውን ወሰድሁ፤ እግዚአብሔርም እኔን የላከባቸውን አሕዛብ ሁሉ አጠጣኋቸው።'),
  ('e88c82ae-6736-551a-a415-ed2bb010774f', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 4, 18, 'ዛሬ እንደ ሆነው ሁሉ ፈጽሞ ምድረ በዳ ይሆኑ ዘንድ፥ ለርግማንም አደርጋቸው ዘንድ ኢየሩሳሌምንና የይሁዳን ከተሞች፥ ነገሥታቷንም፥ አለቆችዋንም አጠጣኋቸው።'),
  ('68cee4ed-9d10-509c-afb2-9119ac267cf9', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 5, 19, 'የግብፅንም ንጉሥ ፈርዖንን፥ አገልጋዮቹንም፥ መሳፍንቱንና መኳንንቱን፤ ሕዝቡንም ሁሉ፥'),
  ('31932efe-e94c-5911-a762-5df89b994cd5', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 6, 20, 'የተደባለቀውንም ሕዝብ ሁሉ፥ የዖፅ ምድር ነገሥታትንም ሁሉ፥ የፍልስጥኤም ምድር ነገሥታትንም ሁሉ፤ አስቀሎናንም፥ ጋዛንም፥ አቃሮንንም፥ የአዛጦንንም ቅሬታ፤'),
  ('a73f3e94-c877-5e8f-a6a8-567e012fa3e5', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 7, 21, 'ኤዶምያስንም፥ ሞዓብንም፥ የአሞንንም ልጆች፤'),
  ('8e8d795a-dc3c-5d4e-a080-ebdc0a7c02f6', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 8, 22, 'የጢሮስንም ነገሥታት ሁሉ፥ የሲዶናንም ነገሥታት ሁሉ፥ በባሕር ማዶ ያሉ የደሴት ነገሥታትንም፤'),
  ('020b0ec6-d989-5bec-a98c-39a879804d60', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 9, 23, 'ድዳንንም፥ ቴማንንም፥ ሮስንም፥ ፊታቸውን የሚከተቡትን ሁሉ፤'),
  ('45a2199a-307b-57c0-af6a-52c4220f1a21', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 10, 24, 'የዓረብ ነገሥታትንም ሁሉ፥ በምድረ በዳ የሚቀመጡ የድብልቅ ሕዝብ ነገሥታትንም ሁሉ፤'),
  ('dc214c92-ed88-5e4e-a142-1356ca112dd3', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 11, 25, 'የዘምሪ ነገሥታትንም ሁሉ፥ የኤላም ነገሥታትንም ሁሉ፥ የሜዶን ነገሥታትንም ሁሉ፤'),
  ('143a2050-5bb1-5569-a2e2-c1a95b3ac6ce', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 12, 26, 'የቀረቡና የራቁ፥ አንዱ ከሌላው ጋር ያሉ የሰሜን ነገሥታትንም ሁሉ፥ በምድር ፊት ላይ ያሉ የዓለም መንግሥታትንም ሁሉ አጠጣኋቸው፤ የሲሳርም ንጉሥ ከእነርሱ በኋላ ይጠጣል።'),
  ('99629efa-65c2-52d3-ae2c-0a95d077da3f', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 13, 27, 'አንተም፥ “የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በመካከላችሁ ከምሰድደው ሰይፍ የተነሣ ጠጡ፤ ስከሩም፤ ተፍገምገሙ፤ ውደቁም፤ ከእንግዲህም ወዲህ አትነሡም በላቸው።'),
  ('da0a82a4-4ada-5832-a88f-3749511f51ff', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 14, 28, 'ይጠጡም ዘንድ ጽዋውን ከእጅህ ለመቀበል እንቢ ቢሉ፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ፈጽማችሁ ትጠጣላችሁ” በላቸው።'),
  ('7f50378b-5d48-53eb-a26e-4a500407f54e', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 15, 29, 'እነሆ ስሜ የተጠራባትን ከተማ አስጨንቃት ዘንድ እጀምራለሁ፤ በውኑ እናንተ መንጻትን ትነጻላችሁን? በምድር በሚኖሩ ሁሉ ላይ ሰይፍን እጠራለሁና አትነጹም፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('bce0e18b-549c-5520-ad4a-e1d4095dbde1', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 16, 30, '“ስለዚህም ይህን ቃል ሁሉ ትንቢት ትናገርባቸዋለህ፤ እንዲህም ትላቸዋለህ፦ እግዚአብሔር በላይ ሆኖ እንደ አንበሳ ያገሣል፤ በቅዱስ ማደሪያውም ሆኖ ድምፁን ያሰማል፤ በበረቱ ላይ እጅግ ያገሣል፤ ወይንም እንደሚጠምቁ በምድር በሚኖሩ ሁሉ ላይ ይጮኻል።'),
  ('be119460-c04f-5476-ac31-a8f47acdb19b', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 17, 31, 'እግዚአብሔር ከአሕዛብ ጋር ክርክር አለውና ጥፋት እስከ ምድር ዳርቻ ድረስ ይደርሳል፤ ከሥጋ ለባሽ ሁሉም ጋር ይፋረዳል፤ ኀጢአተኞችንም ለሰይፍ አሳልፎ ይሰጣል፥ ይላል እግዚአብሔር።”'),
  ('5842516f-7059-5e63-aae9-8df6ffc2945b', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 18, 32, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ፥ ክፉ ነገር ከሕዝብ ወደ ሕዝብ ይወጣል፤ ጽኑም ዐውሎ ነፋስ ከምድር ዳርቻ ይነሣል።'),
  ('1c068625-f54d-5139-ad92-0c48e33c75aa', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 19, 33, 'በዚያም ቀን የእግዚአብሔር ግዳዮች ከምድር ዳር ጀምሮ እስከ ምድር ዳር ድረስ ይሆናሉ፤ አይለቀስላቸውም፤ በምድር ላይ እንደ ጕድፍ ይሆናሉ እንጂ አይሰበሰቡም፤ አይቀበሩምም።'),
  ('40801094-1ac5-5727-ac0e-0e23173fc453', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 20, 34, 'ትታረዱና ትበተኑ ዘንድ ቀናችሁ ደርሶአልና፥ እንደ ተወደደ የሸክላ ዕቃ ትወድቃላችሁና እናንተ እረኞች! አልቅሱ፤ እናንተም የበጎች አውራዎች! ጩኹ።'),
  ('34a690b1-17dc-52cb-a1e7-b2156d7e0965', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 21, 35, 'ከእረኞች የማይጠፋ የለም፤ የበጎች አውራዎችም አይድኑም።'),
  ('8c29ac06-c3d2-545a-a51b-7eea5dca1f2f', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 22, 36, 'እግዚአብሔር ማሰማርያቸውን አጥፍቶአልና የእረኞች ጩኸት ድምፅ፥ የበጎች አውራዎችም ልቅሶ ሆኖአል።'),
  ('1a8bc4c2-5c1a-50af-a4a1-d09e53554b8d', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 23, 37, 'ከእግዚአብሔር ጽኑ ቍጣ የተነሣ የሰላም ውበት ፈርሶአል።'),
  ('4e7591e3-e3e5-5391-a48d-1957f8e4abd6', '61bc6de8-d163-5d37-aaea-a2041a1cb159', '577762ff-f82c-563b-a4a1-4760f22a3ef0', 24, 38, 'እንደ አንበሳ መደቡን ለቅቆአል፤ ከአረማውያን ሰልፍና ከእግዚአብሔር ጽኑ ቍጣ የተነሣ ምድራቸው ምድረ በዳ ሆናለችና።”'),
  ('29f72222-36ae-528d-a8c6-003f40933a08', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 1, 1, 'በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም መንግሥት መጀመሪያ ይህ ቃል ከእግዚአብሔር ዘንድ መጣ፤ አለም፦'),
  ('e2a64995-1a8b-5c77-a2f8-f4b720cc4298', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “በእግዚአብሔር ቤት አደባባይ ቁም፤ በእግዚአብሔርም ቤት ውስጥ ይሰግዱ ዘንድ ለሚመጡት ለይሁዳ ከተሞች ሁሉ ትነግራቸው ዘንድ ያዘዝሁህን ቃል ሁሉ ተናገራቸው፤ አንዲትም ቃል አታጕድል።'),
  ('6b7e0f1f-37cf-5380-aa9f-db87afd11f78', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 3, 3, 'ምናልባት እያንዳንዳቸው ይሰሙ፥ ከክፉ መንገዳቸውም ይመለሱ ይሆናል፤ እኔም ስለ ሥራቸው ክፋት ያሰብሁባቸውን ክፉ ነገር እተዋለሁ።”'),
  ('b9a79f5b-74a3-5f00-ae22-cd439f7fa23e', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 4, 4, 'እንዲህም በላቸው፥ “እግዚአብሔር እንዲህ ይላል፦ በፊታችሁ በሰጠኋት ሕጌ ትሄዱ ዘንድ ባትሰሙኝ፥'),
  ('ef62c7f7-1671-58ea-a51a-b91e6526de47', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 5, 5, 'የባሪያዎችን የነቢያትን ቃል ትሰሙ ዘንድ በማለዳ ወደ እናንተ ብልካቸው አልሰማችሁም።'),
  ('8cd9537c-fdf7-5a92-a979-d2ce8ed19b0d', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 6, 6, 'ይህን ቤት እንደ ሴሎ አደርገዋለሁ፤ ይችንም ከተማ ለምድር አሕዛብ ሁሉ ርግማን አደርጋታለሁ።”'),
  ('c3a12aa7-1071-5125-aeb9-aacb7fd2e586', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 7, 7, 'ካህናቱም፥ ነቢያተ ሐሰትም፥ ሕዝቡም ሁሉ ኤርምያስ በእግዚአብሔር ቤት ይህን ቃል ሲናገር ሰሙ።'),
  ('5df7a352-2968-5955-a234-2fb0ff337f63', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 8, 8, 'ኤርምያስም ለሕዝቡ ሁሉ ይናገር ዘንድ እግዚአብሔር ያዘዘውን ነገር ሁሉ በፈጸመ ጊዜ ካህናትና ነቢያተ ሐሰት፥ ሕዝቡም ሁሉ፥ “ሞትን ትሞታለህ” ብለው ያዙት።'),
  ('6716ce24-11c8-5a6c-a711-4f75933a08ed', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 9, 9, 'በእግዚአብሔር ስም፥ “ይህ ቤት እንደ ሴሎ ይሆናል፤ ይችም ከተማ ባድማ ትሆናለች፤ የሚኖርባትም የለም ብለህ ስለ ምን ትንቢት ተናገርህ?” ሕዝቡም ሁሉ በእግዚአብሔር ቤት ውስጥ በኤርምያስ ላይ ተሰብስበው ነበር።'),
  ('31eb385e-63bd-524c-a4c2-518922c0a5df', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 10, 10, 'የይሁዳም አለቆች ይህን በሰሙ ጊዜ ከንጉሡ ቤት ወደ እግዚአብሔር ቤት ወጡ፤ በአዲሱም በእግዚአብሔር ቤት ደጅ መግቢያ ተቀመጡ።'),
  ('ca0a9d22-7a9b-5706-af57-21ee98f55f67', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 11, 11, 'ካህናቱና ነቢያተ ሐሰትም ለአለቆቹና ለሕዝቡ ሁሉ፥ “በጆሮአችሁ እንደ ሰማችሁ በዚች ከተማ ላይ ትንቢት ተናግሮአልና ይህ ሰው ሞት የሚገባው ነው” ብለው ተናገሩ።'),
  ('56ecd726-8a29-55e4-a523-a24fb327f529', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 12, 12, 'ኤርምያስም ለአለቆችና ለሕዝቡ ሁሉ እንዲህ ሲል ተናገረ፥ “በሰማችሁት ቃል ሁሉ፥ በዚች ቤትና በዚህች ከተማ ላይ ትንቢት እናገር ዘንድ እግዚአብሔር ልኮኛል።'),
  ('394616e3-56bf-5099-a493-36b6c2bd4f32', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 13, 13, 'አሁንም መንገዳችሁንና ሥራችሁን አሳምሩ፤ የአምላካችሁንም የእግዚአብሔርን ቃል ስሙ፤ እግዚአብሔርም የተናገረባችሁን ክፉ ነገር ይተዋል።'),
  ('e9fc48ab-b66d-56cc-a07a-942f8403fd76', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 14, 14, 'እኔ ግን፥ እነሆ በእጃችሁ ነኝ፤ በዐይናችሁ መልካምና ቅን የመሰለውን አድርጉብኝ።'),
  ('5cd97057-c0c1-5ad3-a062-34de7a25371e', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 15, 15, 'ነገር ግን ይህን ቃል ሁሉ በጆሮአችሁ እናገር ዘንድ በእውነቱ እግዚአብሔር ወደ እናንተ ልኮኛልና ብትገድሉኝ ንጹሕ ደምን በራሳችሁና በዚች ከተማ፥ በሚኖሩባትም ላይ እንድታመጡ በርግጥ ዕወቁ።”'),
  ('3a214d3f-78a9-55e8-a3b4-2b51bcb1df11', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 16, 16, 'አለቆቹና ሕዝቡም ሁሉ ለካህናትና ለነቢያተ ሐሰት፥ “ይህ ሰው በአምላካችን በእግዚአብሔር ስም ተናግሮናልና ሞት አይገባውም” አሉ።'),
  ('da79a4f9-5b3c-57c2-a3f3-7b399c44dac1', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 17, 17, 'ከሀገሩ ሽማግሌዎችም ሰዎች ተነሥተው ለሕዝቡ ጉባኤ ሁሉ እንዲህ አሏቸው።'),
  ('1ffedfe5-34cc-5732-acd6-d97c96a33d45', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 18, 18, '“ሞሬታዊው ሚክያስ በይሁዳ ንጉሥ በሕዝቅያስ ዘመን ትንቢት ይናገር ነበር፤ ለይሁዳም ሕዝብ ሁሉ፦ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ጽዮን እንደ እርሻ ትታረሳለች፤ ኢየሩሳሌምም ምድረ በዳ ትሆናለች፤ የቤቱም ተራራ እንደ ዱር ከፍታ ይሆናል ብሎ ተናገረ።'),
  ('18cc9629-cf36-586c-ab8c-60738fef7e49', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 19, 19, 'በውኑ የይሁዳ ንጉሥ ሕዝቅያስና ሕዝቡ ሁሉ ገደሉትን? በውኑ እግዚአብሔርን አልፈሩምን? ወደ እግዚአብሔርስ አልተማለሉምን? እግዚአብሔርስ የተናገረባቸውን ክፉ ነገር አይተዉምን? እኛም በነፍሳችን ላይ ታላቅ ክፋት እናደርጋለን።”'),
  ('001cefa6-a241-525d-a6d3-1c6da719ed08', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 20, 20, 'ደግሞም በእግዚአብሔር ስም ትንቢት የተናገረ አንድ ሰው ነበር፤ እርሱም የቂርያትይዓሪም ሰው የሸማያ ልጅ ኡርያ ይባል ነበር፤ በዚችም ከተማ፥ በዚችም ምድር ላይ እንደ ኤርምያስ ቃል ሁሉ ትንቢት ተናገረ።'),
  ('7fc29046-0235-5725-a3fd-34ef785b4e9f', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 21, 21, 'ንጉሡም ኢዮአቄም፥ ሠራዊቱ ሁሉ፥ አለቆቹም ሁሉ ቃሉን በሰሙ ጊዜ ንጉሡ ሊገድለው ፈለገ፤ ኡርያም ይህን በሰማ ጊዜ ፈርቶ ሸሸ፤ ወደ ግብፅም ገባ።'),
  ('36b1c43a-8557-5136-aa0e-bcf55b33f758', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 22, 22, 'ንጉሡም ኢዮአቄም ሰዎችን ወደ ግብፅ ላከ፤ የአክቦርን ልጅ ኤልናታንን፥ ሌሎችንም ሰዎች ከርሱ ጋራ ወደ ግብፅ ላካቸው።'),
  ('b5bf0898-d447-5ad5-a9ef-4f4dd7632702', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 23, 23, 'ከግብፅም ኡርያን አውጥተው ወደ ንጉሡ ወደ ኢዮአቄም ይዘውት መጡ፤ እርሱም በሰይፍ ገደለው፤ ሬሳውንም በሕዝብ መቃብር ጣለው።'),
  ('dc5cdf61-929d-56f3-a6e3-1e47433f6369', 'dc36ac3e-64dc-50ea-addb-91103649e280', '47bdcbc4-1d52-5da5-a79f-5bd903f9a47a', 24, 24, 'ነገር ግን በሕዝቡ እጅ እንዳይሰጥና እንዳይገድሉት የሳፋን ልጅ የአኪቃም እጅ ከኤርምያስ ጋር ነበረች።'),
  ('dd670fe3-f05a-599b-ae7d-6d320732df1c', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 1, 1, 'በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም መንግሥት መጀመሪያ ይህ ቃል ከእግዚአብሔር ዘንድ ወደ ኤርምያስ መጣ።'),
  ('6dadf147-bc48-534f-a5c7-e7cba2d18bf0', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “ሰንሰለትና ቀንበር ሥራ፤ በአንገትህም ላይ አድርግ፤'),
  ('aeebb829-ccb5-5ea8-ad16-4d951d23136c', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 3, 3, 'ወደ ይሁዳ ንጉሥም ወደ ሴዴቅያስ፥ ወደ ኢየሩሳሌም በመጡት መልእክተኞች እጅ ወደ ኤዶምያስ ንጉሥ፥ ወደ ሞዓብም ንጉሥ፥ ወደ አሞን ልጆች ንጉሥ፥ ወደ ጢሮስም ንጉሥ፥ ወደ ሲዶናም ንጉሥ ላክ።”'),
  ('08535c55-1a84-599e-adf0-45344f35e956', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 4, 4, 'ለጌቶቻቸው እንዲነግሩ እንዲህ ብለህ እዘዛቸው፥ “የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ለጌቶቻችሁ እንዲህ በሉ፦'),
  ('dc545682-de38-55a1-a4f9-118a364dfe1b', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 5, 5, 'ምድሪቱን፥ በምድር ፊት ላይ ያሉትን ሰዎችንና እንስሶችን በታላቅ ኀይሌና በተዘረጋችው ክንዴ ፈጥሬአለሁ፤ ለዐይኔም መልካም ለሆነው እሰጣታለሁ።'),
  ('8660c152-2ee8-5d1b-a261-7de56c147095', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 6, 6, 'አሁንም ምድርን ሁሉ ለባሪያዬ ለባቢሎን ንጉሥ ለናቡከደነፆር እጅ አሳልፌ ሰጥቻለሁ፤ ያገለግሉትም ዘንድ የምድረ በዳ አራዊትን ደግሞ ሰጥቼዋለሁ።'),
  ('edeae278-87b5-5000-a591-bb84d55b3ec5', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 7, 7, 'የገዛ ራሱም ምድር ጊዜ እስኪመጣ ድረስ አሕዛብ ሁሉ ለእርሱና ለልጁ ለልጅ ልጁም ይገዛሉ፤ በዚያን ጊዜም ብዙ አሕዛብና ታላላቆች ነገሥታት ለእርሱ ይገዙለታል።'),
  ('95155855-53cc-5e87-a995-a99558bec63b', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 8, 8, '“ለባቢሎን ንጉሥም ለናቡከንደነፆር የማይገዛውን፥ ከባቢሎንም ንጉሥ ቀንበር በታች አንገቱን ዝቅ የማያደርገውን ሕዝብና መንግሥት፥ ያን ሕዝብ በእጁ እስካጠፋው ድረስ በሰይፍና በራብ፥ በቸነፈርም እቀጣለሁ፥ ይላል እግዚአብሔር።'),
  ('2dc356de-b9d6-5275-a303-054233bb37fd', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 9, 9, 'እናንተ ግን፦ ለባቢሎን ንጉሥ አትገዙም የሚሉአችሁን የሐሰት ነቢያቶቻችሁንና ምዋርተኞቻችሁን፥ ሕልም ዐላሚዎቻችሁንና ባለ ራእዮቻችሁን፥ መተተኞቻችሁንም አትስሙ፤'),
  ('e35f5bbe-04d4-51f2-a7f5-0ce677050c77', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 10, 10, 'ከምድራችሁ እንዲያርቁአችሁ፥ እኔም እንዳሳድዳችሁ፥ እናንተም እንድትጠፉ ሐሰተኛ ትንቢትን ይናገሩላችኋልና።'),
  ('e59836ab-f748-579d-acfe-bd0aff3d2703', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 11, 11, 'ነገር ግን ከባቢሎን ንጉሥ ቀንበር በታች አንገቱን ዝቅ የሚያደርገውንና የሚገዛለትን ሕዝብ በሀገሩ ላይ እተወዋለሁ፤ እርሱም ያርሳታል፤ ይቀመጥባትማል።”'),
  ('9e451637-7cb4-5bc4-a3d4-88f72adb50c9', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 12, 12, 'ለይሁዳ ንጉሥ ለሴዴቅያስም ይህን ቃል ሁሉ ተናገርሁ፥ “ከባቢሎን ንጉሥ ቀንበር በታች አንገታችሁን ዝቅ አድርጉ፤ ለእርሱና ለሕዝቡም ተገዙላቸው በሕይወትም ኑሩ።'),
  ('5e287527-6fc6-5d38-ae11-ce53b8a6dd37', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 13, 13, 'ለባቢሎን ንጉሥ ይገዛ ዘንድ እንቢ ስላለ ሕዝብ እግዚአብሔር እንደ ተናገረ፥ አንተና ሕዝብህ በሰይፍና በራብ፥ በቸነፈርም ለምን ትሞታላችሁ?'),
  ('14360d51-9228-518e-af3a-40bdcda1574d', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 14, 14, 'ሐሰተኛን ትንቢት ይናገሩላችኋልና፦ ለባቢሎን ንጉሥ አትገዙም የሚሉአችሁን የነቢያትን ቃል አትስሙ።'),
  ('f62fb121-2e75-5fc6-ab30-fee1624d0772', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 15, 15, 'እኔ አልላክኋቸውምና፤ ነገር ግን እኔ እንዳሳድዳችሁ፥ እናንተና ትንቢት የሚናገሩላችሁ ነቢያትም እንድትጠፉ በስሜ ሐሰተኛ ትንቢትን ይናገራሉ፥ ይላል እግዚአብሔር።”'),
  ('01c02607-495c-5371-a77b-1b1b4b6fc420', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 16, 16, 'ለካህናትም ለዚህም ሕዝብ እንዲህ ብዬ ተናገርሁ፥ “እግዚአብሔር እንዲህ ይላል፦ ሐሰተኛውን ትንቢት ይናገሩላችኋልና፦ የእግዚአብሔር ቤት ዕቃ በቅርብ ጊዜ ከባቢሎን ይመለሳል የሚሉአችሁን የነቢያቶቻችሁን ቃል አትስሙ።'),
  ('4ce7cc5b-1618-5857-a91a-457629018be9', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 17, 17, 'እነርሱን አትስሙ፤ ለባቢሎን ንጉሥ ተገዙ፤ በሕይወትም ኑሩ፤ ይህችስ ከተማ ስለ ምን ባድማ ትሆናለች?'),
  ('c423d88c-6045-57c8-aa66-5a3ceb67a8b0', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 18, 18, 'እነርሱ ግን ነቢያት ቢሆኑ፥ የእግዚአብሔርም ቃል በእነርሱ ዘንድ ቢገኝ፥ በእግዚአብሔር ቤትና በይሁዳ ንጉሥ ቤት፥ በኢየሩሳሌምም የቀሩት ዕቃዎች ወደ ባቢሎን እንዳይሄዱ ወደ ሠራዊት ጌታ ወደ እግዚአብሔር ይማለሉ።”'),
  ('76af34f7-cd50-5808-aa33-687ac5f81149', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 19, 19, 'ስላልወሰዳቸው ዓምዶች፥ ስለ ባሕሩም፥ ስለ መቀመጫዎቹም፥ በዚች ከተማ ስለ ቀሩት ዕቃዎች ሁሉ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦'),
  ('7319cb9d-7240-5020-a1b3-25211e678b38', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 20, 20, '“የባቢሎን ንጉሥ ናቡከደነፆር የይሁዳን ንጉሥ የኢዮአቄምን ልጅ ኢኮንያንንና የይሁዳንና የኢየሩሳሌምን አለቆች ሁሉ ማርኮ ከኢየሩሳሌም ወደ ባቢሎን ባፈለሳቸው ጊዜ፥'),
  ('79672e8b-9f45-522f-aaae-c85ccf805664', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 21, 21, 'በእግዚአብሔር ቤትና በይሁዳ ንጉሥ ቤት፥ በኢየሩሳሌምም ስለ ቀሩት ዕቃዎች የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦'),
  ('63e2ab1a-7300-595b-a9b8-ab136d7518dc', 'cec35898-486e-5a20-a532-287e40937f8b', 'e52a7bfb-1ec7-5130-ad18-b3d7ebb93a77', 22, 22, 'ወደ ባቢሎን ይወሰዳሉ፤ እስከምጐበኛቸው ቀን ድረስ በዚያ ይኖራሉ፥ ይላል እግዚአብሔር፤ በዚያን ጊዜም ትወጣላችሁ፤ ወደዚህም ስፍራ ትመለሳላችሁ።”'),
  ('e728e304-2af9-552e-a05e-888311d7829d', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 1, 1, 'ከዚህም በኋላ እንዲህ ሆነ፤ በዚያ ዓመት፥ በይሁዳ ንጉሥ በሴዴቅያስ መንግሥት መጀመሪያ፥ በአራተኛው ዓመት በአምስተኛው ወር ሐሰተኛው ነቢይ የገባዖን ሰው የዓዙር ልጅ ሐናንያ በእግዚአብሔር ቤት በካህናትና በሕዝብ ሁሉ ፊት እንዲህ ብሎ ተናገረኝ፦'),
  ('138aad8e-e7c5-5908-a962-8bbe09e926e2', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 2, 2, '“የሠራዊት ጌታ የእስራኤል አምላክ እግዚአብሔር እንዲህ አለ፦ የባቢሎንን ንጉሥ ቀንበር ሰብሬአለሁ።'),
  ('375bf8b8-6ee4-5051-a1c8-dd449c9a5cf3', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 3, 3, 'የባቢሎን ንጉሥ ናቡከደነፆር ከዚች ስፍራ ወደ ባቢሎን የወሰዳቸውን የእግዚአብሔርን ቤት ዕቃዎች ሁሉ በሁለት ዓመት ውስጥ ወደዚህች ስፍራ እመልሳለሁ፤'),
  ('601d7478-91f1-5d46-a043-e84ff2a9f2ce', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 4, 4, 'ወደ ባቢሎንም የሄዱትን የይሁዳን ንጉሥ የኢዮአቄምን ልጅ ኢኮንያንንና የይሁዳን ምርኮ ሁሉ ወደዚች ስፍራ እመልሳቸዋለሁ፤ የባቢሎንን ንጉሥ ቀንበር እሰብራለሁና።”'),
  ('6ec9bbc2-116a-5618-a9f1-72af5a43b7ac', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 5, 5, 'ነቢዩ ኤርምያስም በካህናቱና በእግዚአብሔር ቤት በቆሙት ሕዝብ ሁሉ ፊት ለሐሰተኛው ነቢይ ለሐናንያ ተናገረ።'),
  ('35669d6d-be35-5ed4-a604-c2ffe94a0eb7', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 6, 6, 'ነቢዩም ኤርምያስ እንዲህ አለ፥ “አሜን፥ እግዚአብሔር እንዲህ ያድርግ፤ የእግዚአብሔርን ቤት ዕቃ፥ ምርኮውንም ሁሉ ከባቢሎን ወደዚህ ስፍራ በመመለስ እግዚአብሔር የተናገርኸውን ትንቢት ይፈጽም።'),
  ('8565cd48-43a5-5232-a91a-174038fcf4b8', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 7, 7, 'ነገር ግን በጆሮህና በሕዝቡ ሁሉ ጆሮ የምናገረውን የእግዚአብሔርን ቃል ስማ፤'),
  ('34f510e6-e3bb-5eae-a9e9-d844423669b7', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 8, 8, 'ከጥንት ከእኔና ከአንተ በፊት የነበሩ ነቢያት በብዙ ሀገርና በታላላቅ መንግሥታት ላይ ስለ ሰልፍና ስለ ክፉ ነገር ስለ ቸነፈርም ትንቢት ተናገሩ።'),
  ('a67d4d7b-3e34-5c44-a4cd-d12279b81991', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 9, 9, 'ስለ ሰላም ትንቢት የተናገረ ነቢይ ትንቢቱ በደረሰ ጊዜ፥ እግዚአብሔር በእውነት የላከው ነቢይ እንደ ሆነ ይታወቃል።”'),
  ('8bc2d590-691d-591d-ad10-31e4dae6f526', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 10, 10, 'ሐሰተኛው ነቢይ ሐናንያም በሕዝቡ ሁሉ ፊት ቀንበሩን ከነቢዩ ከኤርምያስ አንገት ወስዶ ሰበረው።'),
  ('d0958d7a-5889-5460-ab12-5733065c73b3', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 11, 11, 'ሐናንያም በሕዝቡ ሁሉ ፊት፥ “እግዚአብሔር እንዲህ ይላል፦ እንግዲህ በሁለት ዓመት ውስጥ የባቢሎንን ንጉሥ የናቡከደነፆርን ቀንበር ከአሕዛብ ሁሉ አንገት እሰብራለሁ” አለ። ነቢዩ ኤርምያስም መንገዱን ሄደ።'),
  ('3bface0d-f627-53f0-af69-f40bf0ec6707', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 12, 12, 'ሐናንያም ቀንበሩን ከነቢዩ ኤርምያስ አንገት ከሰበረ በኋላ፥ የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('c445fb24-63b3-5c92-af5c-b6423c5b2567', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 13, 13, '“ሂድ፥ ለሐናንያ እንዲህ ብለህ ንገረው፦ እግዚአብሔር እንዲህ ይላል፦ አንተ የእንጨትን ቀንበር ሰብረሃል፤ እኔ ግን በእርሱ ፋንታ የብረትን ቀንበር እሠራለሁ።'),
  ('7216089e-dfa3-5e4d-a882-b4acbef9d4fe', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 14, 14, 'የእስራኤልም አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ ለባቢሎን ንጉሥ ለናቡከደነፆር ይገዙለት ዘንድ የብረትን ቀንበር በእነዚህ አሕዛብ ሁሉ አንገት ላይ አድርጌአለሁ፤ እነርሱም ይገዙለታል፤ የምድረ በዳ አራዊትን ደግሞ ሰጥቼዋለሁ።”'),
  ('2a5ad64f-9db8-5ac9-a3c7-fdc97ab8ea71', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 15, 15, 'ነቢዩም ኤርምያስ ሐሰተኛውን ሐናንያን፥ “ሐናንያ ሆይ ስማ፤ እግዚአብሔር አልላከህም፤ ነገር ግን ይህ ሕዝብ በሐሰት እንዲታመን አድርገሃል።'),
  ('e734898a-6115-5c46-a746-f846741972ef', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 16, 16, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ ከገጸ ምድር አስወግድሃለሁ፤ በእግዚአብሔር ላይ ዐመፅን ተናግረሃልና በዚህ ዓመት ትሞታለህ” አለው።'),
  ('28247f46-ce0a-5e71-aa7a-d02c018d20dd', '5344868b-b5a3-58e3-aab2-e731e98cfa4a', 'bab8fe25-2070-53d6-a65c-45a4260655f8', 17, 17, 'ሐሰተኛው ነቢይ ሐናንያም በዚያው ዓመት በሰባተኛው ወር ሞተ።'),
  ('35223c10-4bd6-5cdf-ada1-a9193fe15756', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 1, 1, 'ነቢዩ ኤርምያስ ወደ ተረፉት የምርኮ ሽማግሌዎች፥ ወደ ካህናቱም፥ ወደ ሐሰተኞች ነቢያቱም፥ ናቡከደነፆር ከኢየሩሳሌም ወደ ባቢሎን ማርኮ ወዳፈለሰውም ሕዝብ ሁሉ ከኢየሩሳሌም የላከው የደብዳቤው ቃል ይህ ነው።'),
  ('108f70e3-314d-5d7b-a9d0-2dc36a750fd1', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 2, 2, 'ይህም የሆነው ንጉሡ ኢኮንያንና እቴጌዪቱ፥ ጃንደረቦቹም፥ የይሁዳና የኢየሩሳሌምም አለቆች ነጻዎችና እሥረኞች፥ ብልሃተኞችና ብረት ሠራተኞችም ከኢየሩሳሌም ከወጡ በኋላ ነው።'),
  ('cb8a158b-3e87-5b85-acf5-b1e18e2b6ac6', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 3, 3, 'ኤርምያስም የይሁዳ ንጉሥ ሴዴቅያስ ወደ ባቢሎን ንጉሥ ወደ ናቡከደነፆር ወደ ባቢሎን በላካቸው በሳፋን ልጅ በኤልዓሣና በኬልቅያስ ልጅ በገማርያ እጅ ደብዳቤውን እንዲህ ሲል ላከው፦'),
  ('e5c7544d-3433-5990-a8f2-00fee1c10473', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 4, 4, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር ከኢየሩሳሌም ወደ ባቢሎን ላስማረክኋቸው ምርኮኞች ሁሉ እንዲህ ይላል፦'),
  ('e0dc0045-6d7a-5ab6-ac13-48a497841c97', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 5, 5, '“ቤት ሠርታችሁ ተቀመጡ፤ አታክልትም ተክላችሁ ፍሬዋን ብሉ፤ ተጋቡ፤ ወንዶችና ሴቶች ልጆችንም ውለዱ፤'),
  ('5a91556f-96a1-5d66-a54e-418e34ca28c6', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 6, 6, 'ወንዶችና ሴቶች ልጆቻችሁንም አጋቡ፤ እነርሱም ወንዶችና ሴቶች ልጆችን ይውለዱ፤ ከዚያም ተባዙ፤ ጥቂቶችም አትሁኑ።'),
  ('a5708e16-fefa-5c64-a6cb-93398b320da9', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 7, 7, 'በእርስዋ ሰላም፥ ሰላም ይሆንላችኋልና ወደ እርስዋ ላስማረክኋችሁ ሀገር ሰላምን ፈልጉ፥ ስለ እርስዋም ወደ እግዚአብሔር ጸልዩ።”'),
  ('ec77365e-b1a4-5ef0-a215-b0acc35148f0', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 8, 8, 'የእስራኤልም አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፥ “በመካከላችሁ ያሉት የሐሰት ነቢያቶቻችሁና ምዋርተኞቻችሁ አያታልሉአችሁ፤ ሕልም አላሚዎች አለምንላችሁ የሚሉአችሁን አትስሙ፥'),
  ('1e9cc404-f914-5192-a30f-aa808ef03d36', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 9, 9, 'በስሜ ሐሰተኛ ትንቢትን ይናገሩላችኋልና፤ እኔም አልላክኋቸውም፥” ይላል እግዚአብሔር።'),
  ('1e758b09-e3c2-5454-a2e4-76247d8447d5', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 10, 10, 'እግዚአብሔር እንዲህ ይላልና፦ ሰባው ዓመት በባቢሎን በተፈጸመ ጊዜ እጐበኛችኋለሁ፥ ወደዚህም ስፍራ እመልሳችሁ ዘንድ መልካሚቱን ቃሌን እፈጽምላችኋለሁ።'),
  ('453b2368-05ae-53a0-acec-0bad8034df5d', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 11, 11, 'ለእናንተ የማስባትን አሳብ እኔ አውቃለሁ ይላል እግዚአብሔር፤ ፍጻሜና ተስፋ እሰጣችሁ ዘንድ የሰላም አሳብ ነው እንጂ የክፉ ነገር አይደለም።'),
  ('c13dc480-dbc7-5d07-ac7e-8dbd7e20eca7', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 12, 12, 'እናንተም ትጠሩኛላችሁ፤ ሄዳችሁም ወደ እኔ ትጸልያላችሁ፤ እኔም እሰማችኋለሁ።'),
  ('cf056153-ddb3-5638-ac30-df7031b66d3c', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 13, 13, 'እናንተ ትሹኛላችሁ፤ በፍጹም ልባችሁም ከሻችሁኝ ታገኙኛላችሁ።'),
  ('abafa493-994a-5f7e-a023-b3b90952875d', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 14, 14, 'እገለጥላችኋለሁ፥ ይላል እግዚአብሔር፤ ምርኮአችሁንም እመልሳለሁ፤ ከአሕዛብ ሁሉ ዘንድ እናንተንም ከበተንሁበት ስፍራ ሁሉ እሰበስባችኋለሁ፤ ይላል እግዚአብሔር፤ እናንተንም ለምርኮ ወዳፈለስሁበት ስፍራ እመልሳችኋለሁ።'),
  ('e0a023ac-9c63-5ddc-a78a-5558a370cd60', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 15, 15, '“እናንተም፦ እግዚአብሔር በባቢሎን ነቢያትን አስነሥቶልናል ብላችኋልና፤'),
  ('0a929ae3-efed-5271-af57-b7b420a75db4', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 16, 16, 'እግዚአብሔር በዳዊት ዙፋን ስለ ተቀመጠ ንጉሥ፥ ከእናንተም ጋር ስላልተማረኩት ወንድሞቻችሁ፥ በዚህች ከተማ ስለሚኖሩ ሕዝብ ሁሉ እንዲህ ይላልና፦'),
  ('ec4849c1-06ad-50e6-ae55-7f93434370eb', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 17, 17, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ ሰይፍንና ራብን፥ ቸነፈርንም እሰድድባቸዋለሁ፤ ከመጐምዘዙም የተነሣ ይበላ ዘንድ እንደማይቻል እንደ ክፉ በለስ አደርጋቸዋለሁ።'),
  ('bcf9e6e5-d805-56d5-a59c-b5a1b33005c8', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 18, 18, 'በሰይፍና በራብ፥ በቸነፈርም አሳድዳቸዋለሁ፤ ባሳደድሁባቸውም አሕዛብ ሁሉ ዘንድ ለርግማንና ለጥፋት፥ ለማፍዋጫም፥ ለመሰደቢያም እንዲሆኑ በምድር መንግሥታት ሁሉ ዘንድ ለመበተን አሳልፌ እሰጣቸዋለሁ።'),
  ('1c250b20-33e4-5ad9-a98b-0a692e7684de', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 19, 19, 'ይህም የሆነው ቃሌን ስላልሰሙ ነው፥ ይላል እግዚአብሔር፤ በማለዳ ባሪያዎችን ነቢያትን ወደ እነርሱ ሰድጃለሁና፤ እናንተ ግን አልሰማችሁም፤ ይላል እግዚአብሔር።'),
  ('f15ceeb1-b2bf-56c9-a222-3ecfcad8fcd0', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 20, 20, 'ስለዚህ ከኢየሩሳሌም ወደ ባቢሎን የሰደድኋችሁ ምርኮኞች ሁሉ ሆይ! የእግዚአብሔርን ቃል ስሙ።”'),
  ('8e752dac-0dc6-5314-ae29-44f91afa1177', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 21, 21, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር በስሜ ሐሰተኛ ትንቢትን ስለሚናገሩላችሁ ስለ ቆልያ ልጅ፥ ስለ አክዓብና ሰለ ማሴው ልጅ ስለ ሴዴቅያስ እንዲህ ይላል፥ “እነሆ በባቢሎን ንጉሥ በናቡከደነፆር እጅ አሳልፌ እሰጣቸዋለሁ፤ በዐይኖቻችሁም ፊት ይገድላቸዋል።'),
  ('31c43b27-2069-5812-a01a-fff10e3b78a1', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 22, 22, 'ከእነርሱም የተነሣ በባቢሎን ያሉ የይሁዳ ምርኮኞች ሁሉ፦ የባቢሎን ንጉሥ በእሳት እንደ ጠበሳቸው እንደ ሴዴቅያስና እንደ አክዓብ እግዚአብሔር ያድርግህ የምትባል ርግማንን ያነሣሉ፤'),
  ('e001f8b6-0418-57a8-a709-51c276e94fe4', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 23, 23, 'በእስራኤል ዘንድ ክፉ አድርገዋልና፥ ከባልንጀሮቻቸውም ሚስቶች ጋር አመንዝረዋልና፥ ያላዘዝኋቸውንም ቃል በስሜ በሐሰት ተናግረዋልና። እኔም አውቃለሁ፤ ምስክርም ነኝ፥ ይላል እግዚአብሔር።”'),
  ('4364b7ad-2bd5-53cc-a61f-180dc9596ccf', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 24, 24, 'ለአሔልማዊው ለሸማያ እንዲህ በል፦'),
  ('9d1e9508-aa51-5420-a48a-047d543095ee', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 25, 25, '“የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በኢየሩሳሌም ወደ አለው ሕዝብ ሁሉ፥ ወደ ካህኑም ወደ ማሴው ልጅ ወደ ሶፎንያስ፥ ወደ ካህናቱም ሁሉ ደብዳቤዎችን በስሜ እንዲህ ስትል ልከሃል፦'),
  ('eeb43cd2-5041-5d66-a0ee-bc21ab150249', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 26, 26, 'ትንቢት የሚናገረውን ሰው ሁሉ፥ የሚለፈልፈውንም ሰው ሁሉ በግዞት ታኖረውና በፈሳሽም ታሰጥመው ዘንድ በእግዚአብሔር ቤት አለቃ እንድትሆን እግዚአብሔር በካህኑ በዮዳሄ ፋንታ ካህን አድርጎሃል።'),
  ('021090b4-dc9c-5c39-a286-6f82c422ae08', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 27, 27, 'አሁንስ ትንቢት ተናጋሪውን የአናቶቱን ሰው ኤርምያስን ስለ ምን አትዘልፈውም?'),
  ('91cbef78-fbb4-598e-a9f6-d0a8c04d64e6', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 28, 28, 'እርሱ፦ ምርኮው የረዘመ ነውና ቤት ሠርታችሁ ተቀመጡ፤ አታክልትም ተክላችሁ ፍሬዋን ብሉ ብሎ ወደ እኛ ወደ ባቢሎን ልኮአልና።”'),
  ('8b1c1ceb-0a27-5e9a-a5d9-d7eebf9558e5', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 29, 29, 'ካህኑም ሶፎንያስ ይህን ደብዳቤ በነቢዩ በኤርምያስ ጆሮ አነበበው።'),
  ('c3562289-4017-5304-ac64-ebadbd3b034b', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 30, 30, 'የእግዚአብሔርም ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('83e7165b-a1ae-50b2-a0b6-a30c49b4ba01', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 31, 31, '“እግዚአብሔር ስለ አሔልማዊው ስለ ሸማያ እንዲህ ይላል ብለህ ወደ ምርኮኞች ሁሉ ላክ፦ እኔ ሳልልከው ሸማያ ትንቢት ተናግሮላችኋልና፥ በሐሰትም እንድትታመኑ አድርጓችኋልና።'),
  ('999d1841-3dd4-53e2-ac42-6c523ef22425', '99ce884e-c28b-5b98-a959-28ad46571b0e', '2e3ee13c-facd-5c7b-a1bd-256f115e52f6', 32, 32, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ አሔልማዊውን ሸማያንና ዘሩን እቀጣለሁ፤ እኔም ለሕዝቤ የማደርገውን መልካሙን ነገር የሚያይ ሰው በመካከላችሁ አይኖርላቸውም፤ ይላል እግዚአብሔር፤ በእግዚአብሔር ላይ ዐመፃን ተናግሮአልና።”'),
  ('4719916e-fac6-5d4a-aecf-2c5b75782c7c', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 1, 1, 'ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣው ቃል ይህ ነው። እንዲህም አለው፤'),
  ('55204441-7cdf-5acc-a01c-cace67b0949b', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 2, 2, '“የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ የነገርሁህን ቃል ሁሉ በመጽሐፍ ጻፍ።'),
  ('ec84affe-3901-5a7c-ac0f-892f3523e9b6', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 3, 3, 'እነሆ! የሕዝቤን የእስራኤልንና የይሁዳን ምርኮ የምመልስበት ዘመን ይመጣልና፥ ይላል እግዚአብሔር፤ ለአባቶቻቸውም ወደ ሰጠኋት ምድር እመልሳቸዋለሁ፤ እነርሱም ይገዙአታል።”'),
  ('7c25e918-3a9a-56fd-ad73-2b5f5e2afebf', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 4, 4, 'እግዚአብሔር በእስራኤልና በይሁዳ ላይ የተናገረው ቃል ይህ ነው።'),
  ('0f4877d5-5fd0-583b-a5c2-2e6ecb2b38b6', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 5, 5, 'እግዚአብሔር እንዲህ ይላልና፥ “የሚያስፈራ ድምፅ ትሰማላችሁ፤ ፍርሀት ነው እንጂ ሰላም አይደለም።'),
  ('2335ff3d-37e5-524b-ad02-8874ae727796', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 6, 6, 'ጠይቁ፤ ወንድ ይወልድ እንደ ሆነ ተመልከቱ፤ ስለ ምን ሰው ሁሉ እንደ ወላድ እጁን በወገቡ ላይ አድርጎ፥ ፊቱም ሁሉ ወደ ጥቍረት ተለውጦ አየሁ?'),
  ('81fe4b64-f13e-5d08-aa6e-8cc11ba898e8', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 7, 7, 'ወዮ! ያ ቀን ታላቅ ነውና፥ እርሱንም የሚመስል የለምና፤ ያ የያዕቆብ መከራ ዘመን ነው፤ ነገር ግን ከእርሱ ይድናል።'),
  ('3a2c238a-f1ac-59a4-acc8-46cf2e938985', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 8, 8, 'በዚያ ቀን እንዲህ ይሆናል፥ ይላል የሠራዊት ጌታ እግዚአብሔር፤ ቀንበርን ከአንገትህ እሰብራለሁ፤ እስራትህንም እበጥሳለሁ፤ ከእንግዲህም ወዲህ ለሌላ አትገዛም።'),
  ('20a2e587-2c53-5eb3-a0d9-eed35c645b0b', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 9, 9, 'ለአምላካቸው ለእግዚአብሔርም፥ ለማስነሣላቸው ለንጉሣቸው ለዳዊትም ይገዛሉ።'),
  ('fbbcb165-c973-561a-a410-5c062cef6ecd', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 10, 10, '“እነሆ አንተን ከሩቅ፥ ዘርህንም ከምርኮ ሀገር አድናለሁና ባሪያዬ ያዕቆብ ሆይ! አትፍራ፥ ይላል እግዚአብሔር፤ አንተም እስራኤል ሆይ! አትደንግጥ፤ ያዕቆብም ይመለሳል፤ ያርፍማል፤ ተዘልሎም ይቀመጣል፤ ማንም አያስፈራውም።'),
  ('2cb75337-936a-5885-a6f0-5949f9763f92', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 11, 11, 'አድንህ ዘንድ ከአንተ ጋር ነኝና፥ ይላል እግዚአብሔር፤ አንተንም የበተንሁባቸውን አሕዛብን ሁሉ ፈጽሜ አጠፋለሁ፤ አንተን ግን ፈጽሜ አላጠፋህም፤ በመጠን እቀጣሃለሁ፥” ያለ ቅጣትም ከቶ አልተውህም።”'),
  ('83aa688d-9630-5230-a15d-13555899614f', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 12, 12, 'እግዚአብሔር እንዲህ ይላል፥ “ስብራትህ የማይፈወስ፥ ቍስልህም ክፉ ነው።'),
  ('3dbb1363-49ab-566b-af92-a1c9e211d3c1', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 13, 13, 'ትጠገን ዘንድ ክርክርህን የሚፈርድልህ ሰው የለም፤ ቍስልህንም የሚፈውስ መድኀኒት የለህም።'),
  ('9acca982-7340-595a-a2d3-aaeb03f59c65', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 14, 14, 'ወዳጆችህ ሁሉ ረስተውሃል፤ አይፈልጉህምም፤ በደልህ ታላቅ ስለ ሆነ፥ ኀጢአትህም ስለ በዛ፥ በጠላት ማቍሰልና በጨካኝ ቅጣት አቍስዬሃለሁና።'),
  ('389c1573-d1fb-5da9-a38f-40b7d866e7ea', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 15, 15, 'ቍስልህ የማይፈወስ ሆኖአልና ስለ ስብራትህ ለምን ትጮኻለህ? በደልህ ታላቅ ስለ ሆነ፥ ኀጢአትህም ስለ በዛ፥ ይህን አድርጌብሃለሁ።'),
  ('3d2de11a-1fe9-5680-a611-2de62da55b36', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 16, 16, 'ስለዚህ የሚበሉህ ሁሉ ይበላሉ፤ የሚማርኩህም ሁላቸው ይማረካሉ፤ የዘረፉህም ይዘረፋሉ፤ የሚማርኩህንም ሁሉ ለመማረክ አሳልፌ እሰጣለሁ።'),
  ('d9aa36fa-0ffa-53df-a0aa-5ef969d0762e', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 17, 17, 'እኔ ከክፉ ቍስልሽ እፈውስሻለሁ፤ ጤናሽን እመልስልሻለሁ፤ ቍስልሽንም እፈውሳለሁ፥ ይላል እግዚአብሔር፤ ማንም የማይሻት፥ የተጣለች ጽዮን ብለው ጠርተውሻልና።”'),
  ('57e2bad0-fe90-5bf7-a5b4-466728b09e24', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 18, 18, 'እግዚአብሔር እንዲህ ይላል፥ “እነሆ የያዕቆብን ድንኳን ምርኮ እመልሳለሁ፤ ለማደሪያውም እራራለሁ፤ ከተማዪቱም በጕብታዋ ላይ ትሠራለች፤ አዳራሹም እንደ ዱሮው የሰው መኖሪያ ይሆናል።'),
  ('487c8756-4be4-5b48-a878-c67180187cb9', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 19, 19, 'ከእርሱም ዘንድ የምስጋናና የዘፈን ድምፅ ይወጣል፤ እኔም አበዛቸዋለሁ፤ አያንሱምም።'),
  ('271332b1-93bf-57df-ae85-0c3ded6502ea', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 20, 20, 'ልጆቻቸውም እንደ ቀድሞው ይሆናሉ፤ ምስክርነታቸውም በፊቴ ጸንቶ ይኖራል፤ የሚያስጨንቁአቸውንም ሁሉ እቀጣለሁ።'),
  ('6214cdd0-5f81-58ef-afe8-2d140a4ae9f3', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 21, 21, 'አለቃቸውም ከእነርሱ ውስጥ ይሾማል፤ ገዢአቸውም ከመካከላቸው ይወጣል፤ እሰበስባቸዋለሁ፤ ወደ እኔም እመልሳቸዋለሁ፤ ወደ እኔ ይመለስ ዘንድ ልብ የሰጠው ማን ነው? ይላል እግዚአብሔር።'),
  ('63f0a421-a1e2-5e38-ac26-df163c7c61c9', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 22, 22, 'እናንተም ሕዝብ ትሆኑኛላችሁ እኔም አምላክ እሆናችኋለሁ።”'),
  ('4d611219-91e5-5f49-a016-10dba36f2546', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 23, 23, 'እነሆ የእግዚአብሔር ቍጣ ለመቅሠፍት ወጥቶአል፤ የመዓቱንም ጥፋት በኃጥኣን ራስ ላይ አምጥቶአል፤'),
  ('a1ff158c-e4f8-5220-ad85-e2f60d1c2464', '4827519c-3f61-56f4-a979-f4a5161b416c', '8baaa391-f03f-5ad8-a5e5-34ddcea86844', 24, 24, 'የእግዚአብሔር ጽኑ ቍጣ የልቡን አሳብ ሠርቶ እስኪፈጽም ድረስ አይመለስም፤ በኋለኛውም ዘመን ታውቁታላችሁ።'),
  ('3141ec0d-44be-5d4d-a5ec-397513f248cc', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 1, 1, 'በዚያ ዘመን ይላል እግዚአብሔር፤ ለእስራኤል ወገኖች ሁሉ አምላክ እሆናቸዋለሁ፤ እነርሱም ሕዝብ ይሆኑኛል።'),
  ('1e9b07a0-47ee-59bb-a284-4916d48def5b', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “ከሰይፍ የተረፈው ሕዝብ በምድረ በዳ ሞገስ አገኘ። ሂዱ፦ እስራኤልንም አታጥፉ።”'),
  ('c8f3b4a9-0939-5188-a479-9048afa6f3f9', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 3, 3, 'እግዚአብሔርም ከሩቅ ተገለጠልኝ፤ እንዲህም አለኝ፥ “በዘለዓለም ፍቅር ወድጄሃለሁ፤ ስለዚህ በቸርነት ሳብሁህ።'),
  ('4f8cc131-9374-5dba-a9c8-4cee32676be7', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 4, 4, 'የእስራኤል ድንግል ሆይ እንደ ገና እሠራሻለሁ፤ አንቺም ትሠሪያለሽ፤ እንደ ገናም ከበሮሽን አንሥተሽ ከዘፋኞች ጋር ትወጫለሽ።'),
  ('711af1e6-7191-5e67-a548-50e76a0cdb3d', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 5, 5, 'እንደ ገናም በሰማርያ ተራሮች ላይ የወይን ተክሎችን ትተክሊአለሽ፤ የምትተክሉ ትከሉ፤ አመስግኑም፤'),
  ('00f6608b-194f-5229-a803-4e58174de95e', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 6, 6, 'በኤፍሬም ተራሮች ላይ የሚከራከሩ፦ ተነሡ፤ ወደ ጽዮን ወደ አምላካችን ወደ እግዚአብሔር እንውጣ ብለው የሚጠሩባት ቀን ትመጣለችና።”'),
  ('bf955804-37ed-54e6-acfa-53b575f8de4a', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 7, 7, 'እግዚአብሔር እንዲህ ይላልና፥ “የያዕቆብ ቤት ሆይ! ደስ ይበላችሁ፤ በአሕዛብም አለቆች ላይ እልል በሉ፤ አውሩ፤ አመስግኑም፤ እግዚአብሔርም ሕዝቡን የእስራኤልን ቅሬታ አድኖአል በሉ።'),
  ('517059f4-9da1-5748-ac43-512e8ee3d465', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 8, 8, 'እነሆ፥ ከሰሜን ሀገር አመጣቸዋለሁ፤ ከምድርም ዳርቻ ለበዓለ ፋሲካ እሰበስባቸዋለሁ፤ ብዙ አሕዛብም ይወለዳሉ፤ ወደዚህም ይመለሳሉ።'),
  ('e60e8ef2-fdbc-50f4-a5bc-3b586e37c28e', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 9, 9, 'እያለቀሱ ሄዱ፤ እኔም በማጽናናት አመጣቸዋለሁ፤ በወንዝ ዳር በቅን መንገድ አስሄዳቸዋለሁ፤ በእርሱም አይሰናከሉም፤ እኔ ለእስራኤል አባት ነኝና፥ ኤፍሬምም በኵሬ ነውና።”'),
  ('3bb74329-e502-59c1-a941-0139b7a793d5', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 10, 10, 'አሕዛብ ሆይ! የእግዚአብሔርን ቃል ስሙ፤ በሩቅም ላሉ ደሴቶች አውሩና፥ “እስራኤልን የበተነ እርሱ ይሰበስበዋል፤ እረኛም መንጋውን እንደሚጠብቅ ይጠብቀዋል በሉ።'),
  ('b9bbcb04-cd0d-500e-a8a5-078a22dfc158', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 11, 11, 'እግዚአብሔር ያዕቆብን ተቤዥቶታል፤ ከበረቱበትም እጅ አድኖታል።'),
  ('22cd83f4-6974-5c4d-a5fb-618f3696804e', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 12, 12, 'ይመጣሉ፤ በጽዮንም ተራራ ደስ ይላቸዋል፤ ወደ እግዚአብሔርም በጎነት፥ ወደ እህልና ወደ ወይን ጠጅ፥ ወደ ዘይትም፥ ወደ በጎችና ወደ ላሞች ሀገርም ይሰበሰባሉ፤ ነፍሳቸውም እንደ ረካች ገነት ትሆናለች፤ ከእንግዲህም ወዲህ አይራቡም።'),
  ('9285d669-206e-579a-a5a6-53ba349ed8fb', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 13, 13, 'በዚያን ጊዜም ደናግሉ በዘፈን ደስ ይላቸዋል፤ ጐበዛዝቱና ሽማግሌዎቹም በአንድ ላይ ደስ ይላቸዋል፤ እኔም ልቅሶአቸውን ወደ ደስታ እመልሳለሁ፤ ከኀዘናቸውም ደስ አሰኛቸዋለሁ።'),
  ('bfa23b58-aa58-54e5-a8de-9b0492854003', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 14, 14, 'የካህናቱንም የሌዊን ልጆች ሰውነት ከፍ ከፍ አደርጋታለሁ፤ አረካታለሁ፤ ሕዝቤም ከበረከቴ ይጠግባል፥” ይላል እግዚአብሔር።'),
  ('38913c15-bcc4-519a-a228-04999a679449', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 15, 15, 'እግዚአብሔር እንዲህ ይላል፥ “የኀዘን፥ የልቅሶና የጩኸት ድምፅ በራማ ተሰማ፤ ራሔል ስለ ልጆችዋ አለቀሰች፤ የሉምና ስለ ልጆችዋ መጽናናትን እንቢ አለች።'),
  ('98619fec-0a25-5bfb-aa84-b4b949ca41b7', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 16, 16, 'እግዚአብሔር እንዲህ ይላል፦ ድምፅሽን ከልቅሶ፥ ዐይኖችሽንም ከእንባ ከልክዪ፤ ለሥራሽ ዋጋ ይሆናልና፥ ይላል እግዚአብሔር፤ ከጠላትም ምድር ይመለሳሉ።'),
  ('46da2933-d08e-57a2-ab85-8361ea8d1e49', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 17, 17, 'ለፍጻሜሽም ተስፋ አለ፥ ይላል እግዚአብሔር፥ ልጆችሽም ወደ ሀገራቸው ይመለሳሉ።'),
  ('a241eb1d-e93e-5b36-aac3-19ac4908e1c4', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 18, 18, '“ኤፍሬም ሲጨነቅ መስማትን ሰማሁ፤ እንዲህም አለ፦ ቀጣኸኝ እኔም እንዳልቀና ወይፈን ተቀጣሁ፤ አንተ እግዚአብሔር አምላኬ ነህና መልሰኝ፤ እኔም እመለሳለሁ።'),
  ('46c2597b-aafd-5e22-a253-ec1ce06cb21f', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 19, 19, 'ከተመለስሁ በኋላ ተጸጸትሁ፤ ከተገሠጽሁም በኋላ ጭኔን ጸፋሁ፤ የብላቴንነቴንም ስድብ ተሸክሜአለሁና አፈርሁ፥ ተዋረድሁም።'),
  ('d8355704-41ba-54ed-a17d-e6fd5da6d2e5', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 20, 20, 'በእውነት ኤፍሬም ለእኔ የተወደደ ልጅ ነው፤ ደስ የሚያሰኝም ሕፃን ነው፤ በእርሱ ላይ በተናገርሁ ቍጥር አስበዋለሁ፤ ስለዚህ አንጀቴ ታወከችለት፤ ርኅራኄም እራራለታለሁ፥” ይላል እግዚአብሔር።')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b7d1c47d-f0b2-550c-a888-d5d5d52d256a', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 21, 21, '“ለራስሽ የመንገድ ምልክት አድርጊ፥ መንገድንም የሚመሩ ዐምዶችን ትከዪ፤ ልብሽንም ወደ ሄድሽበት መንገድ ወደ ጥርጊያው አቅኚ፤ አንቺ የእስራኤል ድንግል ሆይ! ተመለሺ፤ ወደ እነዚህም ወደ ከተሞችሽ እያለቀስሽ ተመለሺ።'),
  ('9761192e-9ebf-5f14-a99e-25f8b7d275a8', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', 'd96ab03a-0d0b-509c-a26c-73aa4758a2b4', 22, 22, 'አንቺ ከዳተኛ ልጅ ሆይ! እስከ መቼ ትቅበዘበዣለሽ? እግዚአብሔር በምድር ላይ አዲስ ነገር ፈጥሮአልና ሰው ወደ ድኅነት ይመጣል።”'),
  ('72fb9c1a-f508-5199-ada8-0ef2ea629197', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 1, 23, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “ምርኮአቸውን በመለስሁ ጊዜ በይሁዳ ሀገር በከተሞችዋ፦ የጽድቅ ማደሪያ ሆይ! የቅድስና ተራራ ሆይ! እግዚአብሔር ይባርክህ የሚል ነገርን እንደ ገና ይናገራሉ።'),
  ('119af764-0629-5ac3-a3fd-015905cc2ec4', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 2, 24, 'በይሁዳ ከተሞችና በሀገሩ ሁሉ ከገበሬዎችና መንጋን ይዘው ከሚዞሩ ጋር የሚኖሩ ሰዎች ይገኛሉ።'),
  ('61437ba1-bf85-5925-a912-d9ca56db8543', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 3, 25, 'የተጠማችውን ነፍስ ሁሉ አርክቻለሁና፥ የተራበችውንም ነፍስ ሁሉ አጥግቤአለሁና።'),
  ('dc1f6dda-6351-5401-a9cd-77ef85607eb7', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 4, 26, 'ስለዚህ ነቃሁ፤ ተመለከትሁም፤ እንቅልፌም ጣፈጠኝ።'),
  ('979a721e-5dd9-5c45-a5a2-d08bc134a447', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 5, 27, '“በእስራኤል ቤትና በይሁዳ ቤት የሰው ዘርና የእንስሳ ዘር የምዘራበት ዘመን እነሆ ይመጣል፥ ይላል እግዚአብሔር።'),
  ('ba52a13f-f86a-51fc-a4c8-eabefb0efbec', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 6, 28, 'እንዲህም ይሆናል፤ አፈርሳቸውና ክፉ አደርግባቸው ዘንድ እንደ ተጋሁባቸው፥ እንዲሁ እሠራቸውና እተክላቸው ዘንድ እተጋለሁ፥” ይላል እግዚአብሔር።'),
  ('e1de4afe-c435-5e1b-ae09-734a83f28e0e', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 7, 29, 'በዚያ ዘመን ሰው ዳግመኛ እንዲህ አይልም፦ አባቶች ጮርቃ የወይን ፍሬ በሉ፤ የልጆችም ጥርሶች ጠረሱ፤'),
  ('435a576f-f691-55fd-a0fd-1e81c46e267a', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 8, 30, 'ነገር ግን ሰው ሁሉ በገዛ በደሉ ይሞታል፤ ጮርቃውን የወይን ፍሬ የሚበላም ሁሉ ጥርሶቹ ይጠርሳሉ።'),
  ('ff7996b8-a24d-5c37-a826-894701c81e37', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 9, 31, '“እነሆ ከእስራኤል ቤትና ከይሁዳ ቤት ጋር አዲስ ቃል ኪዳን የምገባበት ወራት ይመጣል፥ ይላል እግዚአብሔር፤'),
  ('463608b7-2d16-5855-a0d6-c4d047da88c3', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 10, 32, 'ከግብፅ ሀገር አወጣቸው ዘንድ እጃቸውን በያዝሁበት ቀን ከአባቶቻቸው ጋር እንደ ገባሁት ያለ ቃል ኪዳን አይደለም፤ እነርሱ በኪዳኔ አልጸኑምና፥ እኔም ቸል አልኋቸው፥ ይላል እግዚአብሔር።'),
  ('c1030deb-f091-5fd5-a4b6-497226ceb4a1', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 11, 33, 'ከእነዚያ ወራት በኋላ ከእስራኤል ቤት ጋር የምገባው ቃል ኪዳን ይህ ነውና፥ ይላል እግዚአብሔር፤ ሕጌን በልቡናቸው አኖራለሁ፤ በልባቸውም እጽፈዋለሁ፤ እኔም አምላክ እሆናቸዋለሁ፤ እነርሱም ሕዝብ ይሆኑኛል።'),
  ('21218df2-9d02-5ab5-ac68-2228cb5ff3e4', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 12, 34, 'እያንዳንዱ ሰው ባልንጀራውን፥ እያንዳንዱም ወንድሙን፦ እግዚአብሔርን ዕወቅ ብሎ አያስተምርም፤ ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሁሉ ያውቁኛልና፥ ይላል እግዚአብሔር። በደላቸውን እምራቸዋለሁና፥ ኀጢአታቸውንም ከእንግዲህ ወዲህ አላስብምና።”'),
  ('a2b57af8-21de-57ac-a9aa-798ab368848d', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 13, 35, 'ስሙ የሠራዊት ጌታ የሚባል፥ ፀሐይን በቀን፥ ጨረቃንና ከዋክብትንም በሌሊት ብርሃን አድርጎ የሚሰጥ፥ እንዲተምሙም የባሕርን ሞገዶች የሚያናውጥ እግዚአብሔር እንዲህ ይላል፦'),
  ('7fc2c20b-667e-5281-a33d-25603e4c5a1f', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 14, 36, '“ይህ ሕግ ከፊቴ ቢወገድ፥ ይላል እግዚአብሔር፥ በዚያ ጊዜ ደግሞ የእስራኤል ዘር በፊቴ ሕዝብ እንዳይሆን ለዘለዓለም ይቀራል።”'),
  ('1ea6c4c2-a024-5aa9-a811-f0086ee0f2eb', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 15, 37, 'እግዚአብሔር እንዲህ ይላል፥ “ሰማይ እጅግ ከፍ ቢል፥ የምድርም መሠረት ፈጽሞ ዝቅ ቢል በዚያ ጊዜ ስላደረጉት ነገር ሁሉ፥ የእስራኤልን ዘር ሁሉ እንቃለሁ ይላል እግዚአብሔር።'),
  ('f28e3703-1db7-50f8-a662-c7537175beda', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 16, 38, '“ከአናምሄል ግንብ ጀምሮ እስከ ማዕዘኑ በር ድረስ ከተማ ለእግዚአብሔር የሚሠራበት ዘመን እነሆ ይመጣል፥” ይላል እግዚአብሔር።'),
  ('cca1187d-52a7-5c8b-ad0f-dd706e1b9fe0', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 17, 39, 'መጠንዋ ወደ ጋሬብ ኮረብታ በቀጥታ ወደ ፊት ይሄዳል፤ ወደ ጎዓትም ይዞራል።'),
  ('f1577a45-007f-5a62-a896-f29dfea93a85', '0fdf3bca-a768-5ecf-ac6a-a5d0e623b9a5', '39bef002-7e98-543a-af6f-51f23d8cbd63', 18, 40, 'የአስሬሞትም ሸለቆ ሁሉ እስከ ቄድሮን ወንዝ ድረስ በምሥራቅ በኩል እስካለው እስከ ፈረስ በር ማዕዘን ድረስ ለእግዚአብሔር የተቀደሰ ይሆናል፤ ከእንግዲህም ወዲህ ለዘለዓለም አይነቀልም፤ አይፈርስምም።'),
  ('87648bc6-afc8-5b3c-a638-16f75a318d3b', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 1, 1, 'በይሁዳ ንጉሥ በሴዴቅያስ በዐሥረኛው ዓመተ መንግሥት፥ በባቢሎን ንጉሥ በናቡከደነፆር በዐሥራ ስምንተኛው ዓመተ መንግሥት ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣው ቃል ይህ ነው።'),
  ('c6679570-93eb-547f-a7af-9a0f770eb16a', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 2, 2, 'በዚያ ጊዜም የባቢሎን ንጉሥ ሠራዊት ኢየሩሳሌምን ከብቦ ነበር፤ ነቢዩ ኤርምያስም በይሁዳ ንጉሥ ቤት በነበረው በግዞት ቤት አደባባይ ታስሮ ነበር።'),
  ('e390d903-8c5a-58a9-a1b7-c7bc28241916', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 3, 3, 'የይሁዳ ንጉሥ ሴዴቅያስ እንዲህ ብሎ አስጠብቆት ነበርና፥ “እግዚአብሔር እንዲህ ይላል፦ እነሆ ይቺን ከተማ ለባቢሎን ንጉሥ እጅ አሳልፌ እሰጣለሁ፤ እርሱም ይይዛታል ብለህ ስለምን ትንቢት ትናገራለህ?'),
  ('61d72897-4991-506d-a52b-4d312266f976', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 4, 4, 'የይሁዳም ንጉሥ ሴዴቅያስ በእውነት በባቢሎን ንጉሥ እጅ አልፎ ይሰጣል፤ አፍ ለአፍም ይናገረዋል፤ ዐይን ለዐይንም ይተያያሉ እንጂ ከከለዳውያን እጅ አያመልጥም፤'),
  ('ec59bb15-806c-5feb-a25e-ac772519e027', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 5, 5, 'ሴዴቅያስም ወደ ባቢሎን ይገባል፤ እኔም እስክጐበኘው ድረስ በዚያ ይኖራል፥ ይላል እግዚአብሔር፤ ከከለዳውያን ጋር ብቷጉ ምንም አይቀናችሁም።”'),
  ('7a392987-a07f-5b47-a0ed-bfc6d96c2da5', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 6, 6, 'የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('28034778-bdbc-5547-aca1-a82742c6c18d', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 7, 7, '“እነሆ የአጎትህ የሰሎም ልጅ አናምኤል ወደ አንተ መጥቶ፦ ትገዛው ዘንድ የመቤዠቱ መብት የአንተ ነውና በዓናቶት ያለውን እርሻዬን ግዛ” ይልሃል።'),
  ('d997ccb4-1a15-5ae0-addb-9a19eb1c119d', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 8, 8, 'እንደ እግዚአብሔርም ቃል የአጎቴ ልጅ አናምኤል እኔ ወደ አለሁበት ወደ ግዞቱ ቤት አደባባይ መጥቶ፥ “በብንያም ሀገር በዓናቶት ያለውን እርሻዬን ግዛ፤ የመግዛትና የመውረስ መብቱ የአንተ ነውና፥ አንተ ታላቃችን ነህና፤ ለአንተ ግዛው” አለኝ። ይህም የእግዚአብሔር ቃል እንደ ሆነ ዐወቅሁ።'),
  ('f702ae57-32d0-5b79-ab4f-976babdc6832', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 9, 9, 'በዐናቶትም ያለውን እርሻ ከአጎቴ ልጅ ከአናምኤል ገዛሁ፤ ዐሥራ ሰባት ሰቅል ብርም መዘንሁለት።'),
  ('e48c6a47-c2a2-573e-ab58-d5266c49c00f', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 10, 10, 'የውሉንም ወረቀት ጻፍሁ፤ አተምሁትም፤ ምስክሮችንም ጠርቼ ብሩን በሚዛን መዘንሁለት።'),
  ('7ebc01fd-d1bb-5fd3-a001-247df3e86d79', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 11, 11, 'የታተመውንም የውል ወረቀት ወሰድሁ፤'),
  ('f13694d9-7620-5d02-a36b-491026f27e3e', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 12, 12, 'የአጎቴም ልጅ አናምኤል፥ የውሉንም ወረቀት የፈረሙ ምስክሮች፥ በግዞት ቤት አደባባይ የተቀመጡ አይሁድም ሁሉ እያዩ የውሉን ወረቀት ለማሴው ልጅ ለኔርያ ልጅ ለባሮክ ሰጠሁት።'),
  ('210cbd8c-568c-560e-ab23-1416eb625b63', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 13, 13, 'በፊታቸውም እንዲህ ብዬ ባሮክን አዘዝሁት፦'),
  ('0a1c63b8-d768-5cd6-a3e6-1986195a87dc', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 14, 14, '“የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ብዙ ቀን ይጠበቅ ዘንድ የታተመውን ይህን የውል ወረቀት ወስደህ በሸክላ ዕቃ ውስጥ አኑረው።'),
  ('42f60ff1-d45c-5c15-affe-5b64137ac734', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '962702a1-ef61-5e52-a50f-3d903c5415ac', 15, 15, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ ሰዎች በዚህ ምድር ቤትንና እርሻን የወይን ቦታንም እንደ ገና ይገዛሉ።”'),
  ('b354119e-1be9-5319-ac18-018af209e61d', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 1, 16, 'ለኔርያ ልጅ ለባሮክም የውሉን ወረቀት ከሰጠሁት በኋላ፥ እንዲህ ብዬ ወደ እግዚአብሔር ጸለይሁ፦'),
  ('2b4cb77d-0b79-5861-a99a-2b9822d7fe73', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 2, 17, '“ወዮ! አቤቱ ጌታ እግዚአብሔር ሆይ! እነሆ አንተ ሰማይንና ምድርን በታላቅ ኀይልህና በተዘረጋች ክንድህ ፈጥረሃል፤ ከአንተም የሚሳን ምንም ነገር የለም።'),
  ('9ca9d02b-2303-5413-a5ea-74ffdeb949ab', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 3, 18, 'ታላቅና ኀያል አምላክ ሆይ! ለብዙ ሺህ ምሕረትን ታደርጋለህ፤ የአባቶችንም በደል ከእነርሱ በኋላ በልጆቻቸው ብብት ትመልሳለህ።'),
  ('575ffe90-06cf-5b4b-ad53-66ccbfffe35b', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 4, 19, 'እግዚአብሔር በምክር ታላቅ በሥራም ብርቱ ነህ፤ ስምህ ታላቅ የሆነ፥ ኀያል፥ ሁሉን ቻይ እግዚአብሔር ለሁሉም እንደ መንገዱና እንደ ሥራው ፍሬ ትሰጥ ዘንድ ዐይኖችህ በሰው ልጆች መንገድ ሁሉ ተገልጠዋል።'),
  ('59a50de9-f47f-5748-aa9c-25ded914e553', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 5, 20, 'እስከ ዛሬም ድረስ ምልክትንና ድንቅን ነገር በግብፅ ምድር፥ ደግሞም በእስራኤልና በሌሎች ሰዎች መካከል አድርገሃል፤ እንደ ዛሬም ለአንተ ስም አድርገሃል።'),
  ('258b278e-7c86-595f-a994-b6489eb81721', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 6, 21, 'በምልክትና በድንቅ ነገር፥ በብርቱ እጅና በተዘረጋች ክንድ፥ በታላቅም ግርማ ሕዝብህን እስራኤልን ከግብፅ ምድር አወጣህ።'),
  ('c8f69bbd-9c92-5d6c-a495-20fe8301800c', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 7, 22, 'ትሰጣቸውም ዘንድ ለአባቶቻቸው የማልህላቸውን ምድር፥ ወተትና ማርም የምታፈስሰውን ምድር ሰጠሃቸው፤'),
  ('84dba86a-b446-5c20-af24-9f3b10e2042c', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 8, 23, 'እነርሱም ገብተው ወረሱአት፤ ነገር ግን ቃልህን አልሰሙም፤ በሕግህም አልሄዱም፤ ያደርጉም ዘንድ ካዘዝሃቸው ሁሉ ምንም አላደረጉም፤ ስለዚህ ይህን ክፉ ነገር ሁሉ አመጣህባቸው።'),
  ('ae0b4eac-c9b9-5145-a4d2-1fbe5c7e041f', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 9, 24, 'አሕዛብም መጥተው ይህችን ሀገር ያዟት፤ ይህችም ከተማ ከረኃቡና ከጦሩ የተነሣ በወጓት በከለዳውያን ሰዎች እጅ ወደቀች፤ እንደ ተናገርኸውም ሆነ።'),
  ('26ddfdd2-0532-5fcd-a8bf-d5aa94aacb41', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 10, 25, 'አንተም ጌታ እግዚአብሔር ሆይ! እርሻውን በብር ግዛ፤ ምስክሮችንም ጥራ አልኸኝ፤ እኔም ውሉን ጽፌ አተምሁ፤ ምስክሮችንም አቆምሁ፤ ከተማዪቱ ግን ለከለዳውያን እጅ ተሰጥታለች።”'),
  ('d45326b0-e66f-583b-ac71-8d6f653f9c1b', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 11, 26, 'የእግዚአብሔርም ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('1d75af3f-79f4-57cb-ad57-4ed77a91a36b', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 12, 27, '“እነሆ እኔ የሥጋ ለባሽ ሁሉ አምላክ እግዚአብሔር ነኝ፤ በውኑ ከእኔ የሚሰወር ነገር አለን?'),
  ('111e6c16-b6f2-5493-af50-1294820059c2', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 13, 28, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፦ እነሆ ይችን ከተማ ለከለዳውያን እጅና ለባቢሎን ንጉሥ ለናቡከደነፆር እጅ አሳልፌ እሰጣለሁ፤ እርሱም ይይዛታል።'),
  ('bc7e492a-fffe-589b-a46c-7277b0709b6a', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 14, 29, 'ይችን ከተማ የሚወጉ ከለዳውያን ይመጣሉ፤ ከተማዋንም በእሳት ያነድዱአታል፤ ያስቈጡኝም ዘንድ በሰገነታቸው ላይ ለበዓል ያጠኑባቸውን፥ ለሌሎችም አማልክት የመጠጥን ቍርባን ያፈሰሱባቸውን ቤቶች ያቃጥሉአቸዋል።'),
  ('32306ecc-83f1-585b-a131-9304b724c3d1', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 15, 30, 'የእስራኤል ልጆችና የይሁዳ ልጆች ከታናሽነታቸው ጀምሮ በፊቴ ክፉ ነገርን ብቻ አድርገዋልና፤ የእስራኤልም ልጆች እኔን በእጃቸው ሥራ ከማስቈጣት በቀር ሌላ ሥራ አላደረጉምና፥ ይላል እግዚአብሔር።'),
  ('a78a332f-7889-5670-a4a3-4cb4f3505606', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 16, 31, 'ከፊቴ አስወግዳት ዘንድ ይህች ከተማ ከሠሩአት ቀን ጀምሮ እስከ ዛሬ ድረስ በቁጣዬና በመዓቴ ውስጥ ናትና፤'),
  ('5fa18e15-3037-5cde-ae1d-d6baaeb92b62', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 17, 32, 'ይህም እኔን ያስቈጡኝ ዘንድ፥ እነርሱና ነገሥታቶቻቸው፥ አለቆቻቸውም፥ ካህናቶቻቸውም፥ ነቢያቶቻቸውም፥ የይሁዳም ሰዎች፥ በኢየሩሳሌምም የሚኖሩ ስለ አደረጉት ስለ እስራኤል ልጆችና ስለ ይሁዳ ልጆች ክፋት ሁሉ ነው።'),
  ('c485f722-86f3-57ff-a21d-d2be816cfc97', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 18, 33, 'ፊታቸውንም ሳይሆን ጀርባቸውን ወደ እኔ መለሱ፤ እኔም በማለዳ ተነሥቼ ሳስተምራቸው ተግሣጽን ይቀበሉ ዘንድ አልሰሙም።'),
  ('4142468d-7820-5666-a177-de8760db82ad', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 19, 34, 'ያረክሱትም ዘንድ ስሜ በተጠራበት ቤት ውስጥ ርኵሰታቸውን አኖሩ።'),
  ('eb57482d-b3db-5e4e-ab0f-0282f3b0feda', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', 'b83532b1-ef5b-509a-a846-e9639e702bf2', 20, 35, 'ይሁዳን ወደ ኀጢአት እንዲያገቡት፥ ይህን ርኵሰት ያደርጉ ዘንድ፥ እኔ ያላዘዝሁትንና በልቤ ያላሰብሁትን ነገር፥ ወንዶችና ሴቶች ልጆቻቸውን ለሞሎክ በእሳት ያሳልፉ ዘንድ በሄኖም ልጅ ሸለቆ ውስጥ ያሉትን መሠዊያዎች ለበዓል ሠሩ።”'),
  ('0f8981c0-b34e-51cf-a3a2-400b448c6fee', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 1, 36, 'አሁን እንግዲህ የእስራኤል አምላክ እግዚአብሔር አንተ ስለ እርስዋ፥ “በሰይፍና በራብ በቸነፈርም ለባቢሎን ንጉሥ እጅ ትሰጣለች ስለምትላት ከተማ እንዲህ ይላል፦'),
  ('25e211ca-802c-5701-a2ee-08e2ccec1b97', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 2, 37, 'እነሆ በቍጣዬና በመዓቴ፥ በታላቅም መቅሠፍቴ እነርሱን ካሳደድሁባት ሀገር ሁሉ እሰበስባቸዋለሁ፤ ወደዚህም ስፍራ እመልሳቸዋለሁ፤ ተዘልለውም እንዲኖሩ አደርጋለሁ፤'),
  ('e31b1afd-b428-5869-aa6c-dc96468747a5', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 3, 38, 'እነርሱም ሕዝብ ይሆኑኛል፤ እኔም አምላክ እሆናቸዋለሁ።'),
  ('b446cef8-6333-5647-a318-98f286e9e71d', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 4, 39, 'ለእነርሱም፥ ከእነርሱም በኋላ ለልጆቻቸው መልካም ይሆንላቸው ዘንድ ለዘለዓለም እንዲፈሩኝ ሌላ መንገድና ሌላ ልብ እሰጣቸዋለሁ።'),
  ('cf154d1a-a577-5bd0-a7ad-fe8a2499a1bf', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 5, 40, 'ከእነርሱም እንዳልመለስ፥ ከእነርሱ ጋር የዘለዓለምን ቃል ኪዳን እገባለሁ፤ ከእኔም ዘንድ ፈቀቅ እንዳይሉ መፈራቴን በልባቸው ውስጥ አኖራለሁ።'),
  ('9b03be77-45e2-571b-a849-1966a93963ab', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 6, 41, 'ለእነርሱም መልካምን በማድረግ ይቅር እላቸዋለሁ፤ በእውነትም በፍጹም ልቤና በፍጹም ነፍሴ በዚህች ምድር እተክላቸዋለሁ።'),
  ('0a2b86a6-1f2d-54a9-acec-fbe9f4531942', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 7, 42, 'እግዚአብሔር እንዲህ ይላልና፦ ይህን እጅግ ክፉ ነገር ሁሉ በዚህ ሕዝብ ላይ እንዳመጣሁ፥ እንዲሁ የተናገርሁላቸውን በጎነት ሁሉ አመጣላቸዋለሁ።'),
  ('c326228b-c63a-558e-acfd-9e537947c9dc', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 8, 43, 'እናንተም፦ ያለ ሰውና ያለ እንስሳ ያለች ባድማ ናት፤ ለከለዳውያንም እጅ ተሰጥታለች በምትሉአት ምድር እርሻን እንደ ገና ይገዛሉ።'),
  ('bfa5b32d-dc92-5ad8-ad97-90cf32b308c9', '94cc9f2f-b47c-5f52-a448-2cd34119fab4', '575b7cc0-94de-5fc4-ac49-2218671d74ce', 9, 44, 'ምርኮኞቻቸውንም እመልሳለሁና በብንያም ሀገር በኢየሩሳሌምም ዙሪያ ባሉ ስፍራዎች፥ በይሁዳም ከተሞች በደጋውም ባሉ ከተሞች፥ በቆላውም ባሉ ከተሞች፥ በደቡብም ባሉ ከተሞች፥ ሰዎች እርሻውን በብር ይገዛሉ፤ በውሉም ወረቀት ፈርመው ያትማሉ፤ ምስክሮችንም ያቆማሉ፤” ይላል እግዚአብሔር።'),
  ('0902ee71-c24f-5021-a7d3-8dc5a06a88a3', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 1, 1, 'ኤርምያስ ገና በግዞት ቤት አደባባይ ታስሮ ሳለ የእግዚአብሔር ቃል ሁለተኛ ጊዜ እንዲህ ሲል መጣለት፦'),
  ('26db0ff9-edb4-5a36-a2bb-ae8fe7d747de', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 2, 2, '“ስሙ እግዚአብሔር የሆነ፥ ምድርን የፈጠራት፥ የሠራትና ያጸናት እግዚአብሔር እንዲህ ይላል፦'),
  ('aa4c065c-3531-5fb9-a694-e2c3271c92c4', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 3, 3, 'ወደ እኔ ጩኽ፥ እኔም እመልስልሃለሁ፤ አንተም የማታውቀውን ታላቅና ኀይለኛ ነገርን እነግርሃለሁ።'),
  ('ecb05d68-030a-56fe-ac01-9455bb4b8e23', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 4, 4, 'የእስራኤል አምላክ እግዚአብሔር ለምሽግና ለመከላከያ ስለ ፈረሱት ስለዚህች ከተማ ቤቶች፥ ስለ ይሁዳም ነገሥታት ቤቶች እንዲህ ይላልና፦'),
  ('208fd567-52e8-5b58-a3ae-097d2c8924dd', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 5, 5, 'የከለዳውያን ተዋጊዎች ለመዋጋት መጥተዋል፤ ነገር ግን በቍጣዬና በመዓቴ በገደልኋቸው ሰዎች ሬሳዎች እሞላታለሁ፥ ስለ ክፋታቸው ሁሉ ፊቴን ከዚህች ከተማ እመልሳለሁ።'),
  ('faa6fb85-1ee3-59b6-ac4d-4729005d6303', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 6, 6, 'እነሆ ፈውስንና መድኀኒትን እሰጣታለሁ፤ እፈውሳታለሁም፤ የሰላምንና የእውነትንም መንገድ እገልጥላቸዋለሁ።'),
  ('5f5c1815-9b5b-53ca-aee5-5e96f193d386', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 7, 7, 'የይሁዳን ምርኮኞች፥ የእስራኤልንም ምርኮኞች እመልሳለሁ፤ ቀድሞም እንደ ነበሩ አድርጌ እሠራቸዋለሁ።'),
  ('b67f4ed5-9ceb-55ae-a3d4-65d8db9c3271', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 8, 8, 'እኔንም ከበደሉበት ኀጢአት ሁሉ አነጻቸዋለሁ፤ እኔም የበደሉኝንና ያመፁብኝን ኀጢአታቸውን ሁሉ ይቅር እላለሁ።'),
  ('29c0b4a7-cea0-5354-a396-5d44c5babd91', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 9, 9, 'ይህችም ከተማ እኔ የምሠራላቸውን በጎነት ሁሉ በሚሰሙ፥ እኔም ስላመጣሁላቸው በጎነትና ሰላም ሁሉ በሚፈሩና በሚደነግጡ አሕዛብ ሁሉ ፊት ለደስታ፥ ለክብርና ለገናንነት ትሆናለች።”'),
  ('cc6e6c98-a938-5c6d-a33a-004ac2cd5a6b', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 10, 10, 'እግዚአብሔር እንዲህ ይላል፥ “እናንተ፦ ያለ ሰውና ያለ እንስሳ ያለች ባድማ ናት በምትሉአት በዚች ስፍራ፥ የሚቀመጥባቸው በሌለ፥ ያለ ሰውና ያለ እንስሳ ባድማ በሆኑ በይሁዳ ከተሞችና በኢየሩሳሌም አደባባይ፥'),
  ('c7b66f6d-65be-5569-aee5-c98d18b507cc', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 11, 11, 'የሐሤት ድምፅና የደስታ ድምፅ፥ የወንድ ሙሽራ ድምፅና የሴት ሙሽራ ድምፅ፦ እግዚአብሔር ቸር ነውና፥ ምሕረቱም ለዘለዓለም ነውና የሠራዊት ጌታ እግዚአብሔርን አመስግኑ የሚሉ ሰዎች ድምፅ፥ ወደ እግዚአብሔርም ቤት የምስጋናን መሥዋዕት የሚያመጡ ሰዎች ድምፅ እንደ ገና ይሰማል። የዚያችን ምድር ምርኮኞች ቀድሞ እንደ ነበረ አድርጌ እመልሳለሁና፥” ይላል እግዚአብሔር።'),
  ('a0ade711-20e2-5861-a79f-789f4107f4f1', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 12, 12, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “ባድማ ሆኖ፥ ያለ ሰውና ያለ እንስሳ ባለው በዚህ ስፍራ በከተሞችም ሁሉ መንጎቻቸውን የሚያሳርፉበት የእረኞች መኖሪያ ይሆናል።'),
  ('c916565e-df53-571a-abb6-3a0d799b000d', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 13, 13, 'በደጋው ላይ ባሉ ከተሞች፥ በቆላውም ባሉ ከተሞች፥ በደቡብም ባሉ ከተሞች፥ በብንያምም ሀገር፥ በኢየሩሳሌምም ዙሪያ ባሉ ስፍራዎች፥ በይሁዳም ከተሞች በጎቹ በተቈጣጣሪያቸው እጅ እንደ ገና ያልፋሉ፥ ይላል እግዚአብሔር።”'),
  ('73bd2897-47cd-5e59-aa3a-7fc069ffe776', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 14, 14, '“እነሆ ስለ እስራኤል ቤትና ስለ ይሁዳ ቤት የሰጠሁትን መልካም የተስፋ ቃል የምፈጽምበት ዘመን ይመጣል፥ ይላል እግዚአብሔር።'),
  ('0accedf4-6646-5601-a463-868887b91526', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 15, 15, 'በዚያም ዘመን በዚያም ጊዜ ለዳዊት የጽድቅን ቍጥቋጥ አበቅልለታለሁ፤ እርሱም ፍርድንና ጽድቅን በምድር ያደርጋል።'),
  ('ca1dfed4-d2b1-524a-af34-93335bc1f509', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 16, 16, 'በዚያም ዘመን ይሁዳ ይድናል፤ ኢየሩሳሌምም ተዘልላ ትቀመጣለች፤ የምትጠራበትም ስም፦ እግዚአብሔር ጽድቃችን ተብሎ ነው።'),
  ('897230fc-5b02-52da-a417-bc47095c37d2', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 17, 17, 'እግዚአብሔር እንዲህ ይላልና፦ በእስራኤል ቤት ዙፋን ላይ የሚቀመጥ ሰው ከዳዊት ዘንድ አይታጣም።'),
  ('fb4ce5ff-c89c-5717-ac81-34990fb05394', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 18, 18, 'የሚቃጠለውንም መሥዋዕት የሚያቀርብ፥ የእህሉንም ቍርባን የሚያቃጥል፥ ሁልጊዜም የሚሠዋ ሰው ከሌዋውያን ካህናት ዘንድ በእኔ ፊት አይታጣም።”'),
  ('c8b34a09-a713-5759-a854-c0a6940e6118', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 19, 19, 'የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('0919350b-8471-5bfb-a779-6a85a98a28aa', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 20, 20, '“እግዚአብሔር እንዲህ ይላል፦ ቀንና ሌሊት በወራታቸው እንዳይሆኑ የቀን ቃል ኪዳኔንና የሌሊት ቃል ኪዳኔን ማፍረስ ብትችሉ፥'),
  ('55933b7d-5539-5a2d-ac19-3c741ebc2566', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 21, 21, 'በዙፋኑ ላይ የሚነግሥ ልጅ እንዳይሆንለት ከባሪያዬ ከዳዊት ጋር፥ ከአገልጋዮችም ከሌዋውያን ካህናት ጋር ያለው ቃል ኪዳኔ ደግሞ ይፈርሳል።'),
  ('c4063527-6282-5796-a369-92fb7f05f34d', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 22, 22, 'የሰማይን ሠራዊት መቍጠር፥ የባሕርንም አሸዋ መስፈር እንደማይቻል፥ እንዲሁ የባሪያዬን የዳዊትን ዘርና የሚያገለግሉኝን ሌዋውያንን አበዛለሁ።”'),
  ('fe9adc16-299b-5010-af79-37267ddaf26f', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 23, 23, 'የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('b78f836f-9255-5593-afd8-6c3d64c5166b', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 24, 24, '“ይህ ሕዝብ፦ እግዚአብሔር የመረጣቸውን ሁለቱን ወገን ጥሎአቸዋል፥ እንዲሁ በፊታቸው ከእንግዲህ ወዲህ ሕዝብ እንዳይሆን ሕዝቤን አቃልለዋል ያለውን ነገር አትመለከትምን?'),
  ('99d96e48-4f18-5a31-a05f-5299a11fc022', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 25, 25, 'እግዚአብሔር እንዲህ ይላል፦ የቀንና የሌሊት ቃል ኪዳኔን የሰማይንና የምድርንም ሥርዐት ያላጸናሁ እንደ ሆነ፥'),
  ('496abe5e-4c10-51c6-aad5-43a5d8a76eee', '5a8309e5-1f42-5dd9-a0eb-1bad6f4267aa', '7598cd13-a1f8-551f-aa0c-438569e240bb', 26, 26, 'እኔም ደግሞ በአብርሃምና በይስሐቅ በያዕቆብም ዘር ላይ ገዢዎች ይሆኑ ዘንድ ከዘሩ እንዳላስነሣ፥ የያዕቆብንና የባሪያዬን የዳዊትን ዘር እጥላለሁ፤ ምርኮአቸውን እመልሳለሁና፥ እምራቸውማለሁና።”'),
  ('10bf9cd7-8ba1-5349-ad39-a0dc935dfa67', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 1, 1, 'የባቢሎን ንጉሥ ናቡከደነፆርና ሠራዊቱ ሁሉ፥ ከእጁም ግዛት በታች ያሉ የምድር መንግሥታት ሁሉ፥ አሕዛብም ሁሉ ኢየሩሳሌምንና የይሁዳን ከተሞች ሁሉ ይወጉ በነበረ ጊዜ፥ ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል ይህ ነው፦'),
  ('d13583d6-d1a0-5be2-a9bc-d6441e6e7246', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 2, 2, '“የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ሂድ፤ ለይሁዳም ንጉሥ ለሴዴቅያስ ተናገር፤ እንዲህም በለው፦ እግዚአብሔር እንዲህ ይላል፦ እነሆ ይች ከተማ በባቢሎን ንጉሥ እጅ ተላልፋ ትሰጣለች፤ ይይዛታል፤ በእሳትም ያቃጥላታል።'),
  ('515e36b2-9b13-520d-abf6-88e634ce00a6', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 3, 3, 'አንተም በርግጥ ትያዛለህ፤ በእጁም አልፈህ ትሰጣለህ እንጂ ከእጁ አታመልጥም፤ ዐይንህም የባቢሎንን ንጉሥ ዐይን ታያለች፤ እርሱም ከአንተ ጋር አፍ ለአፍ ይናገራል፤ ወደ ባቢሎንም ትገባለህ።'),
  ('8863062d-80f3-5dc6-ac18-47219a26a76f', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 4, 4, '“ነገር ግን የይሁዳ ንጉሥ ሴዴቅያስ ሆይ! የእግዚአብሔርን ቃል ስማ፤ እግዚአብሔር ስለ አንተ እንዲህ ይላል፦ በሰይፍ አትሞትም፤'),
  ('00c927a5-a039-534e-a58f-57f106921cba', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 5, 5, 'ነገር ግን በሰላም ትሞታለህ፥ ከአንተ በፊት እንደ ነበሩ እንደ ዱሮ ነገሥታት አባቶችህ እሳት ይቃጠልላቸው እንደ ነበር እንዲሁ ያቃጥሉልሃልና፦ ወየው! ጌታ ሆይ! እያሉ ያለቅሱልሃል፤ እኔ ቃልን ተናግሬአለሁና” ይላል እግዚአብሔር።'),
  ('8e5c943b-1144-544a-a73b-41f477f99411', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 6, 6, 'ነቢዩ ኤርምያስም ይህን ቃል ሁሉ ለይሁዳ ንጉሥ ለሴዴቅያስ በኢየሩሳሌም ነገረው።'),
  ('1c66f4d3-e784-5560-af81-6a3105d806ea', '8727e821-4952-5277-a306-d78899568029', '9b2b718e-0b45-5205-a3a5-2c9ba5c82af2', 7, 7, 'የባቢሎንም ንጉሥ ሠራዊት ኢየሩሳሌምንና የቀሩትን የይሁዳን ከተሞች ሁሉ፥ ለኪሶንና አዚቃንም ይወጋ ነበር። እነዚህ የተመሸጉ ከተሞች በይሁዳ ከተሞች መካከል ቀርተው ነበርና።'),
  ('96c674b6-41f5-586d-ac03-b22de52e1233', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 1, 8, 'ስለ አርነታቸው ዐዋጅ እንዲነግር ንጉሡ ሴዴቅያስ በኢየሩሳሌም ከነበሩ ሕዝብ ሁሉ ጋር ቃል ኪዳን ከአደረገ በኋላ፥ ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣው ቃል ይህ ነው።'),
  ('d217dc74-28cf-54de-ae7e-b5c7c204cdfe', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 2, 9, 'ሰው ሁሉ ዕብራዊ የሆነ ወንድ ባሪያውንና ዕብራዊት የሆነች ሴት ባሪያውን አርነት እንዲያወጣ፥ አይሁዳዊ ወንድሙንም ማንም እንዳይገዛ፤'),
  ('4f5ffadd-2f3f-5050-a9bc-d1dfa619ca7f', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 3, 10, 'ሰው ሁሉ ወንድ ባሪያውንና ሴት ባሪያውን አርነት እንዲያወጣ፥ ከእንግዲህ ወዲህም ማንም እንዳይገዛቸው ወደ ቃል ኪዳኑ የገቡ አለቆች ሁሉና ሕዝቡ ሁሉ ሰሙ፤ አርነትም አወጡአቸው።'),
  ('ffcc4da3-7ccf-58a1-a873-08276a7cf5b6', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 4, 11, 'ነገር ግን ከዚያ በኋላ ተመልሰው አርነት ያወጡአቸውን ወንዶችና ሴቶች ባሪያዎቻቸውን አስመለሱ፤ ወንዶችና ሴቶች ባሪያዎችም አድርገው ገዙአቸው።'),
  ('ae55c751-9b5b-528c-a399-bd615fa25c6b', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 5, 12, 'ስለዚህ የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('8704b4d1-7012-5900-a211-d5254c932173', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 6, 13, '“የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ አባቶቻችሁን ከባርነት ቤት ከግብፅ ሀገር በአወጣኋቸው ቀን ከእነርሱ ጋር እንዲህ ስል ቃል ኪዳን አደረግሁ፦'),
  ('804dee4b-0e77-52bd-aead-d7c70a123df3', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 7, 14, 'ስድስት ዓመት በተፈጸመ ጊዜ፥ የተሸጠላችሁን፥ ስድስትም ዓመት የተገዛላችሁን ዕብራዊ ወንድማችሁን እያንዳንዳችሁ አርነት ታወጡታላችሁ፤ አባቶቻችሁ ግን አልሰሙኝም፤ ጆሮአቸውንም አላዘነበሉም።'),
  ('2d186b25-92f0-514d-ae01-88f77c5b704a', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 8, 15, 'እናንተም ዛሬ ተመልሳችሁ ሰው ሁሉ ባልንጀራውን አርነት ለማውጣት ዓመተ ኅድገትን በማድረግ በዐይኔ ፊት ቅን የሆነውን ነገር አድርጋችሁ ነበር፤ ስሜም በሚጠራበት ቤት ውስጥ በፊቴ ቃል ኪዳን አድርጋችሁ ነበር።'),
  ('6f0bf1bc-8a19-53be-aceb-8beebf952e1d', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 9, 16, 'ነገር ግን ተመልሳችሁ ስሜን አስነቀፋችሁ፤ እያንዳንዳችሁም በፈቃዳቸው እንዲሄዱ አርነት ያወጣችኋቸውን ወንድና ሴት ባሪያዎቻችሁን፥ ወንዶችና ሴቶች ባሪያዎች እንዲሆኑላችሁ መለሳችኋቸው።”'),
  ('9dabce35-768e-5635-ab98-43bd22a58501', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 10, 17, 'ስለዚህ እግዚአብሔር እንዲህ ይላል፥ “ሰው ሁሉ ለወንድሙና ለባልንጀራው ዓመተ ኅድገትን ለማድረግ እኔን አልሰማችሁም፤ እነሆ እኔ ለሰይፍና ለቸነፈር፥ ለራብም ዓመተ ኅድገትን አውጅባችኋለሁ፥ ይላል እግዚአብሔር፤ በምድርም መንግሥታት ሁሉ መካከል እበትናችኋለሁ።'),
  ('49232956-2b72-511f-ac95-c6aeadcd7526', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 11, 18, 'ቃል ኪዳኔን የተላለፉትን ሰዎች፥ በፊቴ ያደረጉትን ቃል ኪዳን ያልፈጸሙትን፥ እንቦሳውንም ቈርጠው በቍራጩ መካከል ያለፉትን አሳልፌ እሰጣቸዋለሁ።'),
  ('a71bee92-00f6-5ad0-acaf-332ebf6bb406', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 12, 19, 'የይሁዳን አለቆችና የኢየሩሳሌምን አለቆች፥ ጃንደረቦችንና ካህናትንም፥ በእንቦሳም ቍራጭ መካከል ያለፉትን የሀገሩን ሕዝብ ሁሉ፥'),
  ('22ece515-2e30-5071-a09a-7d387865daae', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 13, 20, 'ለጠላቶቻቸው እጅ፥ ነፍሳቸውንም ለሚሹአት እጅ አሳልፌ እሰጣለሁ፤ ሬሳቸውም ለሰማይ ወፎችና ለምድር አራዊት መብል ይሆናል።'),
  ('c5bc4827-8991-5f5d-abb2-7d463ce78d7a', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 14, 21, 'የይሁዳንም ንጉሥ ሴዴቅያስንና መኳንንቱን ለጠላቶቻቸው እጅ፤ ነፍሳቸውንም ለሚሹአት እጅ ከእናንተም ለተመለሱት ለባቢሎን ንጉሥ ሠራዊት እጅ አሳልፌ እሰጣለሁ።'),
  ('a1532be1-d6b9-5264-a17e-8b3c833705de', '8727e821-4952-5277-a306-d78899568029', 'c627d899-9e26-5b81-a5fc-aab3729e799f', 15, 22, 'እነሆ እኔ አዝዛለሁ፥ ይላል እግዚአብሔር፤ ወደዚህችም ሀገር እመልሳቸዋለሁ፤ እርስዋንም ይወጋሉ፤ ይይዙአትማል፤ በእሳትም ያቃጥሉአታል፤ የይሁዳንም ከተሞች ሰው የሌለበት ባድማ አደርጋቸዋለሁ።”'),
  ('ab912b4a-797e-593a-a867-a3604d02566d', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 1, 1, 'በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም ዘመን ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል ይህ ነው፤ እንዲህ ሲል፦'),
  ('03f68dc0-9c64-5cfc-a7fa-8f19b1675f69', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 2, 2, '“ወደ ሬካባውያን ቤት ሄደህ ተናገራቸው፤ ወደ እግዚአብሔርም ቤት አምጥተህ ከክፍሎቹ ወደ አንዲቱ አግባቸው፤ የወይን ጠጅም አጠጣቸው።”'),
  ('63fc6f8e-be60-50f0-ad79-0d3d0d55b9a3', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 3, 3, 'የከባስንን ልጅ የኤርምያስን ልጅ ያእዛንያንና ወንድሞቹንም፥ ልጆቹንም ሁሉ የሬካባውያንን ቤተ ሰብእ ሁሉ ወሰድኋቸው፤'),
  ('4c6e6854-72c1-5bc0-ace2-022477435008', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 4, 4, 'ወደ እግዚአብሔርም ቤት በበረኛው በሰሎም ልጅ በማሴው ጓዳ በላይ ባለው በአለቆቹ ጓዳ አጠገብ ወደ አለው ወደ እግዚአብሔር ሰው ወደ ጎዶልያ ልጅ ወደ ሐናንያ ልጆች ጓዳ አገባኋቸው።'),
  ('739648e8-a9e0-5d8d-aaa4-ef131e543746', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 5, 5, 'በሬካባውያንም ልጆች ፊት የወይን ጠጅ የሞላባቸውን ማድጋዎችንና ጽዋዎችን አኑሬ፥ “የወይኑን ጠጅ ጠጡ” አልኋቸው።'),
  ('f3d43966-fb2d-5482-a312-a22dfc1019d5', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 6, 6, 'እነርሱ ግን እንዲህ አሉ፥ “የወይኑን ጠጅ አንጠጣም፤ አባታችን የሬካብ ልጅ ኢዮናዳብ እናንተና ልጆቻችሁ ለዘለዓለም የወይን ጠጅ አትጠጡ ብሎ አዝዞናልና።'),
  ('6fd41d3e-0110-5614-a473-4ed479f7f512', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 7, 7, 'በምትኖሩባት ምድር ላይ ብዙ ዘመን እንድትኖሩ፥ በዕድሜአችሁ ሙሉ በድንኳን ውስጥ ተቀመጡ እንጂ ቤትን አትሥሩ፤ ዘርንም አትዝሩ፤ ወይንም አትትከሉ፤ አንዳችም አይሁንላችሁ።'),
  ('1070df61-afcf-51ee-a0a7-881b2b3a7148', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 8, 8, 'እኛም የአባታችንን የሬካብ ልጅ የኢዮናዳብን ቃል ባዘዘን ነገር ሁሉ ታዝዘናል፤ እኛም ሚስቶቻችንም ወንዶችና ሴቶች ልጆቻችንም ዕድሜአችንን ሙሉ የወይን ጠጅ አልጠጣንም፤'),
  ('7e6904a2-ee20-536d-a3ff-cf1a7d1b032c', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 9, 9, 'የምንቀመጥበትንም ቤት አልሠራንም፤ የወይን ቦታና እርሻ፥ ዘርም የለንም።'),
  ('e721f87f-fada-56de-a766-1f50b058421f', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 10, 10, 'በድንኳን ውስጥ ተቀምጠናል፤ አባታችንም ኢዮናዳብ ያዘዘንን ሁሉ ሰምተናል፤ አድርገናልም።'),
  ('72cfdc74-ac22-5c56-aec0-f5066713da41', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 11, 11, 'ነገር ግን የባቢሎን ንጉሥ ናቡከደነፆር በዚች ምድር ላይ በዘመተ ጊዜ፦ ኑ ከከለዳውያን ሠራዊትና ከሶርያ ሠራዊት ፊት የተነሣ ወደ ኢየሩሳሌም እንሂድ፤ አልን፤ እንዲሁም በኢየሩሳሌም ተቀመጥን።”'),
  ('39c5c94e-64d5-5f34-ada8-92db5585e34a', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 12, 12, 'የእግዚአብሔርም ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('46612649-6fbf-54b8-aec2-79d93840f80d', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 13, 13, '“የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ሂድና ለይሁዳ ሰዎችና በኢየሩሳሌም ለሚቀመጡ ተናገር፤ እንዲህም በላቸው፦ ቃሌን ትሰሙ ዘንድ ተግሣጽን አትቀበሉምን? ይላል እግዚአብሔር።'),
  ('4c11bc63-474a-57e1-ac3a-838578ff0915', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 14, 14, 'የሬካብ ልጅ ኢዮናዳብ ልጆቹ የወይን ጠጅ እንዳይጠጡ ያዘዛቸው ቃል ተፈጸመ፤ ለአባታቸውም ትእዛዝ ታዝዘዋልና እስከ ዛሬ ድረስ ወይን አይጠጡም፤ እኔም በማለዳ ስለ እናንተ ተናገርሁ፤ ሆኖም አልሰማችሁኝም።'),
  ('702b99e1-eda9-5b33-a630-702f10ef3442', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 15, 15, 'ደግሞም፦ እያንዳንዳችሁ ከክፉ መንገዳችሁ ተመለሱ፤ ሥራችሁንም አሳምሩ፤ ታገለግሉአቸውም ዘንድ ሌሎችን አማልክት አትከተሉ፤ ለእናንተና ለአባቶቻችሁም በሰጠሁት ምድር ትቀመጣላችሁ እያልሁ ባሪያዎችን ነቢያትን ሁሉ ልኬባችሁ ነበር፤ እናንተ ግን ጆሮአችሁን አላዘነበላችሁም፤ እኔንም አልሰማችሁኝም።'),
  ('7bcc0c93-43a4-54d9-abad-1c89b92abc6b', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 16, 16, 'የሬካብ ልጅ የኢዮናዳብ ልጆች አባታቸው ያዘዛቸውን ትእዛዝ ፈጽመዋል፤ ይህ ሕዝብ ግን አልሰማኝም፤'),
  ('f9091c97-55e0-5ab2-a812-4da7045da048', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 17, 17, 'ስለዚህ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ በተናገርኋቸው ጊዜ አልሰሙምና፥ በጠራኋቸውም ጊዜ አልመለሱልኝምና የተናገርሁባቸውን ክፉ ነገር ሁሉ በይሁዳ ላይ በኢየሩሳሌምም በሚቀመጡ ሁሉ ላይ አመጣባቸዋለሁ።”'),
  ('727da6a1-3765-5054-affe-527149e749b9', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 18, 18, 'ኤርምያስም ሬካባውያንን እንዲህ አላቸው፥ “የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ የአባታችሁን የኢዮናዳብን ትእዛዝ ሰምታችኋልና፥ ትእዛዙንም ሁሉ ጠብቃችኋልና፥ ያዘዛችሁንም ሁሉ አድርጋችኋልና፥'),
  ('fd84c42b-de73-5f23-ad79-b3fb40cb63e1', '79ad3982-df43-5a38-a6a0-b17c2bb8efdd', 'deeb6722-5533-55cc-a444-e41d5935fbd4', 19, 19, 'ስለዚህ በፊቴ የሚቆም ሰው ከሬካብ ልጅ ከኢዮናዳብ ወገን ለዘለዓለም አይታጣም፥” ይላል የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር።'),
  ('039a74e1-4000-5e8f-a617-e098988b51c4', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 1, 1, 'እንዲህም ሆነ፤ በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም በአራተኛው ዓመተ መንግሥት ይህ ቃል ከእግዚአብሔር ዘንድ ወደ ኤርምያስ እንዲህ ሲል መጣ።'),
  ('c85659d9-dc6c-50a6-a9f6-ff6495b2f9c5', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 2, 2, '“አንድ የመጽሐፍ ክርታስ ውሰድ፥ ለአንተም ከተናገርሁበት ቀን ከይሁዳ ንጉሥ ከኢዮስያስ ዘመን ጀምሮ እስከ ዛሬ ድረስ በእስራኤልና በይሁዳ ላይ በአሕዛብም ሁሉ ላይ የተናገርሁህን ቃል ሁሉ ጻፍበት።'),
  ('51f67462-a257-5b86-a501-a631edf67448', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 3, 3, 'ምናልባት የይሁዳ ቤት ከክፉ መንገዳቸው ይመለሱ ዘንድ፥ እኔም በደላቸውንና ኀጢአታቸውን ይቅር እል ዘንድ፥ እኔ አደርግባቸዋለሁ ያልሁትንና ያሰብሁትን ክፉ ነገር ሁሉ ይሰሙ ይሆናል።”'),
  ('41cae470-9d56-5f1d-ac05-cfa3d71b8a36', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 4, 4, 'ኤርምያስም የኔርዩን ልጅ ባሮክን ጠራ፤ ባሮክም እግዚአብሔር ለእርሱ የተናገረውን ቃል ሁሉ ከኤርምያስ አፍ በመጽሐፉ ክርታስ ጻፈ።'),
  ('3df80122-f92b-5985-a513-b75d238bf832', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 5, 5, 'ኤርምያስም ባሮክን እንዲህ ሲል አዘዘው፥ “እኔ እስረኛ ነኝ፤ ወደ እግዚአብሔር ቤትም እገባ ዘንድ አልችልም።'),
  ('fd41c15e-3031-52b0-accb-e66e6c5b764b', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 6, 6, 'አንተ ግን ገብተህ ከአፌ የጻፍኸውን የእግዚአብሔርን ቃል በጾም ቀን በእግዚአብሔር ቤት በሕዝቡ ጆሮ በክርታሱ አንብብ፤ ደግሞም ከከተሞቻቸው በሚወጡ በይሁዳ ሰዎች ሁሉ ጆሮ አንብበው።'),
  ('af12b2b4-c0a2-53f5-a8f9-b93f551e8117', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 7, 7, 'እግዚአብሔር በዚህ ሕዝብ ላይ የተናገረው ቍጣውና መዓቱ ታላቅ ነውና ምናልባት ልመናቸው በእግዚአብሔር ፊት ትደርስ ይሆናል፤ ሁሉም ከክፉ መንገዳቸው ይመለሱ ይሆናል።”'),
  ('84652683-0218-5ee1-a850-ec6558fe6348', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 8, 8, 'የኔርዩም ልጅ ባሮክ ነቢዩ ኤርምያስ ያዘዘውን ሁሉ አደረገ፥ በእግዚአብሔርም ቤት የእግዚአብሔርን ቃል በመጽሐፉ አነበበ።'),
  ('17345fdb-e1d8-5f56-aea9-675f6e8a413f', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 9, 9, 'እንዲህም ሆነ፤ የይሁዳ ንጉሥ የኢዮስያስ ልጅ ኢዮአቄም በነገሠ በአምስተኛው ዓመት በዘጠነኛው ወር በኢየሩሳሌም የተቀመጡ ሕዝብ ሁሉ፥ ከይሁዳም ከተሞች ወደ ኢየሩሳሌም የመጡ ሕዝብ ሁሉ በእግዚአብሔር ፊት ለመጾም ዐዋጅ ነገሩ።'),
  ('4f254c77-c478-519f-a50e-eabf74229df6', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 10, 10, 'ባሮክም የኤርምያስን ቃል በእግዚአብሔር ቤት በላይኛው አደባባይ በእግዚአብሔር ቤት በአዲሱ በር መግቢያ ባለው በጸሓፊው በሳፋን ልጅ በገማርያ ክፍል በሕዝቡ ሁሉ ጆሮ በመጽሐፉ አንበበ።'),
  ('42e168ec-b5d9-5c0f-a31f-b15d4e7ddefb', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 11, 11, 'የሳፋንም ልጅ የገማርያ ልጅ ሚክያስ የእግዚአብሔርን ቃል ሁሉ ከመጽሐፉ ሰማ።'),
  ('fb9e57ed-de9f-5f7e-a0a9-242c1c7ccfde', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 12, 12, 'ወደ ንጉሡም ቤት ወደ ጸሓፊው ክፍል ወረደ፤ እነሆም አለቆቹ ሁሉ፥ ጸሓፊው ኤሊሳማ፥ የሸማያ ልጅ ድላያ፥ የዓክቦር ልጅ ኤልናታን፥ የሳፋን ልጅ ገማርያ፥ የሐናንያ ልጅ ሴዴቅያስ፥ አለቆቹም ሁሉ በዚያ ተቀምጠው ነበር።'),
  ('5ecf0183-430f-558e-acbc-a52f36a2cac6', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 13, 13, 'ሚክያስም ባሮክ በሕዝቡ ጆሮ በመጽሐፉ በአነበበ ጊዜ የሰማውን ቃል ሁሉ ነገራቸው።'),
  ('5d88f822-72e7-5c4f-a0f6-dae3970f0348', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 14, 14, 'አለቆቹም ሁሉ፥ “በሕዝቡ ጆሮ ያነበብኸውን ክርታስ በእጅህ ይዘህ ና” ብለው የኩሲ ልጅ የሰሌምያ ልጅ የናታንያ ልጅ ይሁዳን ወደ ኔርዩ ልጅ ወደ ባሮክ ላኩ። የኔርዩም ልጅ ባሮክ ክርታሱን በእጁ ይዞ ወደ እነርሱ ወረደ።'),
  ('5032a8e4-1718-5182-ada3-7953f0d7f6fd', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 15, 15, 'እነርሱም፥ “እስኪ ተቀመጥ፤ በጆሮአችንም አንብብ” አሉት። ባሮክም በጆሮአቸው አነበበው።'),
  ('309eefb0-6647-55ef-a08a-b311daee84b0', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 16, 16, 'እንዲህም ሆነ፦ ቃሉን ሁሉ በሰሙ ጊዜ ፈርተው እርስ በርሳቸው ተመካከሩ፤ ባሮክንም፥ “ይህን ቃል ሁሉ በርግጥ ለንጉሡ እንናገራለን” አሉት።'),
  ('2c9db448-5163-51c9-a370-972d29971e4a', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 17, 17, 'ባሮክንም፥ “ይህን ቃል ሁሉ እንዴት እንደ ጻፍኸው ንገረን” ብለው ጠየቁት።'),
  ('e18e5fa9-deea-52f7-a63f-88a0c8bbb783', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 18, 18, 'ባሮክም፥ “ኤርምያስ ይህን ቃል ከአፉ ይነግረኝ ነበር፤ እኔም በመጽሐፉ ላይ እጽፍ ነበር” ብሎ መለሰላቸው።'),
  ('463f4521-113a-5a3f-a27a-c6752837dbfa', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 19, 19, 'አለቆቹም ባሮክን፥ “አንተና ኤርምያስ ሂዱ፤ ተሸሸጉ፤ ወዴትም እንደ ሆናችሁ ማንም አይወቅ” አሉት።'),
  ('e7d16176-f2d0-5c9c-ae52-eac225ada9fa', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 20, 20, 'ወደ ንጉሡም ወደ አደባባይ ገቡ፥ ክርታሱንም በጸሓፊው በኤሊሳማ ክፍል አኑረውት ነበር፤ ቃሉንም ሁሉ ለንጉሡ ተናገሩ።'),
  ('e7941a1a-bd44-5d56-a32f-b3872da2afdc', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 21, 21, 'ንጉሡም ክርታሱን ያመጣ ዘንድ ይሁዳን ላከ፤ እርሱም ከጸሓፊው ከኤሊሳማ ክፍል ወሰደው፤ ይሁዳም በንጉሡና በንጉሡ አጠገብ በቆሙት አለቆች ሁሉ ጆሮ አነበበው።'),
  ('1248b76f-f71c-5993-ac75-43d1e28bdf47', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 22, 22, 'ንጉሡም በዘጠነኛው ወር በክረምት በሚቀመጥበት ቤት ተቀምጦ ነበር፤ በፊቱም እሳት ይነድድ ነበር።'),
  ('9d68df86-aee3-548c-af14-2dbf999f6b24', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 23, 23, 'ይሁዳም ሦስትና አራት ዐምድ ያህል በአነበበ ቍጥር፥ ንጉሡ በብርዕ መቍረጫ ቀደደው፤ ክርታሱንም በምድጃ ውስጥ በአለው እሳት ፈጽሞ እስኪቃጠል ድረስ በምድጃ ውስጥ ወደ አለው እሳት ጣለው።'),
  ('741749f4-87f2-5f0d-ac27-0b3f537c6aa6', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 24, 24, 'ንጉሡም፥ ይህንም ቃል ሁሉ የሰሙ አገልጋዮቹ ሁሉ አልደነገጡም፤ ልብሳቸውንም አልቀደዱም።'),
  ('5d388606-d8ce-5559-aeb7-738dcadf9869', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 25, 25, 'ነገር ግን ኤልናታንና ጎዶልያ፥ ገማርያም ክርታሱን እንዳያቃጥል ንጉሡን ለመኑት፤ እርሱ ግን አልሰማቸውም።'),
  ('144b6301-3e7e-5fee-ac48-3a676e738b90', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'dd7b21ff-2f18-561c-a42f-b7c4cdd44d1b', 26, 26, 'ንጉሡም ጸሓፊውን ባሮክንና ነቢዩን ኤርምያስን ይይዙ ዘንድ የንጉሡን ልጅ ይረሕምኤልንና የዓዝርኤልን ልጅ ሠራያን የዓብድኤልንም ልጅ ሰሌምያን አዘዘ፤ እግዚአብሔር ግን ሰወራቸው።'),
  ('efcdc405-d8ba-588d-a042-8e060478d203', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 1, 27, 'ንጉሡም፥ ባሮክ ከኤርምያስ አፍ የጻፈው ቃል ያለበትን ክርታስ ካቃጠለ በኋላ የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('bd53c8dd-22f8-5f68-ac5d-2c2802680bb7', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 2, 28, '“ዳግመኛም ሌላ ክርታስ ውሰድ፤ የይሁዳም ንጉሥ ኢዮአቄም በአቃጠለው ክርታስ ላይ የነበረውን የቀድሞውን ቃል ሁሉ ጻፍበት።'),
  ('8382bb84-bcbe-55cd-af03-79d459fdf371', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 3, 29, 'የይሁዳንም ንጉሥ ኢዮአቄምን እንዲህ በለው፦ እግዚአብሔር እንዲህ ይላል፦ አንተ፦ የባቢሎን ንጉሥ በርግጥ ይመጣል፤ ይችንም ሀገር ያፈርሳታል፤ ሰውና እንስሳም ያልቃሉ ብለህ ለምን ጻፍህበት? ብለህ ይህን ክርታስ አቃጥለሃል።'),
  ('af34a157-6987-5809-a95d-83930dfb4a56', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 4, 30, 'ስለዚህም ስለ ይሁዳ ንጉሥ ስለ ኢዮአቄም እግዚአብሔር እንዲህ ይላል፦ በዳዊት ዙፋን ላይ የሚቀመጥ ልጅ አይኖርለትም፥ ሬሳውም በቀን ለትኩሳት፥ በሌሊትም ለውርጭ ይጣላል።'),
  ('9cffef04-40bc-5fd1-af38-6bf48999d710', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 5, 31, 'ስለ ኀጢአታቸውም እርሱንና ዘሩን አገልጋዮቹንም በመዓት እጐበኛለሁ፤ እነርሱም አልሰሙምና የተናገርሁባቸውን ክፉ ነገር ሁሉ በእነርሱ ላይና በኢየሩሳሌም በሚቀመጡ በይሁዳም ሰዎች ላይ አመጣለሁ።”'),
  ('bd06a59f-5457-57a1-ab9c-b6c73218539d', 'b12a3f10-5003-5ff8-abfd-3217af90de49', 'a6dca710-7c5b-5c84-a0b5-4a7e5f2e8eae', 6, 32, 'ኤርምያስም ሌላ ክርታስ ወሰደ፤ ለኔርዩም ልጅ ለጸሓፊው ለባሮክ ሰጠው፤ እርሱም የይሁዳ ንጉሥ ኢዮአቄም በእሳት ያቃጠለውን የመጽሐፉን ቃል ሁሉ ከኤርምያስ አፍ ጻፈበት፤ ደግሞም እንደ ቀድሞው ያለ ቃል ብዙ ቃል ተጨመረበት።'),
  ('0be11241-5cf6-552e-a392-c55e512d8de8', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 1, 1, 'የባቢሎን ንጉሥ ናቡከደነፆር በይሁዳ ያነገሠው የኢዮስያስ ልጅ ሴዴቅያስ በኢዮአቄም ልጅ በኢኮንያን ፋንታ ነገሠ።'),
  ('3a25f538-37a2-5a5f-a6fc-bfd6297b580b', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 2, 2, 'እርሱም ሆነ፥ አገልጋዮቹ፥ የሀገሩም ሕዝብ በነቢዩ በኤርምያስ እጅ የተናገረውን የእግዚአብሔርን ቃል አልሰሙም።'),
  ('236dc836-df9e-5952-a560-68496b9e2ce9', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 3, 3, 'ንጉሡም ሴዴቅያስ፥ “ወደ አምላካችን ወደ እግዚአብሔር ስለ እኛ ጸልይ” ብሎ የሰሌምያን ልጅ ዮካልንና ካህኑን የማሴውን ልጅ ሶፎንያስን ወደ ነቢዩ ወደ ኤርምያስ ላከ።'),
  ('b208ba8b-387c-555e-ac27-dd08829ba2cd', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 4, 4, 'እርሱንም በግዞት ቤት ገና አላገቡትም ነበርና ኤርምያስ በሕዝቡ መካከል ይወጣና ይገባ ነበር።'),
  ('2be3bcd3-8297-57a7-ae69-afb604a5d0c6', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 5, 5, 'የፈርዖንም ሠራዊት ከግብፅ ወጣ፤ ኢየሩሳሌምንም ከብበዋት የነበሩ ከለዳውያን ይህን ወሬአቸውን በሰሙ ጊዜ ከኢየሩሳሌም ተመለሱ።'),
  ('939dde7c-7e5f-556b-a074-5b48bef36d14', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 6, 6, 'የእግዚአብሔርም ቃል ወደ ነቢዩ ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('fe8ee9c4-fd55-5c9f-ae6a-20d1c827b5c9', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 7, 7, 'የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፥ “ከእኔ ትጠይቁ ዘንድ የላካችሁን የይሁዳን ንጉሥ እንዲህ በሉት፦ እነሆ ሊረዳችሁ የወጣው የፈርዖን ሠራዊት ወደ ሀገሩ ወደ ግብፅ ይመለሳል።'),
  ('e165e456-dd95-5c97-aed2-4188543315f6', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 8, 8, 'ከለዳውያንም ተመልሰው ይህችን ከተማ ይዋጉአታል፤ ይይዙአትማል፤ በእሳትም ያቃጥሉአታል።'),
  ('cd49643b-d376-5c74-ac5f-3c3d209fdf80', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 9, 9, 'እግዚአብሔር እንዲህ ይላል፦ አይሄዱምና፦ ከለዳውያን በርግጥ ከእኛ ዘንድ ይሄዳሉ ብላችሁ ራሳችሁን አታታልሉ።'),
  ('871bbc75-88ea-540d-a74d-4974d2b0817c', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 10, 10, 'ነገር ግን እናንተን የሚወጉትን የከለዳውያንን ጭፍራ ሁሉ ብትመቱ፤ ከእነርሱም ጥቂት ተወግተው ያልሞቱ ቢቀሩ ሁሉ እያንዳንዱ በስፍራው ይነሣሉ፤ ይህቺንም ሀገር በእሳት ያቃጥላሉ።”'),
  ('5b5dfa50-b727-5b03-acdc-168eb735fcb8', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 11, 11, 'የከለዳውያንም ሠራዊት ከፈርዖን ሠራዊት ፊት የተነሣ ከኢየሩሳሌም በተመለሰ ጊዜ እንዲህ ሆነ፤'),
  ('ba770187-b79f-5b00-a0ab-39c47bd77653', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 12, 12, 'ኤርምያስ በሕዝቡ መካከል ይኖር ዘንድ ወደ ብንያም ሀገር ሊሄድ ከኢየሩሳሌም ወጣ።'),
  ('e7ec8905-2450-5627-a3cf-abaa65f8262a', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 13, 13, 'በብንያምም በር በነበረ ጊዜ የሐናንያ ልጅ የሰሌምያ ልጅ ሳሩያ የተባለ በር ጠባቂ በዚያ ነበረ፤ እርሱም፥ “ወደ ከለዳውያን መኰብለልህ ነው” ብሎ ነቢዩን ኤርምያስን ያዘው።'),
  ('9d0621b6-10d4-524d-a344-24247db6d938', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 14, 14, 'ኤርምያስም፥ “ሐሰት ነው፤ ወደ ከለዳውያን መኰብለሌ አይደለም” አለ፤ እርሱ ግን አልሰማውም፤ ሳሩያም ኤርምያስን ይዞ ወደ አለቆች አመጣው።'),
  ('a20fa3cb-1da9-5e3d-a2ba-3bd33751d7fd', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 15, 15, 'አለቆችም በኤርምያስ ላይ ተቈጥተው መቱት፤ የግዞት ቤት አድርገውት ነበርና ወደ ጸሓፊው ወደ ዮናታን ቤት ላኩት።'),
  ('41f51f2c-33f4-51a5-a442-c5d98ee8bb41', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 16, 16, 'ኤርምያስም ወደ ጕድጓድ ቤት ወደ ጓዳዎቹ ገባ፤ ኤርምያስም በዚያ ብዙ ቀን ተቀመጠ።'),
  ('4889a6b5-d7e8-5048-a500-57f5985d8704', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 17, 17, 'ንጉሡም ሴዴቅያስ ልኮ አስመጣው፥ ንጉሡም በቤቱ፥ “በውኑ ከእግዚአብሔር ዘንድ የሆነ ቃል አለን?” ብሎ በቈይታ ጠየቀው። ኤርምያስም፥ “አዎን አለ፤ ደግሞም በባቢሎን ንጉሥ እጅ አልፈህ ትሰጣለህ” አለው።'),
  ('c8253209-cc33-50da-a580-8d92042cd8bc', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 18, 18, 'ኤርምያስም ደግሞ ንጉሡን ሴዴቅያስን እንዲህ አለው፥ “በግዞት ቤት የጣላችሁኝ አንተን፥ ወይስ አገልጋዮችህን፥ ወይስ ሕዝብህን ምን በድያችሁ ነው?'),
  ('f34c9bfd-7b09-5446-af88-ba2556c1dc67', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 19, 19, 'የባቢሎን ንጉሥ በእናንተና በዚህች ሀገር አይመጣባችሁም ብለው ትንቢት ይናገሩላችሁ የነበሩ ነቢያቶቻችሁ ወዴት አሉ?'),
  ('4d738ff3-0552-5d6d-a5cc-56c069098302', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 20, 20, 'አሁንም አቤቱ ንጉሥ ሆይ! ልመናዬ ወደ አንተ ይድረስ፤ በዚያ እንዳልሞት ወደ ጸሓፊው ወደ ዮናታን ቤት አትመልሰኝ።”'),
  ('1a9304bd-5e00-5438-abde-0b794befe60f', '09dfd89e-8554-5d14-a1f3-296a1f265bfe', '53563813-57f2-50ed-ab3d-f8b7e9690f39', 21, 21, 'ንጉሡም ሴዴቅያስ አዘዘ፤ ኤርምያስንም በግዞት ቤቱ ቅጥር ግቢ አኖሩት፤ እንጀራም ሁሉ ከከተማ እስኪጠፋ ድረስ ዕለት ዕለት አንድ አንድ እንጀራ ከውጪ ጋጋሪዎች እያመጡ ይሰጡት ነበር። እንዲሁም ኤርምያስ በግዞት ቤት ቅጥር ግቢ ተቀምጦ ነበር።'),
  ('2d1b0a7e-613a-52ca-a1a3-2533d96715b4', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 1, 1, 'ኤርምያስ ለሕዝቡ ሁሉ እንዲህ ሲል የተናገረውን ቃል የናታን ልጅ ሰፋንያስ፥ የጳስኮርም ልጅ ጎዶልያስ፥ የሰሌምያም ልጅ ዮካል፥ የመልክያም ልጅ ጳስኮር ሰሙ።'),
  ('93b3abd1-c309-5fcc-a8cc-746aaa4a8292', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “በዚች ከተማ የሚቀመጥ በሰይፍና በራብ፥ በቸነፈርም ይሞታል፤ ወደ ከለዳውያን የሚወጣ ግን በሕይወት ይኖራል፤ ነፍሱም እንደ ምርኮ ትሆንለታለች፤ በሕይወትም ይኖራል።'),
  ('6d45f86a-e039-52c1-a2d7-994943de424a', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 3, 3, 'እግዚአብሔር እንዲህ ይላልና፦ ይች ከተማ በባቢሎን ንጉሥ ሠራዊት እጅ በርግጥ ትሰጣለች፤ እርሱም ይይዛታል።”'),
  ('f780dddd-ef39-5048-afbf-79159777db73', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 4, 4, 'አለቆቹም ንጉሡን፥ “ይህን የመሰለውን ቃል ሲነግራቸው በዚያች ከተማ የቀሩትን የሰልፈኞቹን እጅ፥ የሕዝቡንም ሁሉ እጅ ያደክማልና ይህ ሰው ይገደል፤ ለዚህ ሕዝብ ክፋትን እንጂ ሰላምን አይመኝለትምና” አሉት።'),
  ('7aebc723-d309-5f5b-a6b1-d0e4fe7adcc3', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 5, 5, 'ንጉሡም ሴዴቅያስ፥ “ንጉሡ በእናንተ ላይ ምንም ሊያደርግ አይችልምና እነሆ በእጃችሁ ነው” አለ።'),
  ('23a91d9c-7abc-5cee-a5b6-3b806b20e478', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 6, 6, 'ኤርምያስንም ወሰዱት፤ በግዞት ቤትም አደባባይ ወደ ነበረው ወደ ንጉሡ ልጅ ወደ መልክያ ጕድጓድ ውስጥ ጣሉት፤ ኤርምያስንም በገመድ አወረዱት። በጕድጓዱም ውስጥ ጭቃ እንጂ ውኃ አልነበረበትም፤ ኤርምያስም ወደ ጭቃው ውስጥ ገባ።'),
  ('d5f4b668-f70f-5270-aa80-d818a1479e29', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 7, 7, 'በንጉሡም ቤት የነበረው ጃንደረባ ኢትዮጵያዊው አቤሜሌክ ኤርምያስን በጕድጓድ ውስጥ እንደ ጣሉት ሰማ።'),
  ('b7c437d5-de98-5398-a1f3-ca6d5ad04e6e', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 8, 8, 'ንጉሡም በብንያም በር ተቀምጦ ነበር። አቤሜሌክም ከንጉሡ ቤት ወጥቶ ለንጉሡ እንዲህ ብሎ ነገረው፥'),
  ('c0be60ca-a414-58d8-a130-e9dec420123f', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 9, 9, '“ጌታዬ ንጉሥ ሆይ! እነዚህ ሰዎች ነቢዩን ኤርምያስን በጕድጓድ ውስጥ በመጣላቸው በእርሱ ላይ በአደረጉት ሁሉ ክፉ አድርገዋል፤ በከተማዪቱም ውስጥ እንጀራ ስለሌለ በዚያ በራብ ይሞታል።”'),
  ('385cb468-a187-55bc-a5c9-e56d2124a295', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 10, 10, 'ንጉሡም ኢትዮጵያዊዉን አቤሜሌክን፥ “ከአንተ ጋር ሠላሳ ሰዎች ከዚህ ውሰድ፤ ነቢዩ ኤርምያስም ሳይሞት ከጕድጓድ አውጣው” ብሎ አዘዘው።'),
  ('6c1941c7-a4ae-519e-af57-bcfd5b69beae', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 11, 11, 'አቤሜሌክም ከእርሱ ጋር ሰዎችን ይዞ ሄደ፤ ከቤተ መዛግብቱም በታች ወደ ነበረው ወደ ንጉሥ ቤት ገባ፤ ከዚያም ዕላቂ ጨርቅና አሮጌ ገመድ ወሰደ፥ ወደ ኤርምያስም ወደ ጕድጓዱ ውስጥ በገመድ አወረደው።'),
  ('8a181d01-710f-51ac-a04a-493c11bc374b', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 12, 12, 'ኢትዮጵያዊውም አቤሜሌክ ኤርምያስን፥ “እነዚህን ጨርቆች በብብትህ ከገመዱ በታች አድርግ” አለው፤ ኤርምያስም እንዲሁ አደረገ።'),
  ('c24485ff-a574-5177-aa04-f4bd55af1aa9', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 13, 13, 'ኤርምያስንም በገመዱ ጐተቱት፤ ከጕድጓድም አወጡት፤ ኤርምያስም በግዞት ቤት አደባባይ ተቀመጠ።'),
  ('2d2f615f-d32b-59ba-a665-1627a8f6ca06', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 14, 14, 'ንጉሡም ሴዴቅያስ ልኮ በእግዚአብሔር ቤት ወደ ነበረው ወደ ሦስተኛው መግቢያ ወደ እርሱ ነቢዩን ኤርምያስን አስመጣው፤ ንጉሡም ኤርምያስን፥ “አንዲት ነገር እጠይቅሃለሁ፤ ምንም አትሸሽገኝ” አለው።'),
  ('4d1fab70-cc08-5d69-a5d6-3b466e9d674e', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 15, 15, 'ኤርምያስም ንጉሡን ሴዴቅያስን፥ “ብነግርህ በውኑ አትገድለኝምን? ብመክርህም አትሰማኝም” አለው።'),
  ('2dccea7a-931f-529c-ae93-0a58c226e186', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 16, 16, 'ንጉሡም ሴዴቅያስ፥ “ይህችን ነፍስ የፈጠረልን ሕያው እግዚአብሔርን! አልገድልህም፤ ነፍስህንም ለሚሹ ለእነዚህ ሰዎች እጅ አሳልፌ አልሰጥህም” ብሎ በቈይታ ለኤርምያስ ማለ።'),
  ('2aa590af-f1ff-5ef5-a276-24dacbb4401d', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 17, 17, 'ኤርምያስም ሴዴቅያስን፥ “የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ወደ ባቢሎን ንጉሥ አለቆች ብትወጣ፥ ነፍስህ በሕይወት ትኖራለች፤ ይህችም ከተማ በእሳት አትቃጠልም፤ አንተም፥ ቤትህም በሕይወት ትኖራላችሁ።'),
  ('69a690cc-d1bb-5f81-ab0c-651dc2e73cab', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 18, 18, 'ወደ ባቢሎን ንጉሥ አለቆች ባትወጣ ግን፥ ይች ከተማ በከለዳውያን እጅ ትሰጣለች፤ በእሳትም ያቃጥሉአታል፤ አንተም ከእጃቸው አታመልጥም” አለው።'),
  ('fedc70bc-348f-5dc1-aae9-5167af032be1', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 19, 19, 'ንጉሡም ሴዴቅያስ ኤርምያስን፥ “ወደ ከለዳውያን በኰበለሉ በአይሁድ እጅ አሳልፈው ይሰጡኛል፤ እነርሱም ያፌዙብኛል ብዬ እፈራለሁ” አለው።'),
  ('c47c87c4-bc09-5d59-a7e5-1e156e0bf122', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 20, 20, 'ኤርምያስም እንዲህ አለው፥ “አሳልፈው አይሰጡህም። እኔ የምነግርህን የእግዚአብሔርን ቃል ስማ፤ ለአንተም ይሻልሃል፤ ነፍስህም በሕይወት ትኖራለች።'),
  ('1ab75f77-1b0c-510a-a2cc-817dc45bb184', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 21, 21, 'ትወጣ ዘንድ እንቢ ብትል ግን፥ እግዚአብሔር ያሳየኝ ቃል ይህ ነው።'),
  ('3dcfeea5-0a48-5534-ae91-161954d75321', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 22, 22, 'እነሆ በይሁዳ ቤት የቀሩትን ሴቶች ሁሉ ወደ ባቢሎን ንጉሥ አለቆች ያወጣሉ፤ እነዚያም ሴቶች፦ ባለሟሎችህ አታልለውሃል፤ አሸንፈውህማል፤ እግሮችህ ግን አሁን በጭቃ ውስጥ ከገቡ እነርሱ ከአንተ ወደ ኋላ ተመልሰዋል ይላሉ።'),
  ('ca770910-ff8c-51f6-a2e0-abea16133160', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 23, 23, 'ሚስቶችህንና ልጆችህንም ሁሉ ወደ ከለዳውያን ያወጣሉ፤ አንተም በባቢሎን ንጉሥ እጅ ትያዛለህ እንጂ ከእጃቸው አታመልጥም፤ ይህችም ከተማ በእሳት ትቃጠላለች።”'),
  ('04faa885-d12e-55ba-a3bd-d8764dc51ad2', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 24, 24, 'ሴዴቅያስም ኤርምያስን እንዲህ አለው፥ “ይህን ቃል ማንም አይወቅ፥ አንተም አትሞትም።'),
  ('4a840544-9af3-5873-a1ec-d008235635df', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 25, 25, 'አለቆቹ ግን እኔ ከአንተ ጋር እንደ ተነጋገርሁ ቢሰሙ፥ ወደ አንተም መጥተው፦ ለንጉሡ ያልኸውን ንገረን፤ አትሸሽገንም፤ እኛም አንገድልህም፤ ደግሞ ንጉሡ ያለህን ንገረን ቢሉህ፥'),
  ('cd762b26-3f0b-5f1b-afab-76109dfef900', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 26, 26, 'አንተ በዚያ እሞት ዘንድ ወደ ዮናታን ቤት አትመልሰኝ ብዬ በንጉሡ ፊት ለመንሁ” በላቸው።'),
  ('9408fd68-0ea4-541b-ad82-a38cade87d0c', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 27, 27, 'አለቆቹም ሁሉ ወደ ኤርምያስ መጥተው ጠየቁት፤ ንጉሡም እንዳዘዘው እንደዚህ ቃል ሁሉ ነገራቸው። ነገሩም አልተሰማምና ከእርሱ ጋር መነጋገርን ተዉ።'),
  ('989cd296-4c5a-5c02-a67e-15ecf4552312', 'bb135a3f-e5ee-5f41-afb9-dedfb20925cd', '96c668e4-40d2-5683-a067-dbfb42c80350', 28, 28, 'ኤርምያስም ኢየሩሳሌም እስከ ተያዘችበት ቀን ድረስ በግዞት ቤቱ አደባባይ ተቀመጠ።'),
  ('46a85a3f-9fcc-5e7d-a8c2-45e96ee04578', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 1, 1, 'እንዲህም ሆነ፤ በይሁዳ ንጉሥ በሴዴቅያስ በዘጠነኛው ዓመተ መንግሥት በዐሥረኛው ወር የባቢሎን ንጉሥ ናቡከደነፆርና ሠራዊቱ ሁሉ ወደ ኢየሩሳሌም መጥተው ከበቡአት።'),
  ('447026f8-200a-5f7c-a9ca-5f6aa37c8b69', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 2, 2, 'በሴዴቅያስም በዐሥራ አንደኛው ዓመተ መንግሥት በአራተኛው ወር፥ ከወሩም በዘጠነኛው ቀን ከተማዪቱ ተለያየች።'),
  ('a199a624-d65a-56d8-a244-7c3de9cd5646', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 3, 3, 'የባቢሎንም ንጉሥ አለቆች ሁሉ፥ ማርጋናሳር፥ ሳማጎት፥ ናቡሳኮር፥ ናቡሰሪስ፥ ናግራጎስናሴር፥ ረብማግ፥ ኔርጋል ሴሪአጼር፥ ከቀሩት ከባቢሎን ንጉሥ አለቆች ሁሉ ጋር ገብተው በመካከለኛው በር ውስጥ ተቀመጡ።'),
  ('fa159090-920a-5de8-add0-29e3ed572482', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 4, 4, 'የይሁዳ ንጉሥ ሴዴቅያስና ሰልፈኞቹም ሁሉ በአዩአቸው ጊዜ፥ በሌሊት ሸሹ፤ በንጉሡም አትክልት መንገድ በሁለቱ ቅጥር መካከል በነበረው ደጅ ከከተማዪቱ ወጡ፤ በዓረባም መንገድ ወጡ።'),
  ('9df002f8-717c-5578-a4ac-5015c0ea2e20', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 5, 5, 'የከለዳውያንም ሠራዊት ተከታተላቸው፤ ሴዴቅያስንም በኢያሪኮ ሜዳ አገኙት፤ ይዘውም በሐማት ምድር ወዳለችው ወደ ዴብላታ ወደ ባቢሎን ንጉሥ ወደ ናቡከደነፆር አመጡት፤ እርሱም ፍርድን በእርሱ ላይ ተናገረ።'),
  ('a528888a-8b12-5e48-a72d-ead5fd821c6d', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 6, 6, 'የባቢሎንም ንጉሥ የሴዴቅያስን ልጆች በዐይኑ ፊት በዴብላታ ገደላቸው፤ የባቢሎንም ንጉሥ የይሁዳን ታላላቆች ሁሉ ገደለ።'),
  ('4e09ad8d-9813-5a46-a0a1-3e84577596fc', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 7, 7, 'የሴዴቅያስንም ዐይን አወጣ፤ በሰንሰለትም አስሮ ወደ ባቢሎን ወሰደው።'),
  ('72adb615-714c-5855-a5df-3e6e36a54678', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 8, 8, 'ከለዳውያንም የንጉሡንና የሕዝቡን ቤቶች በእሳት አቃጠሉ፤ የኢየሩሳሌምንም ቅጥር አፈረሱ።'),
  ('2692dcce-6531-596f-a67f-dbb0fd2f7e1c', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 9, 9, 'የአዛዦች አለቃ ናቡዛርዳንም በከተማዪቱ የቀሩትን ሕዝብ፥ ኰብልለውም ወደ እርሱ የገቡትን ሰዎችና የቀረውንም የሕዝቡን ቅሬታ ወደ ባቢሎን ማረካቸው።'),
  ('30d0dea5-ae20-58ff-afff-eefa24165309', 'eec438c8-492a-5b96-a9cd-1146268900a6', '1bf89c61-4ef2-51a5-aa30-03ce610970f1', 10, 10, 'የአዛዦች አለቃ ናቡዛርዳን ግን አንዳች ከሌላቸው ከሕዝቡ ድሆች ከፊሎቹን በይሁዳ ሀገር ተዋቸው፤ የወይኑን ቦታና እርሻውንም በዚያ ጊዜ ሰጣቸው።'),
  ('425fcbb5-d16f-5868-a017-a1efe88598ad', 'eec438c8-492a-5b96-a9cd-1146268900a6', '3bfcf0f5-658c-53a1-a0f0-e7d3a094ed59', 1, 11, 'የባቢሎንም ንጉሥ ናቡከደነፆር የአዛዦች አለቃ ናቡዛርዳንን ስለ ኤርምያስ እንዲህ ሲል አዘዘው፦'),
  ('8cff4975-63f3-53ea-a991-d638ddec1fa0', 'eec438c8-492a-5b96-a9cd-1146268900a6', '3bfcf0f5-658c-53a1-a0f0-e7d3a094ed59', 2, 12, '“ውሰደውና በመልካም ተመልከተው፤ የሚልህንም ነገር አድርግለት እንጂ ክፉን ነገር አታድርግበት።”'),
  ('ff91900d-57fe-5886-af4f-cc67a8bae357', 'eec438c8-492a-5b96-a9cd-1146268900a6', '3bfcf0f5-658c-53a1-a0f0-e7d3a094ed59', 3, 13, 'የአዛዞች አለቃ ናቡዛርዳንም ላከ፤ ናቡሻዝባንም፥ ራፋስቂስም፥ ኔርጋል ሴራአጼርም፥ ራብማግም፥ የባቢሎንም ንጉሥ አለቆች ሁሉ ላኩ።'),
  ('e589e49e-1a30-58f7-a87b-86fd6f41954d', 'eec438c8-492a-5b96-a9cd-1146268900a6', '3bfcf0f5-658c-53a1-a0f0-e7d3a094ed59', 4, 14, 'ኤርምያስንም ከግዞት ቤቱ አደባባይ አወጡት፤ ወደ ቤቱም ይወስደው ዘንድ ለሳፋን ልጅ ለአኪቃም ልጅ ለጎዶልያስ ሰጡት፤ እንዲህም በሕዝብ መካከል ተቀመጠ።'),
  ('e62ab8d5-dd72-55be-a4d7-3c823e9c1fc0', 'eec438c8-492a-5b96-a9cd-1146268900a6', '54e4f6cd-452b-57d4-ad9a-baa03de8f068', 1, 15, 'በግዞት ቤቱ አደባባይም ታስሮ ሳለ የእግዚአብሔር ቃል እንዲህ ሲል ወደ ኤርምያስ መጣ፦'),
  ('a7e349fa-c512-5e05-aa8a-fe634f90c327', 'eec438c8-492a-5b96-a9cd-1146268900a6', '54e4f6cd-452b-57d4-ad9a-baa03de8f068', 2, 16, '“ሂድ ለኢትዮጵያዊው ለአቤሜሌክ እንዲህ በለው፦ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ ለበጎነት ሳይሆን ለክፋት ቃሌን በዚች ከተማ ላይ አመጣለሁ፤ በዚያም ቀን በፊትህ ይፈጸማል።'),
  ('818704cf-b226-56c1-aed6-20636e71b26c', 'eec438c8-492a-5b96-a9cd-1146268900a6', '54e4f6cd-452b-57d4-ad9a-baa03de8f068', 3, 17, 'በዚያም ቀን አድንሃለሁ፥ ይላል እግዚአብሔር፤ ከፊታቸውም የተነሣ በምትፈራቸው ሰዎች እጅ አልሰጥህም።'),
  ('841ee0ec-6602-5b79-a849-7a4883a9597f', 'eec438c8-492a-5b96-a9cd-1146268900a6', '54e4f6cd-452b-57d4-ad9a-baa03de8f068', 4, 18, 'ፈጽሜ አድንሃለሁ፤ ሰውነትህም እንደ ምርኮ ትሆንልሃለች እንጂ በሰይፍ አትወድቅም፤ በእኔ ታምነሃልና፥” ይላል እግዚአብሔር።'),
  ('859a7265-24f9-50bd-a026-0a256888f05a', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 1, 1, 'ወደ ባቢሎን በተማረኩት በኢየሩሳሌምና በይሁዳ ምርኮኞች መካከል የአዛዦች አለቃ ናቡዛርዳን በሰንሰለት አስሮ በወሰደው ጊዜ ከራማ ከለቀቀው በኋላ ከእግዚአብሔር ዘንድ ወደ ኤርምያስ የመጣ ቃል ይህ ነው።'),
  ('e0488231-d03f-5cba-a1ad-6931329554ff', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 2, 2, 'የአዛዦችም አለቃ ኤርምያስን ወሰደው፤ እንዲህም አለው፥ “አምላክህ እግዚአብሔር ይህን ክፉ ነገር በዚህ ስፍራ ላይ ተናገረ።'),
  ('d31c8a5b-f80d-5577-af7a-b42d63bafbfc', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 3, 3, 'እግዚአብሔርም እንደ ተናገረው አደረገ፤ እርሱን በድላችኋልና፥ ቃሉንም አልሰማችሁምና ይህ ነገር ሆነባችሁ።'),
  ('c0e2f3ee-adb1-5892-a9ea-b6914b653a1c', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 4, 4, 'አሁንም እነሆ በእጅህ ካለችው ሰንሰለት ዛሬ ፈታሁህ። ከእኔ ጋር ወደ ባቢሎን መምጣት መልካም መስሎ ቢታይህ፥ ና፤ እኔም በመልካም አይሃለሁ፤ ከእኔ ጋር ወደ ባቢሎን መምጣት መልካም መስሎ ባይታይህ ግን፥ ተቀመጥ፤ ተመልከት፥ እነሆ፥ ሀገሪቱ ሁሉ በፊትህ ናት፤ ትሄድ ዘንድ መልካም መስሎ በሚታይህና ደስ በሚያሰኝህም ስፍራ ተቀመጥ።”'),
  ('44ff12b5-afef-5653-adc8-d3be8f262e97', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 5, 5, 'እርሱም ገና ሳይመለስ፥ “የባቢሎን ንጉሥ በይሁዳ ከተሞች ላይ ወደ ሾመው ወደ ሳፋን ልጅ ወደ አኪቃም ልጅ ወደ ጎዶልያስ ተመለስ፤ ከእርሱም ጋር በሕዝቡ መካከል በይሁዳ ምድር ተቀመጥ፤ ወይም ትሄድ ዘንድ ለዐይንህ ደስ ወደሚያሰኝህ ስፍራ ሂድ” አለው። የአዛዦችም አለቃ ስንቅና ስጦታ ሰጥቶ አሰናበተው።'),
  ('1202a1d9-a653-5f1d-aa49-a6cbc01ea83b', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '5bc0d304-1b55-5e94-a8ed-4ff5d76398a8', 6, 6, 'ኤርምያስም የአኪቃም ልጅ ጎዶልያስ ወደ አለበት ወደ መሴፋ ሄደ፤ ከእርሱም ጋር በሀገሩ ውስጥ በቀሩት ሕዝብ መካከል ተቀመጠ።'),
  ('c249216b-c1b3-5c5b-a0b3-cae588628316', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 1, 7, 'በየሜዳው የነበሩት የጭፍራ አለቆችና ሰዎቻቸው ሁሉ የባቢሎን ንጉሥ የአኪቃምን ልጅ ጎዶልያስን በሀገሩ ላይ እንደ ሾመ፥ ወንዶችንና ሴቶችን ልጆችንም፥ ወደ ባቢሎን ያልተማረኩትንም የምድርን ድሆች እንዳስጠበቀ በሰሙ ጊዜ፥'),
  ('36ce4a76-4095-501e-a7af-91c4f6316067', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 2, 8, 'የናታንያ ልጅ እስማኤል፥ የቃርሔም ልጆች ዮሐናንና ዮናታን፥ የተንሁሜትም ልጅ ሠራያ፥ የነጦፋዊውም የዮፌ ልጆች፥ የመከጢ ልጅ አዛንያም ከሰዎቻቸው ጋር ወደ ጎዶልያስ ወደ መሴፋ መጡ።'),
  ('4a222b26-54ec-5652-a16e-d4f10d553c95', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 3, 9, 'የሳፋንም ልጅ የአኪቃም ልጅ ጎዶልያስ ለእነርሱና ለሰዎቻቸው እንዲህ ብሎ ማለ፥ “ለከለዳውያን ትገዙ ዘንድ አትፍሩ፤ በምድር ተቀመጡ፤ ለባቢሎንም ንጉሥ ተገዙ፤ መልካምም ይሆንላችኋል።'),
  ('b1129892-1b42-5607-ac34-53d897f3bbce', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 4, 10, 'እነሆ እኔም ወደ እኛ በሚመጡት ከለዳውያን ፊት እቆም ዘንድ በመሴፋ እኖራለሁ፤ እናንተ ግን ወይኑንና ፍሬውን፥ ዘይቱንም አከማቹ፤ በየዕቃችሁም ውስጥ ክተቱ፤ በያዛችኋቸውም ከተሞቻችሁ ተቀመጡ።”'),
  ('90b41bcc-1345-5530-ac3d-cce15eb2026b', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 5, 11, 'በሞዓብና በአሞንም ልጆች መካከል፥ በኤዶምያስም፥ በምድርም ሁሉ ላይ የነበሩ አይሁድ ሁሉ የባቢሎን ንጉሥ የይሁዳን ቅሬታ እንዳስቀረ፥ የሳፋንንም ልጅ የአኪቃምን ልጅ ጎዶልያስን በላያቸው እንደ ሾመው ሰሙ።'),
  ('7ad63873-b6cc-5c6d-a4a9-097fee4ee7d8', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1ed794ee-e7ca-535e-a75e-6527be7cfc9e', 6, 12, 'አይሁድም ሁሉ ከተሰደዱበት ስፍራ ሁሉ ተመለሱ፤ ወደ ይሁዳም ሀገር ጎዶልያስ ወዳለበት ወደ መሴፋ መጡ፤ ወይንንና የበጋን ፍሬ፥ ዘይትንም እጅግ ብዙ አከማቹ።'),
  ('5d17e060-c109-5f9a-aa42-528c962ba3f4', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1b4b0118-fbf0-5618-a361-3b10f857ac31', 1, 13, 'የቃርሔም ልጅ ዮሐናን፥ በየሜዳውም የነበሩ የጭፍራ አለቆች ሁሉ ወደ ጎዶልያስ ወደ መሴፋ መጥተው፦'),
  ('68773d60-9a97-5988-aa0c-4887acaf9612', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1b4b0118-fbf0-5618-a361-3b10f857ac31', 2, 14, '“የአሞን ልጆች ንጉሥ በኣሊስ ይገድልህ ዘንድ የናታንያን ልጅ እስማኤልን እንደ ላከ ታውቃለህን?” አሉት። የአኪቃም ልጅ ጎዶልያስ ግን አላመናቸውም።'),
  ('31bebcb2-3b12-5c09-ace7-d98208aa1b7e', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1b4b0118-fbf0-5618-a361-3b10f857ac31', 3, 15, 'የቃርሔም ልጅ ዮሐናን፥ “እባክህ፥ ልሂድ፤ ማንም ሳያውቅ የናታንያን ልጅ እስማኤልን ልግደለው፤ ወደ አንተ የተሰበሰቡ አይሁድ ሁሉ እንዲበተኑ፥ የይሁዳም ቅሬታ እንዲጠፋ ነፍስህን ስለ ምን ይገድላል?” ብሎ በመሴፋ በቈይታ ለጎዶልያስ ተናገረ።'),
  ('bd0f4ed6-5c07-5825-a8c8-9619483ffbb5', 'f4403373-2021-52cf-a4ab-0b43bd04a4ef', '1b4b0118-fbf0-5618-a361-3b10f857ac31', 4, 16, 'የአኪቃም ልጅ ጎዶልያስ ግን የቃርሔን ልጅ ዮሐናንን፥ “በእስማኤል ላይ ሐሰት ተናግረሃልና ይህን ነገር አታድርግ” አለው።'),
  ('6b18f73b-3e45-5182-a08c-aa4f37fd6adf', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 1, 1, 'እንዲህም ሆነ፤ በሰባተኛው ወር ከመንግሥት ወገንና ከንጉሡ ዋና ዋና አለቆች አንዱ የኤሊሳማ ልጅ የናታንያ ልጅ እስማኤል ከዐሥር ሰዎች ጋር ወደ መሴፋ ወደ አኪቃም ልጅ ወደ ጎዶልያስ መጣ፤ በዚያም በመሴፋ በአንድ ላይ እንጀራ በሉ።'),
  ('9f4f9568-e83d-5ffe-ab7a-53ff9a1ead54', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 2, 2, 'የናታንያም ልጅ እስማኤል ከእርሱም ጋር የነበሩት ዐሥሩ ሰዎች ተነሥተው የሳፋንን ልጅ የአኪቃምን ልጅ ጎዶልያስን በሰይፍ መቱ፤ የባቢሎንም ንጉሥ በሀገሩ ላይ የሾመውን ገደሉ።'),
  ('3ff7e9a1-af31-5fee-a2ff-9d5e4f24d61b', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 3, 3, 'እስማኤልም ከጎዶልያስ ጋር በመሴፋ የነበሩትን አይሁድ ሁሉ፥ በዚያም የተገኙትን ከለዳውያንን ሁሉ፤ ሰልፈኞች ሰዎችንም ሁሉ ገደላቸው።'),
  ('ed78c1a5-4801-5b60-a30c-41841baaedb5', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 4, 4, 'እስማኤል ማንም ሳያውቅ ጎዶልያስን ከገደለ በኋላ በሁለተኛው ቀን እንዲህ ሆነ፤')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a8df4a8c-d317-5a36-a50b-e57278c821d5', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 5, 5, 'ጢማቸውን ላጭተው፥ ልብሳቸውንም ቀድደው እያለቀሱ ወደ እግዚአብሔር ቤት ያቀርቡ ዘንድ የእህል ቍርባንና ዕጣን በእጃቸው የያዙ፥ ሰማንያ ሰዎች ከሴኬምና ከሴሎ፥ ከሰማርያም መጡ።'),
  ('36cdc52c-dc47-54bd-a211-0322a047c8f0', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 6, 6, 'የናታንያም ልጅ እስማኤል ከመሴፋ ወጥቶ እያለቀሰ ሊገናኛቸው ሄደ፤ በተገናኛቸውም ጊዜ፥ “ወደ አኪቃም ልጅ ወደ ጎዶልያስ ኑ” አላቸው።'),
  ('0e2c35f3-3c2d-5dfb-af45-efc56f3209e3', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 7, 7, 'ወደ ከተማም መካከል በመጡ ጊዜ የናታንያ ልጅ እስማኤል፥ ከእርሱም ጋር የነበሩ ሰዎች ገደሉአቸው፤ በጕድጓድም መካከል ጣሉአቸው።'),
  ('bfa36048-0555-5460-ac1e-7b943e4f281c', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 8, 8, 'በዚያም የተገኙ ዐሥር ሰዎች ቀርበው እስማኤልን እንዲህ አሉት፥ “በሜዳው ድልብ አለንና፥ ገብስና ስንዴ፥ ዘይትና ማርም አለንና አትግደለን፤” እርሱም በወንድሞቻቸው መካከል እነርሱን መግደል ተወ።'),
  ('9102a0d5-a2a2-55dd-a273-5043682bf5ca', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 9, 9, 'እስማኤልም ከጎዶልያስ ጋር የገደላቸውን ሰዎች ሬሳ ሁሉ የጣለበት ጕድጓድ ንጉሡ አሳ የእስራኤልን ንጉሥ ባኦስን ስለ ፈራ የሠራው ጕድጓድ ነበረ፤ የናታንያም ልጅ እስማኤል የገደላቸውን ሞላበት።'),
  ('b43e83a0-4b03-5ffd-a87a-b582b2b67a12', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 10, 10, 'እስማኤልም በመሴፋ የነበረውን የሕዝቡን ቅሬታ ሁሉ፥ የንጉሡን ሴቶች ልጆች፥ የአዛዦች አለቃ ናቡዛርዳን ለአኪቃም ልጅ ለጎዶልያስ የሰጠውን በመሴፋ የቀሩትን ሕዝብ ሁሉ መለሰ፤ የናታንያም ልጅ እስማኤል ወደ አሞን ልጆች ይሄድ ዘንድ ተነሣ።'),
  ('4b48559e-65bf-52a9-a2ce-e1cc6b1d555d', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 11, 11, 'የቃርሔም ልጅ ዮሐናን፥ ከእርሱም ጋር የነበሩ የጭፍራ አለቆች ሁሉ የናታንያ ልጅ እስማኤል ያደረገውን ክፋት ሁሉ ሰሙ።'),
  ('b889c908-80c2-5766-a546-8ab32191f0e2', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 12, 12, 'ሠራዊቱንም ሁሉ ይዘው ከናታንያ ልጅ ከእስማኤል ጋር ሊዋጉ ሄዱ። በገባዖንም ባለው በብዙ ውኃ አጠገብ አገኙት።'),
  ('36b807ad-5fc1-5564-ac7a-01fa0394c43f', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 13, 13, 'እንዲህም ሆነ፤ ከእስማኤል ጋር የነበሩት ሕዝብ ሁሉ የቃርሔን ልጅ ዮሐናንን ከእርሱም ጋር የነበሩትን የጭፍራ አለቆችን ሁሉ ባዩ ጊዜ ደስ አላቸው።'),
  ('4a5f7794-ec82-584d-a0ab-d74ffff67669', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 14, 14, 'እስማኤልም ከመሴፋ የማረካቸው ሕዝብ ሁሉ ተመልሰው ወደ ቃርሔም ልጅ ወደ ዮሐናን ሔዱ።'),
  ('cec321ff-c120-553f-a78f-9695e0a45429', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 15, 15, 'የናታንያ ልጅ እስማኤል ግን ከስምንት ሰዎች ጋር ከዮሐናን አመለጠ፥ ወደ አሞንም ልጆች ሄደ።'),
  ('56d971c1-d2c7-548b-aa35-deeb98d7f8e6', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 16, 16, 'የቃርሔም ልጅ ዮሐናን፥ ከእርሱም ጋር የነበሩት የጭፍራ አለቆች ሁሉ የአኪቃምን ልጅ ጎዶልያስን በመሴፋ ከገደለው በኋላ ከናታንያ ልጅ ከእስማኤል ያስመለሱአቸውን የሕዝቡን ቅሬታ ሁሉ፥ ከገባዖን ያስመለሱአቸውን ኀያላን ሰልፈኞችን፥ ሴቶችንም፥ ልጆችንም፥ ጃንደረቦችንም ወሰዱ፤'),
  ('d7124ab8-d07d-5341-a526-6a8aae78ccd7', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 17, 17, 'ተነሥተውም ወደ ግብፅ ይሄዱ ዘንድ በቤተልሔም አጠገብ በአለው በጌሮት-ከመዓም ተቀመጡ፤'),
  ('e78cdf67-77af-529a-a966-2ae7b69a0a10', '96f33b1c-0eed-51c9-a704-ff46bd6ebdcc', 'e875c3f1-04f5-5987-a590-9d4a96e32a07', 18, 18, 'እስማኤል የባቢሎን ንጉሥ በሀገሩ ላይ የሾመውን የአኪቃምን ልጅ ጎዶልያስን ስለ ገደለው ከለዳውያንን ፈርተዋልና።'),
  ('83055b82-c43b-5b05-a941-535c0cd195ab', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 1, 1, 'የጭፍራ አለቆችም ሁሉ፥ የቃርሔም ልጅ ዮሐናን፥ የሐናንያ ልጅ ኢዛንያስ ሕዝቡም ሁሉ ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ወደ ነቢዩ ወደ ኤርምያስ መጡ።'),
  ('66fb4732-0cff-552e-a441-956c21167985', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 2, 2, 'እንዲህም አሉት፥ “እባክህ ልመናችን በፊትህ ትድረስ፤ ስለ እኛ፥ ስለ እነዚህም ቅሬታዎች ሁሉ ወደ አምላክህ ወደ እግዚአብሔር ጸልይልን፤ ዐይኖችህ እንደ አዩን ከብዙ ጥቂት ቀርተናልና።'),
  ('35de3df2-24f7-5a1b-a8d2-fd12f46fd80e', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 3, 3, 'አምላክህ እግዚአብሔርም የምንሄድበትን መንገድና የምናደርገውን ነገር ይንገረን።”'),
  ('5bdb9c3d-66f7-564e-a4ca-420d9d81f7d0', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 4, 4, 'ነቢዩ ኤርምያስም አላቸው፥ “ሰምታችኋል፤ እነሆ እንደ ቃላችሁ ወደ አምላካችሁ ወደ እግዚአብሔር እጸልያለሁ፤ እግዚአብሔርም የሚመልስልኝን ሁሉ እነግራችኋለሁ፤ ከእናንተም አንድም ቃል አልሸሽግም።”'),
  ('a57ecc08-0fa0-58ed-a763-051c6b0ef31a', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 5, 5, 'ኤርምያስንም፥ “አምላክህ እግዚአብሔር ወደ እኛ የላከህን ነገር ሁሉ ባናደርግ፥ እግዚአብሔር በመካከላችን እውነተኛና ታማኝ ምስክር ይሁን።'),
  ('7953db71-2d77-5e0b-a236-59bee14631ae', '421481e8-411e-5f00-a43e-439af1d6756a', 'b940a132-3180-5233-a394-46c3ab1aa3ea', 6, 6, 'የአምላካችንን የእግዚአብሔርን ቃል ስለምንሰማ መልካም እንዲሆንልን፥ መልካም ወይም ክፉ ቢሆን፥ አንተን ወደ እርሱ የምንልክህ የአምላካችንን የእግዚአብሔርን ቃል እንሰማለን” አሉት።'),
  ('09f90d8e-53f4-5cf7-a7ca-a2ce3b982038', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 1, 7, 'እንዲህም ሆነ፤ ከዐሥር ቀን በኋላ የእግዚአብሔር ቃል ወደ ኤርምያስ መጣ።'),
  ('f08fd326-134d-53bd-a130-7177b4860202', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 2, 8, 'የቃርሔምንም ልጅ ዮሐናንን፥ ከእርሱም ጋር የነበሩትን የጭፍራ አለቆች ሁሉ፥ ከታናሹ ጀምሮ እስከ ታላቁ ድረስ ሕዝቡንም ሁሉ ጠራ፤'),
  ('3cccf396-f5c5-571e-ac2f-52aab4933810', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 3, 9, 'እንዲህም አላቸው፥ “ልመናችሁን በፊቱ አቀርብ ዘንድ ወደ እርሱ የላካችሁኝ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦'),
  ('d5cc5cfd-26c6-5ec5-a475-4b8d068ba51a', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 4, 10, 'አደርግባችሁ ዘንድ ከአሰብሁት ክፉ ነገር ተመልሻለሁና በዚች ምድር ብትቀመጡ እሠራችኋለሁ እንጂ አላፈርሳችሁም፥ እተክላችኋለሁ እንጂ አልነቅላችሁም።'),
  ('7d1fe766-59a2-5338-ad9c-bba5927dbb49', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 5, 11, 'ከምትፈሩት ከባቢሎን ንጉሥ ፊት አትፍሩ፤ አድናችሁ ዘንድ፥ ከእጁም አስጥላችሁ ዘንድ እኔ ከእናንተ ጋር ነኝና አትፍሩ፥ ይላል እግዚአብሔር።'),
  ('4cbe8837-f925-5fa7-a66f-f8b2024a7080', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 6, 12, 'ይቅርታን እሰጣችኋለሁ፤ ይቅርም እላችኋለሁ፤ ወደ ሀገራችሁም እመልሳችኋለሁ።'),
  ('ffd26155-24e6-590d-ab4f-d3fa5e37f111', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 7, 13, '“እናንተ ግን በዚች ምድር አንቀመጥም ብትሉ፥ የአምላካችሁንም የእግዚአብሔርን ቃል ባትሰሙ፥'),
  ('14c6b18a-30c8-5794-a2f5-696299f9417c', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 8, 14, 'እናንተም፦ አይደለም፤ ሰልፍ ወደማናይባት፥ የመለከትም ድምፅ ወደማንሰማባት፥ እንጀራንም ወደማንራብባት ወደ ግብፅ ምድር እንሄዳለን፤ በዚያም እንቀመጣለን ብትሉ፥'),
  ('6ca8a97e-323f-507a-a929-701ee49d0370', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 9, 15, 'ስለዚህ እናንተ የይሁዳ ቅሬታ ሆይ! አሁን እንግዲህ የእግዚአብሔርን ቃል ስሙ፤ የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ ወደ ግብፅም ትገቡ ዘንድ በዚያም ትቀመጡ ዘንድ ፊታችሁን ብታቀኑ፤'),
  ('60738309-58e7-5a1d-a5df-44e3d6820bf0', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 10, 16, 'እናንተ የምትፈሩት ሰይፍ በዚያ በግብፅ ምድር ያገኛችኋል፤ ስለ እርሱም የምትደነግጡበት ራብ በዚያ በግብፅ ይደርስባችኋል፤ በዚያም ትሞታላችሁ።'),
  ('fa32adae-6c19-51f9-a2d0-e8d88526cacd', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 11, 17, 'ወደ ግብፅም ይገቡ ዘንድ፥ በዚያም ይቀመጡ ዘንድ ፊታቸውን በሚያቀኑ ሰዎች ሁሉ እንዲህ ይሆንባቸዋል፤ በሰይፍና በራብ፥ በቸነፈርም ያልቃሉ፤ እኔም ከማመጣባቸው ክፉ ነገር ማንም አይቀርም፤ ማንም አያመልጥም።'),
  ('abcf9f4f-2cff-5581-a5ce-aece77637b07', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 12, 18, '“የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላልና፦ ቍጣዬና መቅሠፍቴ በኢየሩሳሌም በሚኖሩ ላይ እንደ ፈሰሰ፥ እንዲሁ ወደ ግብፅ በገባችሁ ጊዜ መዓቴ ይፈስስባችኋል፤ እናንተም ለጥላቻና ለጥፋት ለስድብና ለርግማን ትሆናላችሁ፤ ይችንም ስፍራ ከእንግዲህ ወዲህ አታዩአትም።'),
  ('aa2c72ce-c759-50cf-aa02-84f71030c03a', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 13, 19, 'እናንተ የይሁዳ ቅሬታ ሆይ! እግዚአብሔር፦ ወደ ግብፅ አትግቡ ብሎ ተናግሮባችኋልና ዛሬ እንዳስጠነቀቅኋችሁ በእርግጥ ዕወቁ።'),
  ('5cac84e9-e7d9-52d6-a0c0-13cce8a47725', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 14, 20, 'እናንተ፦ ሰለ እኛ ወደ አምላካችን ወደ እግዚአብሔር ጸልይ፤ አምላካችንም እግዚአብሔር የሚናገርህን ሁሉ ንገረን፤ እኛም እናደርገዋለን ብላችሁ ወደ እግዚአብሔር ወደ አምላካችሁ ልካችሁኝ ነበርና ራሳችሁን አታልላችኋል።'),
  ('d3492b8d-f0cb-5265-ac46-10ceef6c2065', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 15, 21, 'እኔም ዛሬ ነግሬአችኋለሁ፤ ወደ እናንተም በላከኝ ነገር ሁሉ የአምላካችሁን የእግዚአብሔርን ቃል አልሰማችሁም።'),
  ('c438c3ba-cb37-548d-a8ca-7d59ba847f3b', '421481e8-411e-5f00-a43e-439af1d6756a', 'cea403e1-f4f0-510b-af97-f369e85d9300', 16, 22, 'አሁንም ሄዳችሁ እንድትቀመጡ በወደዳችሁበት ስፍራ በሰይፍና በራብ፥ በቸነፈርም እንድትሞቱ በእርግጥ ዕወቁ።”'),
  ('b4f77fac-1ba3-5bd6-a539-187b551d32d4', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 1, 1, 'የአምላካቸውን የእግዚአብሔርን ቃል ሁሉ፥ ለእነርሱ አምላካቸው እግዚአብሔር የላከውን ይህን ቃል ሁሉ፥ ኤርምያስ ለሕዝቡ ሁሉ መናገርን በፈጸመ ጊዜ እንዲህ ሆነ፤'),
  ('2077072f-dd45-5314-abb0-8b56ac3b7cb3', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 2, 2, 'የኢዮስያስ ልጅ ኣዛርያስ፥ የቃርሔም ልጅ ዮሐናን፥ ትዕቢተኞችም ሰዎች ሁሉ ኤርምያስን፥ “ሐሰት ተናግረሃል፤ አምላካችን እግዚአብሔር፦ በዚያ ትቀመጡ ዘንድ ወደ ግብፅ አትግቡ ብሎ አልላከህም፤'),
  ('c4b71d64-57cc-5e67-a51e-342dff68e345', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 3, 3, 'ነገር ግን ከለዳውያን እንዲገድሉን ወደ ባቢሎንም እንዲያፈልሱን በእጃቸው አሳልፈህ ትሰጠን ዘንድ የኔርዩ ልጅ ባሮክ በላያችን ላይ አነሣሥቶሃል” አሉት።'),
  ('a44a422e-6974-5e94-a6e5-608b40529a24', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 4, 4, 'የቃርሔም ልጅ ዮሐናን፥ የጭፍራ አለቆችም ሁሉ፥ ሕዝቡም ሁሉ በይሁዳ ምድር ይቀመጡ ዘንድ የእግዚአብሔርን ቃል አልሰሙም።'),
  ('55570919-489d-5322-a49e-f10f831b9490', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 5, 5, 'የቃርሔም ልጅ ዮሐናን፥ የጭፍራ አለቆችም ሁሉ በይሁዳ ምድር ለመቀመጥ ከተሰደዱባቸው ከአሕዛብ ሁሉ የተመለሱትን የይሁዳን ቅሬታ ሁሉ ወሰዱ።'),
  ('af9c04b4-2b7c-53dc-a449-599e93ed8a6e', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 6, 6, 'ወንዶችንና ሴቶችን፥ ሕፃናቱንም፥ የንጉሡንም ሴቶች ልጆች፥ የአዛዦችም አለቃ ናቡዛርዳን ከሳፋን ልጅ ከአኪቃም ልጅ ከጎዶልያስ ጋር የተዋቸውን ሰዎች ሁሉ፥ ነቢዩ ኤርምያስንና የኔርዩን ልጅ ባሮክንም ወሰዱ።'),
  ('4afeff54-c8b3-5601-ace9-e7b05c6f752e', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 7, 7, 'የእግዚአብሔርንም ቃል አልሰሙምና ወደ ግብፅ ምድር ገቡ፤ እስከ ጣፍናስ ድረስም መጡ።'),
  ('b84d9c56-e07a-5db8-a98e-f3e764ce79d7', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 8, 8, 'በጣፍናስም የእግዚአብሔር ቃል ወደ ኤርምያስ እንዲህ ሲል መጣ፦'),
  ('e30850d7-122e-55f2-ab92-40f9e37e3585', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 9, 9, '“ታላላቆችን ድንጋዮች በእጅህ ውሰድ፥ የይሁዳም ሰዎች እያዩ በጣፍናስ ባለው በፈርዖን ቤት ደጅ መግቢያ ሸሽጋቸው።'),
  ('7412e032-68df-57f7-a8bd-2c6c21fdeb36', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 10, 10, 'እንዲህም በላቸው፦ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ልኬ ባሪያዬን የባቢሎንን ንጉሥ ናቡከደነፆርን አመጣለሁ፤ ዙፋኑንም እኔ በሸሸግኋቸው በእነዚህ ድንጋዮች ላይ አኖራለሁ፤ ጋሻዎቹንም በእነርሱ ላይ ያነሣል።'),
  ('7c2edaa4-a7b0-5518-a173-c34a65c72be4', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 11, 11, 'መጥቶም የግብፅን ምድር ይመታል፤ ለሞትም የሚሆነውን ለሞት፥ ለምርኮም የሚሆነውን ለምርኮ፥ ለሰይፍም የሚሆነውን ለሰይፍ አሳልፎ ይሰጣል።'),
  ('55b71c2c-37be-5bf6-ac31-61aa4fc8c021', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 12, 12, 'በግብፅም አማልክት ቤቶች እሳትን ያነድዳል፤ ያቃጥላቸውማል፤ ይማርካቸውማል፤ እረኛም ልብሱን እንደሚቀምል እንዲሁ የግብፅን ሀገር ይቀምላታል፤ ከዚያም በሰላም ይወጣል።'),
  ('843e0471-6d75-5cc1-a909-05cdb455aa37', 'fbdea006-9e6e-5519-a20d-5acde37d4e6d', '9866f897-5c8f-5a10-a3a8-b4c895af1533', 13, 13, 'በግብፅ ምድርም ያለውን የፀሐይ ከተማ ምሰሶዎችን ይሰብራል፥ የግብፅንም አማልክት ቤቶች በእሳት ያቃጥላል።”'),
  ('3d42d656-e1e9-5c07-a43b-e19933c65a86', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 1, 1, 'በግብፅ ምድር በሚግዶልና በጣፍናስ፥ በሜምፎስም፥ በፋቱራም ሀገር ስለ ተቀመጡ አይሁድ ሁሉ ወደ ኤርምያስ የመጣ ቃል ይህ ነው፦'),
  ('604a8043-0984-58a8-a727-07cf52db4e64', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 2, 2, '“የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ በኢየሩሳሌምና በይሁዳ ከተሞች ሁሉ ያመጣሁትን ክፉ ነገር ሁሉ አይታችኋል፤ ከክፋታቸውም የተነሣ እነሆ ዛሬ ባድማ ሆነዋል፤ የሚቀመጥባቸውም የለም።'),
  ('4532377e-364e-5b96-af88-255a85c4223d', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 3, 3, 'ይህም የሆነው ያስቈጡኝ ዘንድ ስላደረጉት ክፋት፥ እነርሱና አባቶቻቸው ለማያውቁአቸው ለሌሎች አማልክት ያጥኑ ዘንድ፥ ያመልኳቸውም ዘንድ ስለሄዱ ነው።'),
  ('dc61c89e-0296-5397-a657-e29c58fe68ec', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 4, 4, 'በማለዳም ባሪያዎችን ነቢያትን ሁሉ ላክሁባቸው፤ የጠላሁትንም ርኩስ ነገር አታድርጉ ብዬ ላክሁባቸው።'),
  ('5076fd29-4c24-5228-a1fc-b46e44118703', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 5, 5, 'ነገር ግን አልሰሙኝም፤ ከክፋታቸውም ተመልሰው ለሌሎች አማልክት እንዳያጥኑ ጆሮአቸውን አልመለሱም።'),
  ('7df1099d-1647-59f3-a0d1-5137fbc04d5b', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 6, 6, 'ስለዚህ መዓቴና መቅሠፍቴ ወረደ፤ በይሁዳም ከተሞችና በኢየሩሳሌም አደባባይ ነደደ፤ ዛሬም እንደ ሆነው ጠፍና ባድማ ሆኑ።'),
  ('adcaa1c2-be0a-5976-a8c7-02bbe5f2d72c', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 7, 7, '“አሁንም የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ከይሁዳ ወገን መካከል ቅሬታ እንዳይቀርላችሁ፥ ወንድንና ሴትን፥ ብላቴናንና የሚጠባ ሕፃንን ከመካከላችሁ ታጠፉ ዘንድ ይህን ታላቅ ክፋት በራሳችሁ ላይ ለምን ታደርጋላችሁ?'),
  ('11f05b33-180b-525a-a47b-0fe6b299a424', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 8, 8, 'ሰውነታችሁንም ታጠፉ ዘንድ፥ በምድርም አሕዛብ ሁሉ መካከል መረገሚያና መሰደቢያ ትሆኑ ዘንድ፥ ለመቀመጥ በገባችሁባት በግብፅ ምድር ለሌሎች አማልክት በማጠናችሁ በእጃችሁ ሥራ ለምን ታስቈጡኛላችሁ?'),
  ('1c0d2c4e-204d-5db4-ad3e-89d06c4b3e42', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 9, 9, 'በውኑ በይሁዳ ምድርና በኢየሩሳሌም አደባባይ ያደረጉትን የአባቶቻችሁን ክፋት፥ የይሁዳንም ነገሥታት ክፋት፥ የአለቆቻቸውንም ክፋት የሚስቶቻችሁንም ክፋት ረስታችሁታልን?።'),
  ('caf82450-294c-5700-a44a-577266846f56', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 10, 10, 'እስከ ዛሬም ድረስ አላረፉም፤ አልፈሩምም፤ በእናንተና በአባቶቻችሁም ፊት ባኖርሁት ሕጌና ሥርዐቴ አልሄዱም።'),
  ('539e30d6-fa15-5b52-a679-b240a6c4a980', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 11, 11, '“ስለዚህም የእስራኤል አምላክ እግዚአብሔር እንዲህ ይላል፦ እነሆ፥ ይሁዳን ሁሉ አጠፋ ዘንድ፥ ፊቴን ለክፋት በላያችሁ አደርጋለሁ።'),
  ('5bae6168-4ee1-5492-a3d7-74013095d1e5', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 12, 12, 'ወደ ግብፅም ይገቡ ዘንድ፥ በዚያም ይቀመጡ ዘንድ ፊታቸውን ያቀኑትን የይሁዳን ቅሬታ እወስዳለሁ፤ ሁሉም ይጠፋሉ፤ በግብፅም ምድር ይወድቃሉ፤ በሰይፍና በራብ ይጠፋሉ፤ ከታናሹም ጀምሮ እስከ ታላቁ ድረስ በሰይፍና በራብ ይሞታሉ፤ ለጥላቻና ለጥፋት፥ ለመረገሚያና ለመሰደቢያ ይሆናሉ።'),
  ('a2521f08-abde-534b-abfd-ba876b3c76ac', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 13, 13, 'ኢየሩሳሌምንም በመዐት እንደ ጐበኘሁ፥ እንዲሁ በግብፅ ምድር የሚኖሩትን በሰይፍና በራብ በቸነፈርም እጐበኛለሁ።'),
  ('095216db-5bf7-5acc-a029-b89bda51bdd9', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 14, 14, 'በዚያ ለመቀመጥ በልባቸው ተስፋ ወደሚያደርጓት ወደ ይሁዳ ምድር ይመለሱ ዘንድ በግብፅ ለመኖር ከመጡ ከይሁዳ ቅሬታ ወገን የሚያመልጥና የሚቀር፥ ወደዚያም የሚመለስ አይኖርም፤ ከሚያመልጥም በቀር ማንም አይመለስም።”'),
  ('de0ceb8b-b5dd-5fc4-ad89-1cb878de95d4', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 15, 15, 'ሚስቶቻቸውም ለሌሎች አማልክት ማጠናቸውን ያወቁ ሰዎች ሁሉ፥ በዚያም የቆሙ ሴቶች ሁሉ፥ በግብፅም ምድር በጳትሮስ የተቀመጡ ሕዝብ ሁሉ፥ ታላቅ ጉባኤ ሆነው ለኤርምያስ መለሱለት፤ እንዲህም አሉ፦'),
  ('52668bbf-eb3c-5374-ad6c-d2483e8dfa12', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 16, 16, '“አንተ በእግዚአብሔር ስም የነገርኸንን ቃል አንሰማም።'),
  ('c643cf97-dac4-5478-a4cb-26d008a58840', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 17, 17, 'ነገር ግን እኛና አባቶቻችን፥ ነገሥታቶቻችንም፥ አለቆቻችንም በይሁዳ ከተሞችና በኢየሩሳሌም አደባባይ እናደርገው እንደ ነበረ፥ ለሰማይ ንግሥት እናጥን ዘንድ፥ የመጠጥንም ቍርባን እናፈስስላት ዘንድ ከአፋችን የወጣውን ቃል ሁሉ በርግጥ እናደርጋለን፤ በዚያ ጊዜም እንጀራን እንጠግብ ነበር፥ መልካምም ይሆንልን ነበር፤ ክፉም አናይም ነበር።'),
  ('1423e8aa-2ac7-5037-abb4-bc70f16a73b0', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 18, 18, 'ለሰማይ ንግሥት ማጠንን፥ ለእርስዋም የመጠጥን ቍርባን ማፍሰስን ከተውን ወዲህ ግን፥ እኛ ሁላችን አንሰናል፤ በሰይፍና በራብም አልቀናል።'),
  ('940ddac6-aefa-53b9-a82c-99a4dd4ff415', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 19, 19, 'እኛስ ለሰማይ ንግሥት ባጠንንላት፥ የመጠጥንም ቍርባን ባፈሰስንላት ጊዜ፥ በውኑ ያለ ባሎቻችን ምስልዋን ለማበጀት እንጎቻ አድርገንላት ኖሮአልን? የመጠጥንም ቍርባን አፍስሰንላት ኖሮአልን?”'),
  ('a05d50db-424e-56af-aa7d-6c1c4deb5411', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 20, 20, 'ኤርምያስም ይህን ቃል ለመለሱለት ሕዝብ ሁሉ፦ ለወንዶቹና ለሴቶቹ፥ ለሕዝቡም ሁሉ መለሰላቸው እንዲህም አለ፦'),
  ('06b84195-0a72-5efe-a2a3-441733f834d9', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 21, 21, '“እናንተና አባቶቻችሁ፥ ነገሥታቶቻችሁም፥ አለቆቻችሁም የምድርም ሕዝብ በይሁዳ ከተሞችና በኢየሩሳሌም አደባባይ ያጠናችሁትን ዕጣን እግዚአብሔር ያሰበው፥ በልቡም ያኖረው አይደለምን?'),
  ('126f52cb-53bf-500d-af0e-cc4f2920c564', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 22, 22, 'እግዚአብሔርም ከእንግዲህ ወዲህ የሥራችሁን ክፋትና ያደረጋችሁትን ርኵሰት ይታገሥ ዘንድ አልቻለም፤ ስለዚህ ምድራችሁ ባድማ፥ በረሃና መረገሚያ ሆናለች፤ እስከ ዛሬም የሚኖርባት የለም።'),
  ('d3632a72-392a-5e32-a21a-2fa253d0db6f', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 23, 23, 'ስላጠናችሁት ዕጣን፥ በእግዚአብሔርም ላይ ስለ በደላችሁ፥ የእግዚአብሔርንም ቃል ስላልሰማችሁ፥ በሕጉና በሥርዐቱም፥ በምስክሩም ስላልሄዳችሁ፥ ስለዚህ ዛሬ እንደ ሆነ ይች ክፉ ነገር አግኝታችኋለች።”'),
  ('c17ab32b-5581-5774-ada0-535c899cde6b', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 24, 24, 'ኤርምያስም ለሕዝቡ ሁሉ፥ ለሴቶቹም ሁሉ እንዲህ አለ፥ “በግብፅ ምድር የምትኖሩ አይሁድ ሁሉ! የእግዚአብሔርን ቃል ስሙ።'),
  ('3af00514-594e-5ba7-a4b3-3a5209f5af23', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 25, 25, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እናንተና ሚስቶቻችሁ በአፋችሁ፦ ለሰማይ ንግሥት እናጥን ዘንድ፥ የመጠጥንም ቍርባን እናፈስስላት ዘንድ የተሳልነውን ስእለታችንን በርግጥ እንፈጽማለን አላችሁ፤ በእጃችሁም አደረጋችሁት፤ እንግዲህ ስእለታችሁን አጽኑ፤ ስእለታችሁንም ፈጽሙ።'),
  ('28e291d0-0573-5314-a4ac-a7ce2be3a6d9', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 26, 26, 'ስለዚህ እናንተ በግብፅ ምድር የምትኖሩ አይሁድ ሁሉ! የእግዚአብሔርን ቃል ስሙ፤ በግብፅ ምድር ሁሉ በሚኖር በይሁዳ ሰው ሁሉ አፍ ስሜ ከእንግዲህ ወዲህ፦ ሕያው እግዚአብሔርን! ተብሎ እንዳይጠራ፥ እነሆ በታላቁ ስሜ ምያለሁ፥” ይላል እግዚእብሔር።'),
  ('487fff13-1ca8-5821-a237-3d08d45fe3c0', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 27, 27, 'እነሆ ለመልካም ሳይሆን ለክፋት እተጋባቸዋለሁ፤ በግብፅም ምድር ያሉት የይሁዳ ሰዎች ሁሉ እስኪጠፉ ድረስ በሰይፍና በራብ ያልቃሉ።'),
  ('99a47a68-f8c2-5bd6-afc8-e02719c55d76', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 28, 28, 'ከሰይፍም የሚያመልጡ በቍጥር ጥቂቶች ሰዎች ከግብፅ ምድር ወደ ይሁዳ ምድር ይመለሳሉ፤ ሊቀመጡም ወደ ግብፅ ምድር የገቡት የይሁዳ ቅሬታ ሁሉ ከእኔ ወይም ከእነርሱ የማናችን ቃል እንዲጸና ያውቃሉ።'),
  ('89cb38f5-1b5c-5b1f-a29c-526e25ba1a8d', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 29, 29, '“ቃሌም በላያችሁ ለክፋት እንዲጸና ታውቁ ዘንድ በዚች ስፍራ በክፉ እንደምጐበኛችሁ ምልክታችሁ ይህ ነው፥” ይላል እግዚአብሔር።'),
  ('7c0bfcd6-d197-57cb-abd4-82398f60863e', '668e9efd-c75e-5ff5-a49a-5e8ba621fccd', 'a622a76b-9edc-5f16-a282-7b3e93b1ba6d', 30, 30, 'እግዚአብሔር እንዲህ ይላል፦ የይሁዳን ንጉሥ ሴዴቅያስን ጠላቱ ለሆነው፥ ነፍሱንም ለፈለገው ለባቢሎን ንጉሥ ለናቡከደነፆር እጅ አሳልፌ እንደ ሰጠሁት፥ እንዲሁ እነሆ የግብፅን ንጉሥ ፈርዖን ሖፍራን ለጠላቶቹ፥ ነፍሱንም ለሚፈልጉ እጅ አሳልፌ እሰጠዋለሁ።'),
  ('6882783d-c2d4-5838-ad9c-9c38123c0967', 'fb6a4311-2689-5c9c-a4d0-e25107c35140', '8af88e72-0df8-5e8c-a313-c9383b1ea9b3', 1, 1, 'በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም በአራተኛው ዓመተ መንግሥት እነዚህን ቃላት ከኤርምያስ አፍ በመጽሐፍ በጻፋቸው ጊዜ፥ ነቢዩ ኤርምያስ ለኔርዩ ልጅ ለባሮክ የተናገረው ቃል ይህ ነው።'),
  ('fd359646-be79-5158-ac96-3752eb6e8e48', 'fb6a4311-2689-5c9c-a4d0-e25107c35140', '8af88e72-0df8-5e8c-a313-c9383b1ea9b3', 2, 2, '“ባሮክ ሆይ! የእስራኤል አምላክ እግዚእብሔር እንዲህ ይልሃል፦'),
  ('add205fd-47d3-54cd-af0c-bfd38faceb67', 'fb6a4311-2689-5c9c-a4d0-e25107c35140', '8af88e72-0df8-5e8c-a313-c9383b1ea9b3', 3, 3, 'አንተ፦ እግዚአብሔር በሕማሜ ላይ ኀዘንን ጨምሮብኛልና ወዮልኝ! በልቅሶዬ ጩኸት ደክሜአለሁ፤ ዕረፍትንም አላገኘሁም ብለሃል።'),
  ('d4f30b81-23d0-5598-a200-9e77c91948e1', 'fb6a4311-2689-5c9c-a4d0-e25107c35140', '8af88e72-0df8-5e8c-a313-c9383b1ea9b3', 4, 4, 'እንዲህ በለው፦ እግዚአብሔር እንዲህ ይላል፦ እነሆ የሠራሁትን አፈርሳለሁ፥ የተከልሁትንም እነቅላለሁ፤ ይኸውም በምድር ሁሉ ነው።'),
  ('19a26c54-b30e-55d0-a490-078f9de6f9dc', 'fb6a4311-2689-5c9c-a4d0-e25107c35140', '8af88e72-0df8-5e8c-a313-c9383b1ea9b3', 5, 5, 'ለራስህ ታላላቅ ነገሮችን ትፈልጋለህን? በሥጋ ለባሽ ሁሉ ላይ እነሆ ክፉ ነገርን አመጣለሁና አትፈልጋቸው፥ ይላል እግዚአብሔር፤ ነገር ግን በሄድህበት ስፍራ ሁሉ ነፍስህን እንደ ምርኮ አድርጌ እሰጥሃለሁ።”'),
  ('3d47bd46-72bb-560d-a0d5-f9e9650e6739', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 1, 1, 'በአሕዛብ ላይ ወደ ነቢዩ ወደ ኤርምያስ የመጣው የእግዚአብሔር ቃል ይህ ነው።'),
  ('0b446444-1793-51f9-abd9-728205662187', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 2, 2, 'በግብፅ ላይ፤ በኤፍራጥስ ወንዝ አጠገብ በከርኬማስ በነበረው፥ በይሁዳ ንጉሥ በኢዮስያስ ልጅ በኢዮአቄም በአራተኛው ዓመተ መንግሥት የባቢሎን ንጉሥ ናቡከደነፆር በመታው በግብፅ ንጉሥ በፈርዖን ኒካዑ ሠራዊት፥'),
  ('528d86da-b365-5a24-a964-cf02b8c51067', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 3, 3, '“ጋሻና ጦር ያዙ፤ ወደ ሰልፍም ቅረቡ።'),
  ('f4ec8e98-6e91-530a-a0cf-ae0f114e680b', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 4, 4, 'ፈረሰኞች ሆይ፥ ፈረሶችን ጫኑና ውጡ፤ ራስ ቍርንም ደፍታችሁ ቁሙ፤ ጦርንም ሰንግሉ፤ ጥሩርንም ልበሱ።'),
  ('7019b4b7-7885-5d9f-a613-bf701dfc2272', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 5, 5, 'ፈርተው ወደ ኋላ ሲመለሱ፥ ኀያላኖቻቸውም ሲደክሙ፥ ወደ ኋላቸውም ሳይመለከቱ ፈጥነው ሲሸሹ ለምን አየሁ? በዙሪያቸውም ይከቡአቸዋል፥” ይላል እግዚአብሔር።'),
  ('2c38b66f-4fbd-5042-a414-d58350e33fd0', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 6, 6, 'ፈጣኑም አያመልጥም፤ ኀያሉም አይድንም፤ በሰሜን በኤፍራጥስ ወንዝ በኩል ደክመው ወደቁ።'),
  ('764836cc-8a2b-58a7-a9e3-dd930d69b088', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 7, 7, 'ይህ እንደ ወንዝ የሚነሣ ውኃውም እንደ ወንዝ የሚናወጥ ማን ነው?'),
  ('745ee916-0a3a-5644-a428-8a2d088cff8d', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 8, 8, 'ግብፅ እንደ ወንዝ ይነሣል፤ ከባሕሩም እንደሚታወክ ማዕበል ይሆናል፤ እርሱም እንዲህ ብሏል፥ “እነሣለሁ፤ ምድርንም ሁሉ እከድናለሁ፤ ከተሞችንና የሚኖሩባቸውን አጠፋለሁ።'),
  ('3158a633-f68d-51cf-ac0c-427023126053', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 9, 9, 'በፈረሶች ተቀመጡ፤ ሰረገሎችንም አዘጋጁና ውጡ፤ ጋሻም የሚያነግቡ የኢትዮጵያና የሊብያ ኀያላን፥ ቀስትንም ይዘው የሚስቡ የሉድ ኀያላን ይውጡ።'),
  ('0918388c-05ae-58b9-a4f9-888f65f3af71', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 10, 10, 'ያ ቀን ጠላቶቹን የሚበቀልበት የአምላካችን የእግዚአብሔር የበቀል ቀን ነው፤ የእግዚአብሔር ሰይፍ በልቶ ይጠግባል፤ በደማቸውም ይሰክራል፤ የሠራዊት ጌታ የእግዚአብሔር መሥዋዕት በሰሜን ምድር በኤፍራጥስ ወንዝ አጠገብ ነውና።'),
  ('13629c40-1d77-5ae9-aded-9b92b6532c93', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 11, 11, 'ድንግሊቱ የግብፅ ልጅ ሆይ! ወደ ገለዓድ ውጪ፤ የሚቀባ መድኀኒትንም ውሰጂ፤ ለምንም የማይጠቅምሽን መድኀኒት በከንቱ አብዝተሻል።'),
  ('7709d498-1695-5558-a5be-9cfda7a4726c', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '26f9db8a-a2b7-5c8e-ac14-73a0aec0d634', 12, 12, 'ጦረኞች በጦረኞች ላይ ተሰናክለው ሁለቱ በአንድነት ወድቀዋልና አሕዛብ ቃልሽን ሰምተዋል፤ ልቅሶሽም ምድርን ሞልቶአታል።”'),
  ('37dca624-8f0e-5588-a751-4130a9be4484', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 1, 13, 'የባቢሎን ንጉሥ ናቡከደነፆር እንደሚመጣና የግብፅን ምድር እንደሚመታ እግዚአብሔር ለነቢዩ ለኤርምያስ የተናገረው ቃል ይህ ነው።'),
  ('10d68c1a-0202-5090-a7a0-e9c8da0bd9ac', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 2, 14, '“በግብፅ ተናገሩ፤ በሚግዶልም አውሩ፤ በሜምፎስና በጣፍናስ አሰሙ፤ ሰይፍ በዙሪያህ ያለውን በልቶአልና፦ ተነሥ ተዘጋጅም በሉ።'),
  ('269e03fd-927b-5b7e-a887-686af61603fa', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 3, 15, 'ኀይለኞችህ ስለ ምን ታጡ? እግዚአብሔር ስላደከማቸው የሉም።'),
  ('27a5ed81-d0f3-56cb-aa63-3f51112b8731', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 4, 16, 'ብዛታቸውም ደከመ፤ ወደቀም፤ አንዱም አንዱ ለጓደኛው፦ ተነሥ፤ ከአረማውያን ሰይፍ ፊት ወደ ወገናችን ወደ ተወለድንባት ምድር እንመለስ አለው።'),
  ('92a7a19d-f966-5b67-ad0d-1b8d77ca3c82', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 5, 17, 'በዚያም የግብፅ ንጉሥ የፈርዖንን ስም ጊዜውን የሚያሳልፍ ብለው ጠሩት።'),
  ('1786ec94-98e0-5178-afdd-89a4604c724a', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 6, 18, 'እኔ ሕያው ነኝና በተራሮች መካከል እንዳለ እንደ አጤቤርዮን፥ በባሕርም አጠገብ እንዳለ እንደ ቀርሜሎስ፥ እንዲሁ በእውነት ይመጣል፥ ይላል ስሙ የሠራዊት ጌታ የሆነ ንጉሥ እግዚአብሔር።'),
  ('b50c4c07-4632-5b57-af2f-23ffec29e890', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 7, 19, 'አንቺ በግብፅ የምትቀመጪ ልጅ ሆይ! ሜምፎስ ባድማ ትሆናለችና፥ የሚቀመጥባትም አይገኝምና ለፍልሰት የሚሆን ዕቃ አዘጋጂ።'),
  ('825f548b-a331-5eb9-ab37-707b3f4bd82a', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 8, 20, '“ግብፅ የተዋበች ጊደር ናት፤ ጥፋት ግን ከሰሜን በኩል ይመጣባታል።'),
  ('f457cfba-de2d-5713-a3c3-1b0112c164e4', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 9, 21, 'በእርስዋም ያሉ የተቀጠሩ ሠራተኞች በእርስዋ ተቀልበው እንደ ሰቡ ወይፈኖች ናቸው፤ የጥፋታቸው ቀንና የቅጣታቸው ጊዜ መጥቶባቸዋልና ተመለሱ፤ በአንድነትም ሸሹ፤ አልቆሙምም።'),
  ('b7983f2b-7398-5c43-a4cb-2781f66b2a85', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 10, 22, 'ሠራዊትም በኀይል ይዘምቱባታልና፥ እንደ እንጨት ቈራጮችም በምሳር ይመጡባታልና ድምፅዋ እንደምትሸሽ እባብ ይተማል።'),
  ('e42baff8-28bd-5af7-aefa-92defdbfc315', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 11, 23, 'ሊቈጠሩ የማይችሉ የዱርዋን ዛፎች ይቈርጣሉ፥ ይላል እግዚአብሔር፤ ከአንበጣ ይልቅ በዝተዋልና፥ ቍጥርም የላቸውምና።'),
  ('8e2052df-1632-54b1-a2e8-4c13c27cde20', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 12, 24, 'የግብፅ ልጅ ታፍራለች፤ በሰሜን ሕዝብ እጅም አልፋ ትሰጣለች።”'),
  ('618b5172-24cf-5062-a379-d692ecbf317d', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 13, 25, 'የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “እነሆ የኖእ አሞንን፥ ፈርዖንንም፥ ግብጽንም፥ አማልክቶችዋንና ነገሥታቶችዋንም፥ ፈርዖንንና በእርሱም የሚታመኑትን እቀጣለሁ።'),
  ('6db1ff19-0e96-5a48-a3e2-cee9cce794f8', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '431de0a1-0f93-5172-a9b3-2e9a87840402', 14, 26, 'ነፍሳቸውንም በሚፈልጉ ሰዎች እጅ፥ በባቢሎንም ንጉሥ በናቡከደነፆር እጅ፥ በአገልጋዮቹም እጅ አሳልፌ እሰጣቸዋለሁ፤ ከዚያም በኋላ እንደ ቀድሞው ዘመን የሰው መኖሪያ ትሆናለች፥ ይላል እግዚአብሔር።”'),
  ('fede6322-3f79-5d42-a32e-e869c88c448d', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '7b24fbf6-0f38-5bd4-a903-2d679dfa8004', 1, 27, '“ነገር ግን አንተ ባሪያዬ ያዕቆብ ሆይ! አትፍራ፥ አንተም እስራኤል ሆይ! አትደንግጥ፤ እነሆ አንተን ከሩቅ፥ ዘርህንም ከተማረኩባት ምድር አድናለሁ፤ ያዕቆብም ተመልሶ ያርፋል፤ ተዘልሎም ይተኛል፤ ማንም አያስፈራውም።'),
  ('dab89e4b-ccdf-5aad-a397-c77bd5de37a8', 'ff9e7667-fa14-5e9e-aafd-b9b9b86e5606', '7b24fbf6-0f38-5bd4-a903-2d679dfa8004', 2, 28, 'አንተ ባሪያዬ ያዕቆብ ሆይ! እኔ ከአንተ ጋር ነኝና አትፍራ፥” ይላል እግዚአብሔር፤ አንተንም ያሳደድሁባቸውን አሕዛብን ሁሉ ፈጽሜ አጠፋለሁና፥ አንተን ግን ፈጽሜ አላጠፋህም፤ በመጠን እቀጣሃለሁ፥ ያለ ቅጣትም አልተውህም።”'),
  ('8c08ab5c-6218-5776-a789-2c45bddf0ff9', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 1, 1, 'ፈርዖንም ጋዛን ሳይመታ ስለ ፍልስጥኤማውያን ወደ ነቢዩ ወደ ኤርምያስ የመጣው የእግዚአብሔር ቃል ይህ ነው።'),
  ('9ab7b69a-6a5c-506e-a204-f0f35f4a2d94', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 2, 2, 'እግዚአብሔር እንዲህ ይላል፥ “እነሆ ውኃ ከሰሜን ይነሣል፥ የሚያጥለቀልቅም ፈሳሽ ይሆናል፤ በሀገሪቱና በመላዋ ሁሉ፥ በከተማዪቱና በሚኖሩባትም ላይ ይጐርፋል፤ ሰዎቹም ይጮኻሉ፤ በምድርም የሚኖሩ ሁሉ ያለቅሳሉ።'),
  ('00a77673-2fa9-5201-aec6-dc4506675ea7', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 3, 3, 'ከኀይለኞች ፈረሶች ከኮቴያቸው መጠብጠብ ድምፅ፥ ከሰረገሎቹም መሽከርከር፥ ከመንኰራኵሮቹም መትመም የተነሣ አባቶች በእጃቸው ድካም ምክንያት ወደ ልጆቻቸው አይመለሱም።'),
  ('a9927fe5-3bf6-5f9b-a1a0-8afd4026112e', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 4, 4, 'ይህም የሚሆነው ፍልስጥኤማውያንን ሁሉ ታጠፋ ዘንድ፥ ጢሮስንና ሲዶናን የቀሩትንም ረዳቶቻቸውን ታጠፋ ዘንድ ስለምትመጣው ቀን ነው፤ እግዚአብሔር ፍልስጥኤማውያንንና በከፍቶር ደሴት የቀሩትን ያጠፋልና።'),
  ('fe476fed-bd31-574d-ae69-250197fbf4d3', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 5, 5, 'ቡሀነት በጋዛ ላይ መጥቶአል፤ አስቀሎና ጠፋች፤ የዔናቅ ቅሬታዎች ሆይ! እስከ መቼ ድረስ ገላችሁን ትነጫላችሁ?'),
  ('67c8d524-43ba-562b-a884-f9103d4c1605', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 6, 6, 'አንተ የእግዚአብሔር ሰይፍ ሆይ! ዝም የማትለው እስከ መቼ ነው? ወደ ሰገባህ ግባ፤ ጸጥ ብለህም ዕረፍ።'),
  ('71eccb6b-b5bc-5846-aaf2-a66376666e87', '4ec53d8a-7a72-563e-a9a7-9e6f05777a24', '29fa634f-12fe-5b40-ae4a-1d1eeb2e83d8', 7, 7, 'እግዚአብሔር በአስቀሎናና በባሕር ዳር በቀሩትም ቦታዎች ላይ ትእዛዝ ሰጥቶአልና፥ በዚያም አዘጋጅቶታልና እንዴት ዝም ትላለህ? በዚያ ትነሣለህ።'),
  ('f68ba952-9db8-5859-a054-25eb79ae2fe7', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 1, 1, 'ስለ ሞአብ፤ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ ናባው ጠፍታለችና ወዮላት! ቂርያታይም አፍራለች፤ ተይዛማለች፤ መጠጊያዋም አፍራለች፤ ደንግጣማለች።'),
  ('ab616165-b50e-54ec-a308-c55b08477816', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 2, 2, 'ከእንግዲህ ወዲህ የሞአብ ፈውስ የለም፤ በሐሴቦን ላይ፥ “ኑ ሕዝብ እንዳትሆን እናጥፋት” ብለው ክፉ ነገርን አስበውባታል። ፈጽሞ ትተዋለች፤ ከኋላዋ ሰይፍ ይመጣልና።'),
  ('b508cb9b-a4bd-5e4d-abbb-55349e5a378f', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 3, 3, 'መፍረስና ታላቅ ጥፋት የሚል የጩኸት ቃል ከሖሮናይም ተሰማ።'),
  ('c417dff2-939a-51c5-aa91-74344fbce944', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 4, 4, 'ሞአብ ጠፍታለች፤ ይህንም በሴጎር ተናገሩ።'),
  ('d4710a41-e669-5c3c-a973-48243271ec10', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 5, 5, 'በሎዊት ዓቀበት ልቅሶ እያለቀሱ ይወጣሉና፥ በሖሮናይምም መንገድ የመባባትን ጩኸት ሰምተዋል።'),
  ('f2d22739-e182-5ce8-a0a4-7fb153f86a86', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 6, 6, '“ሸሽታችሁ ራሳችሁን አድኑ፤ እንደ ሜዳ አህያ በምድረ በዳ ተቀመጡ፤'),
  ('9fcb51a7-a0f7-5d16-a0ed-d09cedda1198', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 7, 7, 'በሥራሽና በመዝገብሽ ታምነሻልና አንቺ ደግሞ ትያዢያለሽ፤ ካሞሽም ከካህናቱና ከአለቆቹ ጋር በአንድነት ይማረካል።'),
  ('7687899d-242f-5727-a2f0-7b7aaa1f84a2', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 8, 8, 'እግዚአብሔርም እንደ ተናገረ፥ ጥፋት ወደ ከተማ ሁሉ ይመጣል፤ አንዲትም ከተማ አትድንም፤ ሸለቆውም ይጠፋል፤ ሜዳውም ይበላሻል።'),
  ('8dfdec05-f926-5d44-a5be-ac4c686db0b0', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 9, 9, 'በርራ እንድትወጣ ለሞአብ ክንፍ ስጡአት፤ ከተሞችዋም ባድማ ይሆናሉ፤ የሚኖርባቸውም የለም።'),
  ('2ba75261-0976-5090-af3e-ffdd3878171e', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 10, 10, 'የእግዚአብሔርን ሥራ በቸልታ የሚያደርግ ርጉም ይሁን፤ ሰይፉንም ከደም የሚከለክል ርጉም ይሁን።'),
  ('fefdd0c8-3e60-5e97-a4de-4ff2edf77ee3', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 11, 11, '“ሞአብ ከልጅነቷ ጀምራ ዐረፈች፤ በክብርዋም ቅምጥል ነበረች፤ ወይንዋም ከዕቃ ወደ ዕቃ አልተገላበጠም፤ ወደ ምርኮም አልሄደችም፤ ስለዚህ ቃናው በእርስዋ ውስጥ ቀርቶአል፤ መዓዛዋም አልተለወጠም።'),
  ('b563959f-5844-5218-a20b-44983677214f', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 12, 12, 'ስለዚህ እነሆ ጠማሞችን የምልክበት ዘመን ይመጣል፥ ይላል እግዚአብሔር፤ እነርሱም ይጠሙበታል፤ ጋኖቹንም ይቀጠቅጣሉ፤ ፊቀኖቹንም ይሰብራሉ።'),
  ('d1fe0cd9-7229-5aa6-a8a2-c053337f8936', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 13, 13, 'የእስራኤልም ቤት ይታመንባት ከነበረው ከቤቴል እንዳፈረ፥ እንዲሁ ሞአብ ከካሞሽ ታፍራለች።'),
  ('98074442-dc37-5360-a231-000fc10e8113', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 14, 14, 'እናንተ፦ እኛ ኀያላን በሰልፍም ጽኑዓን ነን እንዴት ትላላችሁ?'),
  ('57291064-3a75-549c-a506-f95bbc2df258', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 15, 15, 'ሞዓብ ፈርሳለች፤ ከተሞቹዋም ጠፍተዋል፤ የተመረጡትም ጐልማሶችዋ ወደ መታረድ ወርደዋል፥ ይላል ስሙ የሠራዊት ጌታ እግዚአብሔር።'),
  ('980ce880-5c3d-5abe-ab3f-c5fceaaeecc2', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 16, 16, 'የሞአብ ጥፋት ሊመጣ ቀርቦአል፤ መከራውም እጅግ ይፈጥናል።'),
  ('0af391ad-ed7f-5508-a221-f375f4726069', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 17, 17, 'በዙሪያው ያላችሁ ሁሉ ስሙንም የምታውቁ ሁሉ፦ ታላቁ በትር፥ ጠንካራውም ሽመል፥ እንዴት ተሰበረ! ብላችሁ አልቅሱለት።'),
  ('3bfa4e00-1402-500f-aa8e-04bec139f62e', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 18, 18, 'በዲቦን የምትኖሪ ሆይ! ሞአብን የሚያጠፋ ወጥቶብሻልና፥ አምባሽንም ሰብሮአልና ከክብርሽ ውረጂ፤ በጭቃም ላይ ተቀመጪ።'),
  ('91813ad3-4895-5c10-a2e0-e38680e9c370', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 19, 19, 'በአሮዔር የምትኖሪ ሆይ! በመንገድ አጠገብ ቆመሽ ተመልከቺ፤ የሸሸውንና ያመለጠውን፦ ምን ሆኖአል? ብለሽ ጠይቂው።'),
  ('b8f5e4b6-1ef8-566a-a699-3f695f3a3d6f', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 20, 20, '“ሞአብ ፈርሳለችና አፈረች፤ አልቅሱ፥ ጩኹም፤ ሞአብ እንደ ጠፋች በአርኖን አውሩ።'),
  ('d45b734b-dd6a-5045-ad3a-1b83cfaeef9c', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 21, 21, 'ፍርድ ይመጣል፤ በሜሶር ምድር፥ በኬሎን፥ በያሳና፥ በሜፍዓት ላይ፤'),
  ('c92cb17a-54b8-5e6c-ac06-1c37d82830ce', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 22, 22, 'በዲቦን፥ በናባው፥ በቤትዲብላታይም ላይ፥'),
  ('ab8485df-e06e-5047-ae65-f5e8a39ca2b1', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 23, 23, 'በቂርያታይም፥ በቤትጋሙል፥ በቤትምዖን ላይ፥'),
  ('4e2ab1c9-dfb5-5156-ad55-c0f35d30c113', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 24, 24, 'በቂርዮት፥ በቦሶራ፥ በሞአብም ምድር ከተሞች ሁሉ ቅርብና ሩቅ በሆኑ ላይ ፍርድ መጥቶአል።'),
  ('2c283c20-329f-58ef-ae94-5ed95fbec867', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', '871635d4-b994-52f7-ac25-ed7c7a4921fa', 25, 25, 'የሞአብ ቀንድ ተሰበረ፤ እጁም ተቀጠቀጠ ይላል እግዚአብሔር።'),
  ('26414299-f554-5496-aaf9-5cf91fb8f686', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 1, 26, '“በእግዚአብሔር ላይ ኰርቶአልና፥ አስክሩት፤ ሞአብም በትፋቱ ላይ ይንከባለላል፤ በእጁም ያጨበጭባል፤ ደግሞ መሳቂያ ይሆናል።'),
  ('1f261242-5e31-50cc-a261-5046f35fc312', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 2, 27, 'እስራኤል ለአንተ መሳቂያ አልሆነምን? ወይስ በሌቦች መካከል ተገኝቶአልን? ስለ እርሱ በተናገርህ ጊዜ ራስህን ትነቀንቃለህ።'),
  ('195caeb6-0e7c-5176-ae3c-ef41d3674243', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 3, 28, 'በሞአብ የሚኖሩ ከተሞችን ትተው በዓለት ውስጥ ተቀመጡ፤ በገደል አፋፍም ቤቷን እንደምትሠራ እንደ ርግብ ሆኑ።'),
  ('4936d151-8c36-54fb-ad13-466f4a31e67a', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 4, 29, 'የሞአብን ስድብ፥ የተዋረደውንም ብዙ ውርደቱን፥ ልቡናውንም ያስታበየበትን ትዕቢቱን ሰምተናል።'),
  ('f62bb499-bec5-589b-a611-39d1ed2d1fc8', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 5, 30, 'እኔ ሥራውን አውቃለሁ ይላል እግዚአብሔር፤ እንደ ኀይሉም መጠን እንዲሁ ያደረገ አይደለም።'),
  ('9cc05496-7659-5365-acda-6561c3ecff7f', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 6, 31, 'ሰለዚህ ለሞአብ አለቅሳለሁ፤ ለሞአብም ሁሉ እጮኻለሁ፤ ለቂርሔሬስ ሰዎች አለቅሳለሁ።'),
  ('3ff87cae-c773-5ac0-a758-bdc1fea1211c', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 7, 32, 'አንቺ የሴባማ ወይን ሆይ! የኢያዜርን ልቅሶ ለአንቺ አለቅሳለሁ፤ ቅርንጫፎችሽ ባሕርን ተሻግረዋል፤ ወደ ኢያዜርም ባሕር ደርሰዋል፤ ሳይበስል በሰብልሽና በወይንሽ ላይ ጥፋት መጥቶአል።'),
  ('831ae9bd-3af8-54f3-a27e-9d22c17d19bc', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 8, 33, 'ሐሤትና ደስታ ከፍሬያማው እርሻና ከሞአብ ምድር ጠፍተዋል፤ ወይን ከመጥመቂያው ጠፍቶአል፤ በነግህ የሚጠምቁት የለም፤ በሠርክም የሚያደርጉት የእልልታ ድምፅ የለም።'),
  ('37d1bc53-f71d-575d-a407-c6fec5e8d1cf', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 9, 34, 'ከሐሴቦን ጩኸት እስከ ኤሊያሊና እስከ ኢያሳ ድረስ ድምፃቸውን ሰጥተዋል፤ ከሴጎር እስከ ሖሮናይምና እስከ ዔግላት ሺሊሺያ ድረስ ይደርሳል፤ የኔምሬም ውኃ ደርቋልና።'),
  ('2c159515-5d3b-5b34-aa24-b958112ee1f9', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 10, 35, 'ሞአብንና በኮረብታው መስገጃ ላይ የሚሠዋውን፥ ለአማልክቱም የሚያጥነውን አጠፋለሁ፥ ይላል እግዚአብሔር።'),
  ('ce7ce089-20c3-5ac0-a9c9-56a09df4aff6', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 11, 36, '“ያተረፈው ትርፉ ጠፍቶበታልና ስለዚህ ልቤ ለሞአብ እንደ እንቢልታ ይጮኻል፤ ልቤም ለቂርሔሬስ ሰዎች እንደ እንቢልታ ይጮኻል፤'),
  ('7790e03a-3a3d-5283-a973-c85ccdf52ce9', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 12, 37, 'በሰው ሁሉ ራስ ላይ ቡሃነት አለ፤ ጽሕማቸውን ሁሉ ይላጫሉ፤ እጆች ሁሉ ይንቀጠቀጣሉ፤ ሁሉም በወገባቸው ማቅን ይታጠቃሉ።'),
  ('5d1bf2ac-589c-5912-a40f-5bc2168dfd63', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 13, 38, 'ሞአብንም ለምንም እንደማይጠቅም ዕቃ ሰብሬአለሁና በሞአብ ሰገነት ሁሉ ላይ፥ በአደባባዩም ላይ ልቅሶ አለ፥” ይላል እግዚአብሔር።'),
  ('6d985e4e-50b7-5e98-aa86-c09ccaf4d01a', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 14, 39, 'እንዴት ተለወጠች! ከእፍረትም የተነሣ ሞአብ ጀርባዋን እንዴት መለሰች! ሞአብም በዙሪያዋ ላሉት ሁሉ መሳቂያና መሳለቂያ ትሆናለች።'),
  ('aa2ad14f-27d1-51f6-a1ba-a0725681c870', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 15, 40, 'እግዚአብሔር እንዲህ ይላልና፥ “እነሆ እንደ ንስር ይበርራል፤ ክንፉንም በሞአብ ላይ ይዘረጋል።'),
  ('fa5abe82-6517-54a4-a0da-6332bce0ab8b', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 16, 41, 'ሐቄርዮት ተያዘች፤ አንባዎችዋም ተወስደዋል፤ በዚያም ቀን የሞአብ ኀያላን ልብ ምጥ እንደ ያዛት ሴት ልብ ይሆናል።'),
  ('66a99f9c-6a8c-5f1a-a286-e22a59928a26', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 17, 42, 'ሞአብም በእግዚአብሔር ላይ ኰርታለችና ሕዝብ ከመሆን ትጠፋለች።'),
  ('82b2751b-e41b-5db8-a9db-c5641a8139f2', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 18, 43, 'በሞአብ የምትኖር ሆይ! ፍርሀትና ጕድጓድ፥ ወጥመድም በአንተ ላይ አሉ፥ ይላል እግዚአብሔር፤'),
  ('bf54316b-53cc-545d-a5e0-fc091b009a90', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 19, 44, 'እርስዋን በምጐበኝበት ዓመት በሞአብ ላይ ይህን አመጣለሁ፤ በፍርሀት የሸሸ በጕድጓድ ውስጥ ይወድቃል፤ ከጕድጓድም የወጣ በወጥመድ ይያዛል፤ ይላል እግዚአብሔር።'),
  ('51cfb974-b2fb-5ccf-a8ef-839167364be6', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 20, 45, 'ከሰልፍ የሸሹ ከሐሴቦን ጥላ በታች ቆመዋል፤ እሳት ከሐሴቦን፥ ነበልባልም ከሴዎን ወጥቶአል፤ የሞአብንም ማዕዘን፥ የሚጮኹ ልጆችንም ራስ በልቶአል።'),
  ('380efd9d-05ef-5d51-a9d4-d00c6ce4e4e3', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 21, 46, 'ሞአብ ሆይ! ወዮልሽ! የካሞሸ ወገን ጠፍቶአል፤ ወንዶች ልጆችሽ ተማርከው ተወስደዋልና፥ ሴቶች ልጆችሽም ወደ ምርኮ ሄደዋልና።'),
  ('843b84c7-4937-5640-aaab-2e90e4cd1501', '56dec701-ce02-54c0-a4ed-bdcd49c85fe6', 'ce6939b0-81b7-5a54-a084-c4a302aead36', 22, 47, 'ነገር ግን በኋለኛው ዘመን የሞአብን ምርኮ እመልሳለሁ፥” ይላል እግዚአብሔር። የሞዓብ ፍርድ እስከዚህ ድረስ ነው።'),
  ('c734f2c5-6b54-5690-adbe-7ddc462a1da0', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 1, 1, 'ስለ አሞን ልጆች እግዚአብሔር እንዲህ ይላል፥ “ሚልኮም ጋድን ይወርስ ዘንድ ሕዝቡም በከተሞቹ ላይ ይቀመጥ ዘንድ ለእስራኤል ልጆች የሉትምን? ወይስ ወራሽ የለውምን?'),
  ('d4de1b1a-095f-50f4-a763-d7c60576d594', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 2, 2, 'ስለዚህ እነሆ በአሞን ልጆች ከተማ በራባት ላይ የሰልፍ ውካታን የማሰማበት ዘመን ይመጣል፥ ይላል እግዚአብሔር፤ ለጥፋትም ትሆናለች፥ መንደሮችዋም በእሳት ይቃጠላሉ፤ እስራኤልም የወረሱትን ይወርሳል፥ ይላል እግዚአብሔር።'),
  ('d0eb9a66-4cf5-5e62-a37e-a09ead7ac816', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 3, 3, 'ሐሴቦን ሆይ! ጋይ ፈርሳለችና አልቅሽላት፤ እናንተም የራባት ሴቶች ልጆች ሆይ! ሚልኮም፥ ካህናቱና አለቆቹም በአንድነት ይማረካሉና ጩኹ፤ ማቅም ታጠቁ፤ አልቅሱም።'),
  ('a353ed88-0d08-5758-af54-cc4313b70cdc', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 4, 4, 'ማን ይመጣብኛል ብለሽ በሀብትሽ የታመንሽ አንቺ ከዳተኛ ልጅ ሆይ! በጠፉ ሸለቆዎችሽ ስለ ምን ትመኪያለሽ?'),
  ('632aae9a-9864-54e4-a061-7cc96da32c9f', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 5, 5, 'እነሆ በዙሪያሽ ካሉት ሁሉ ዘንድ ፍርሀትን አመጣብሻለሁ፥ ይላል የሠራዊት ጌታ እግዚአብሔር፤ እያንዳንዳችሁም በፊታችሁ ወዳለው ስፍራ ትሰደዳላችሁ፤ የሚሸሹትንም የሚሰበስብ የለም።'),
  ('11bfd92d-d731-5174-a6b1-b38446f63ff9', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 6, 6, 'ነገር ግን ከዚያ በኋላ የአሞንን ልጆች ምርኮ እመልሳለሁ ይላል እግዚአብሔር።”'),
  ('e95b3adc-fea2-5804-aead-6a411550182b', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 7, 7, 'ስለ ኤዶምያስ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “በውኑ በቴማን ጥበብ የለምን? ከብልሃተኞችስ ምክር ጠፍቶአልን? ጥበባቸውስ አልቆአልን?'),
  ('ef6641e8-df95-5cb1-a375-a1254e73f5ac', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 8, 8, 'እናንተ በድዳን የምትኖሩ ሆይ! የዔሳውን ጥፋት፥ የምጐበኝበትን ጊዜ አመጣበታለሁና ሽሹ፤ ወደ ኋላም ተመለሱ፤ በጥልቅም ጕድጓድ ውስጥ ተቀመጡ።'),
  ('eef7a8ad-e14b-5635-a17e-44bc9e2fdd40', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 9, 9, 'ወይን ለቃሚዎች ቢመጡብህ፥ ቃርሚያውን አይተዉልህምን? ሌቦችስ በሌሊት ቢመጡ፥ የሚያጠፉት እስኪበቃቸው ድረስ አይደለምን?'),
  ('7e4ddd8d-5fd1-57be-aea1-7d935a56afba', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 10, 10, 'እኔ ግን ዔሳውን አራቆትሁት፤ የተሸሸጉትንም ስፍራዎች ገለጥሁ፤ ይሸሸግም ዘንድ አይችልም፤ ዘሩም፤ ወንድሞቹም፤ ጎረቤቶቹም ጠፍተዋል፥ እርሱም የለም።'),
  ('c0149bb8-9d25-58e4-aa3f-ef161d459c3d', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 11, 11, 'ድሃአደጎችህን ተው፤ እኔም በሕይወት አኖራቸዋለሁ፤ መበለቶችህም በእኔ ይታመናሉ።'),
  ('c23711dd-ec51-5d14-a2e0-3cf17a813f53', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 12, 12, 'እግዚአብሔር እንዲህ ይላልና፦ እነሆ ጽዋውን ያልተገባቸው ሰዎች ጠጥተውታል፤ አንተም መንጻትን ትነጻለህን? እንግዲህ አትነጻም መጠጣትን ትጠጣለህና።'),
  ('91ddf4e5-a68b-5114-a94a-483a9a5e163f', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 13, 13, 'ባሶራ ምድረ በዳ፥ መሰደቢያና መረገሚያም እንድትሆን በራሴ ምያለሁ፥ ይላል እግዚአብሔር፤ ከተሞችዋም ሁሉ ለዘለዓለም ባድማ ይሆናሉ።'),
  ('c7e20cc4-e0fd-5382-a8f9-6a7b24b5a574', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 14, 14, '“ከእግዚአብሔር ዘንድ መስማትን ሰምቻለሁ፤ በአሕዛብ ሀገሮች ተሰብሰቡ፤ በእርስዋም ላይ ኑ፤ እርስዋንም ውጓት፥ የሚል መልእክተኛ ተልኳል።'),
  ('2cdab6aa-9302-569c-aebe-bd83bcde6b4d', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 15, 15, 'እነሆ በሕዝብ ዘንድ የተጠቃህ፥ በሰዎችም ዘንድ የተናቅህ አድርጌሃለሁ።'),
  ('eb56985a-ad21-5ba9-af74-6f244931ae1b', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 16, 16, 'በዓለት ንቃቃት ውስጥ የምትቀመጥ፥ የተራራውን ከፍታ የምትይዝ ሆይ! ድፍረትህና የልብህ ኵራት አነሣሥተውሃል። ቤትህንም ምንም እንደ ንስር ከፍ ብታደርግ፥ ከዚያ አወርድሃለሁ፥” ይላል እግዚአብሔር።'),
  ('4756e8ed-f5cd-5c76-ac51-101960a6053b', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 17, 17, '“ኤዶምያስም ምድረ በዳ ትሆናለች፤ የሚያልፍባትም ሁሉ ይደነቃል፤ ስለ መጣባትም መቅሠፍት ሁሉ ያፍዋጭባታል።'),
  ('a12c0abd-9455-58f2-acb5-fb2c8ec35846', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 18, 18, 'ሰዶምና ገሞራ፥ በእነርሱም አጠገብ የነበሩት ከተሞች እንደ ተገለበጡ፥ ይላል ሁሉን የሚገዛ እግዚአብሔር፤ እንዲሁ በዚያ ሰው አይቀመጥም፤ የሰው ልጅም አይኖርባትም።'),
  ('4aa2438f-4388-59cf-a4a6-dae1bd26b1be', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 19, 19, 'እነሆ ከእርስዋ ዘንድ በቶሎ አባርራቸዋለሁና ከዮርዳኖስ ዳር ወደ ኤታም እንደ አንበሳ ይወጣል፤ ጐልማሶችንም በእርስዋ ላይ እሾማለሁ፤ እንደ እኔ ያለ ማን ነው? ወይስ ለእኔ ጊዜን የሚወስን ማን ነው? ወይስ ፊቴን የሚቃወም እረኛ ማን ነው?”'),
  ('6f5d12bc-a606-580f-a784-3e0d818fbe88', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 20, 20, 'ስለዚህ እግዚአብሔር በኤዶምያስ ላይ የመከረባትን ምክር፥ በቴማንም በሚኖሩ ስዎች ላይ ያሰባትን ዐሳብ ስሙ፤ ትንንሾች በጎችን ዘርፈው ይወስዷቸዋል፤ የሚኖሩባትንም ማደሪያቸውን ባድማ ያደርጉባቸዋል።'),
  ('381f3637-1093-57b7-a470-595038a843cb', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 21, 21, 'ከመውደቃቸው ድምፅ የተነሣ ምድር ደነገጠች፤ ድምፅዋም እንደ ባሕር ድምፅ እነሆ ተሰማ።'),
  ('5b793215-9f73-52e2-adbe-a72baf404fd6', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 22, 22, 'እነሆ እንደ ንስር ወጥቶ ይመለከታል፤ ክንፉንም በባሶራ ላይ ይዘረጋል፤ በዚያም ቀን የኤዶምያስ ኀያላን ልብ ምጥ እንደ ያዛት ሴት ልብ ይሆናል።'),
  ('e6de0860-39dd-5313-a168-82d854c12ab7', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 23, 23, '“ስለ ደማስቆ፤ ክፉ ወሬ ሰምተዋልና ሐማትና አርፋድ አፈሩ፤ ቀለጡም፤ እንደ ባሕርም ተነዋወጡ፤ ያርፉም ዘንድ አይችሉም።'),
  ('3afd9135-a72e-564d-ab8a-604863974e0c', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 24, 24, 'ደማስቆ ደከመች፤ ተሸብራም ሸሸች፤ እንቅጥቅጥም ያዛት፤ እንደ ወላድም ሴት ጣርና ምጥ ያዛት።'),
  ('f3ce358c-729f-508f-a417-f89413840833', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 25, 25, 'የወደዱትን ቦታና ከተማ እንዴት አልተዉላትም?'),
  ('cbb18d50-b4b9-5d32-a3ec-c61c99c1459d', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 26, 26, 'ስለዚህ ጐበዛዝቷ በአደባባይዋ ላይ ይወድቃሉ፤ በዚያም ቀን ሰልፈኞች ሁሉ ይወድቃሉ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('9b2ba252-39f2-5cb3-ae39-c0036faa31ee', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 27, 27, 'በደማስቆም ቅጥር ላይ እሳት አነድዳለሁ፤ የወልደ አዴርንም አዳራሾች ትበላለች።”'),
  ('b1349edc-944b-5078-a1ed-28df32cc7dc3', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 28, 28, 'የባቢሎን ንጉሥ ናቡከደነፆር ስለ መታቸው ስለ ቄዳርና ስለ አሦር መንግሥታት እግዚአብሔር እንዲህ ይላል፥ “ተነሡ ወደ ቄዳርም ውጡ፤ የምሥራቅንም ልጆች አጥፉ።'),
  ('7ca63b16-e424-5a91-aa9f-0e6a9a379027', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 29, 29, 'ድንኳናቸውንና በጎቻቸውን ይወስዳሉ፤ መጋረጃዎቻቸውንና ዕቃቸውን ሁሉ፥ ግመሎቻቸውንም ለራሳቸው ይወስዳሉ፤ በዙሪያቸውም ሁሉ ጥፋትን ጥሩባቸው።'),
  ('0772724d-1b1f-5704-a2e2-5b605ee4244c', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 30, 30, 'እናንተ በአሦር የምትኖሩ ሆይ! የባቢሎን ንጉሥ ናቡከደነፆር ተማክሮባችኋልና፥ ክፉ አሳብንም አስቦባችኋልና ሽሹ፤ ወደ ሩቅም ሂዱ፤ በጥልቅ ጕድጓድም ውስጥ ተቀመጡ፥” ይላል እግዚአብሔር።'),
  ('ff8ccec1-802b-5624-ac17-7128be962f24', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 31, 31, '“ተነሡ፤ ዕረፍት ወዳለበት፥ ተዘልሎም ወደ ተቀመጠው፥ ደጅና መዝጊያ፥ መወርወሪያም ወደሌለው፥ ብቻውንም ወደ ተቀመጠው ሕዝብ ዝመቱ።'),
  ('52996e7b-191d-534b-a4b0-caae08384eba', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 32, 32, 'ግመሎቻቸው ለምርኮ ይሆናሉ፤ የእንስሶቻቸውም ብዛት ለጥፋት ይሆናል፤ ጠጕራቸውንም በዙሪያ የሚላጩትን ሰዎች ወደ ነፋሳት ሁሉ እበትናቸዋለሁ፤ ከዳርቻቸው ሁሉ ጥፋት አመጣባቸዋለሁ፥” ይላል እግዚአብሔር፥'),
  ('41d58465-e48f-52d2-a9ad-9f1e00d0b07d', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '2e2ee3c9-62df-58ee-a2fb-8f2c13d15eab', 33, 33, 'አሦርም የወፎች መኖሪያና የዘለዓለም ባድማ ትሆናለች፤ በዚያም ሰው አይኖርም፤ የሰው ልጅም አይቀመጥባትም።'),
  ('9fb28e91-7ad2-541f-a964-ec50e6567d63', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 1, 34, 'በይሁዳ ንጉሥ በሴዴቅያስ በመጀመሪያው ዓመተ መንግሥት ስለ ኤላም ወደ ነቢዩ ወደ ኤርምያስ የመጣው የእግዚአብሔር ቃል ይህ ነው።'),
  ('5a616c1f-d719-5792-a778-5c8ca92fa861', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 2, 35, '“የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፦ እነሆ ዋና የኀይላቸው መሣሪያ የሆነውን የኤላምን ቀስት እሰብራለሁ።'),
  ('e80cd9de-cd55-59cb-ae39-287059efd6ff', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 3, 36, 'ከአራቱም ከሰማይ ማዕዘናት አራቱን ነፋሳት በኤላም ላይ አመጣለሁ፤ ወደ እነዚያም ነፋሳት ሁሉ እበትናቸዋለሁ፤ ከኤላም የተሰደዱ ሰዎች የማይደርሱበት ሕዝብ አይገኝም።'),
  ('c059a027-bfa2-5f47-ad81-bd8e9df6147e', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 4, 37, 'በጠላቶቻቸውና ነፍሳቸውን በሚሹአት ፊት ኤላምን አስደነግጣለሁ። ክፉ ነገርን እርሱም ጽኑ ቍጣዬን አመጣባቸዋለሁ፥ ይላል እግዚአብሔር፤ እስካጠፋቸውም ድረስ በኋላቸው ሰይፍን እሰድድባቸዋለሁ።'),
  ('1bf6cd31-4a81-5096-a0f3-f790708cc654', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 5, 38, 'ዙፋኔንም በኤላም አኖራለሁ፤ ከዚያም ንጉሡንና መሳፍንቱን አጠፋለሁ፥ ይላል እግዚአብሔር።'),
  ('b01caafe-3fc5-55e4-af60-445088907fa5', 'cc74bfb6-3e1a-5dab-ab8b-4956938fbf8d', '15317067-622f-5653-a582-89f758dafe2a', 6, 39, 'ነገር ግን በኋለኛው ዘመን እንዲህ ይሆናል፤ የኤላምን ምርኮ እመልሳለሁ፥” ይላል እግዚአብሔር።'),
  ('e7ba14bb-37d2-5624-ae75-fb9a48f5a167', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 1, 1, 'እግዚአብሔር በከለዳውያን ምድር በባቢሎን ላይ በነቢዩ በኤርምያስ የተናገረው ቃል ይህ ነው።'),
  ('db9e4b21-680c-5ee0-acf8-18bcdeb0c129', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 2, 2, '“ለአሕዛብ ተናገሩ፤ አውሩም፤ ዓላማውንም አንሡ፥ አትደብቁ፦ ባቢሎን ተያዘች፤ ቤል አፈረ፤ ሜሮዳክ ፈራች፤ ምስሎችዋም አፈሩ፤ ጣዖታቷም ደነገጡ፤ በሉ።'),
  ('00ba23b6-b9a7-51c9-ab60-902e36d508b4', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 3, 3, 'ሕዝቤ ከሰሜን በእርስዋ ላይ ወጥትዋል፤ ምድርዋንም ባድማ ያደርጋል፤ የሚቀመጥባትም አይገኝም፤ ከሰው ጀምሮ እስከ እንስሳ ድረስ ሸሽተው ሄደዋል።'),
  ('26f81ed8-c4d6-51dd-aaf4-6fbd46839a78', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 4, 4, '“በዚያም ወራት በዚያም ጊዜ፥ ይላል እግዚአብሔር፤ የእስራኤል ልጆችና የይሁዳ ልጆች በአንድነት ሆነው ይመጣሉ፤ እያለቀሱም መንገዳቸውን ይሄዳሉ፥ አምላካቸውንም እግዚአብሔርን ይፈልጋሉ።'),
  ('3110e2c2-8046-55b0-ade3-50feeeea95a7', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 5, 5, 'ወደ ጽዮን የሚሄዱበትን ጎዳና ይመረምራሉ፤ ፊታቸውንም ወደ ሀገራቸው ይመልሳሉ፤ የዘለዓለም ቃልኪዳን አይረሳምና መጥተው ወደ ፈጣሪያቸው ወደ እግዚአብሔር ይማጠናሉ።'),
  ('e178b1f3-568b-581d-afcf-eb955c597ce4', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 6, 6, '“ሕዝቤ የጠፉ በጎች ሆነዋል፤ እረኞቻቸው አሳቱአቸው፤ በተራሮችም ላይ የተቅበዘበዙ አደረጉአቸው፤ ከተራራ ወደ ኮረብታ ዐለፉ፤ በረታቸውንም ረሱ።'),
  ('97ff50e8-6c75-50bb-ae92-9ca7f0432a1c', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 7, 7, 'ያገኙአቸው ሁሉ በሉአቸው፤ ጠላቶቻቸውም፦ በጽድቅ ማደሪያ በእግዚአብሔር ላይ፥ በአባቶቻቸው ተስፋ በእግዚአብሔር ላይ ኀጢአት ስለ ሠሩ እኛ አናሳርፋቸውም አሉ።'),
  ('af6fa601-1ac6-5fdd-acda-cd5aa0fc1bdb', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 8, 8, 'ከባቢሎን መካከል ሽሹ፤ ከከለዳውያንም ምድር ውጡ፤ በበጎችም ፊት እንደ እባቦች ሁኑ።'),
  ('0018a339-8ad7-5c37-a059-780f3e9bb3ba', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 9, 9, 'እነሆ ከሰሜን ምድር የታላላቅ አሕዛብን ጉባኤ አነሣለሁ፤ በባቢሎንም ላይ አመጣቸዋለሁ፤ በእርስዋም ላይ ይሰለፋሉ፤ ከዚያም ትወሰዳለች፤ ፍላጾቻቸውም ባዶውን እንደማይመለስ እንደ ብልህ ተዋጊ ፍላጻ ናቸው።'),
  ('2643ad3a-daad-5a2b-a1e9-9f02fc912ab5', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 10, 10, 'የከላውዴዎን ምድር ትዘረፋለች፤ የማረኳትም ሁሉ ይጠግባሉ፥” ይላል እግዚአብሔር።'),
  ('9e50a1a7-c161-5fce-a46f-70e518c0569e', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 11, 11, '“ርስቴን የምትበዘብዙ እናንተ ሆይ! ደስ ብሎአችኋልና፥ ሐሤትንም አድርጋችኋልና፥ በመስክ ላይም እንዳለች ጊደር ሆናችሁ ተቀናጥታችኋልና፥ እንደ ብርቱዎችም በሬዎች ቷጋላችሁና፤'),
  ('8cc9c382-71f1-5d77-a352-81017eb4aa38', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 12, 12, 'እናታችሁ እጅግ ታፍራለች፤ የወለደቻችሁም ትጐሰቍላለች፤ እነሆ በአሕዛብ መካከል ኋለኛዪቱ ትሆናለች፤ ምድረ በዳና ደረቅ ምድር፥ በረሀም ትሆናለች።'),
  ('03efd274-398c-5442-ac96-6d4480e38a08', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 13, 13, 'ከእግዚአብሔር ቍጣ የተነሣ ባድማ ትሆናለች እንጂ ሰው አይቀመጥባትም፤ በባቢሎንም በኩል የሚያልፍ ሁሉ ይደነቃል፤ በመጣባትም መቅሠፍት ሁሉ ያፍዋጫል።'),
  ('d3ad3129-cf04-5998-ab13-71fde7a7ff2e', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 14, 14, '“እናንተ ቀስትን የምትገትሩ ሰዎች ሁሉ፥ በባቢሎን ላይ በዙሪያዋ ተሰለፉ፤ በእግዚአብሔር ላይ ኀጢአት ሠርታለችና ወርውሩባት፤ እርስዋንም ከመውጋት ቸል አትበሉ፤'),
  ('341e5fde-5145-5bdf-a2cd-018dc11e2529', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 15, 15, 'እጆችዋ ደክመዋልና ክበቡአት፤ ግንቧ ወድቋል፤ ቅጥርዋም ፈርሶአል፤ የእግዚአብሔርም በቀል ነውና ተበቀሏት፤ እንደ ሠራችውም ሥሩባት።'),
  ('91292b67-7644-511b-a2a0-c7a050ddd794', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 16, 16, 'ዘሪውንና በመከር ጊዜ ማጭድ የሚይዘውን ከባቢሎን አጥፉ፤ ከአረማዊው ሰይፍ ፊት የተነሣ እያንዳንዱ ወደ ወገኑ ይመለሳል፤ እያንዳንዱም ወደ ሀገሩ ይሸሻል።'),
  ('2e0116b0-1d79-518e-ae79-039efd2fb519', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 17, 17, '“እስራኤል የባዘነ በግ ነው፤ አንበሶች አሳደዱት፤ መጀመሪያ የአሦር ንጉሥ በላው፥ በመጨረሻም የባቢሎን ንጉሥ ናቡከደነፆር አጥንቱን ቈረጠመው።”'),
  ('6e0bcc01-6cf6-5f3d-ad7e-11c8a2c27bc0', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 18, 18, 'ስለዚህ የእስራኤል አምላክ የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “የአሦርን ንጉሥ እንደ ተበቀልሁ እንዲሁ እነሆ የባቢሎንን ንጉሥና ምድሩን እበቀላለሁ።'),
  ('025b10ce-4811-5d38-a466-a5d9a97c8a52', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 19, 19, 'እስራኤልንም ወደ ማሰማርያው እመልሳለሁ፥ በቀርሜሎስና በባሳን፥ በኤፍሬም ተራራና በገለዓድም ይሰማራል፤ ነፍሱም ትጠግባለች።'),
  ('22555618-5cbb-5ba3-a551-b7fc0e02ad00', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 20, 20, 'በዚያ ወራት በዚያም ዘመን፥ ይላል እግዚአብሔር፤ እነዚህን በምድር የተረፉትን ይቅር እላቸዋለሁና የእስራኤል በደል ይፈለጋል፤ አይኖርምም፤ የይሁዳም ኀጢአት ይፈለጋል፥ ምንም አይገኝም።'),
  ('a38b5971-dae8-5873-a173-a8fdba3c7764', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 21, 21, '“በላይዋና በሚኖሩባት ላይ በምሬት ውጡ፤ ሰይፍ ሆይ! ተበቀዪ፥ ፍጻሜያቸውንም አጥፊ፥ ይላል እግዚአብሔር፤ ያዘዝሁሽንም ሁሉ አድርጊ።'),
  ('cad0a9d8-48b7-5bbc-aadb-bcfb2777041a', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 22, 22, 'የሰልፍና የታላቅ ጥፋት ውካታ በምድር ላይ አለ።'),
  ('442a3256-4b40-57ce-a7ba-b44cc4b2c435', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 23, 23, 'ምድርን ሁሉ የምትፈጫት መዶሻ እንዴት ደቀቀች! እንዴትስ ተሰበረች! ባቢሎንስ በአሕዛብ መካከል እንዴት ባድማ ሆነች!'),
  ('df1c4f6e-0f43-596e-a2de-7482751988c4', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 24, 24, 'ባቢሎን ሆይ! በመከራው ተይዘሽ ጠፋሽ፤ አንቺም ይህ እንደመጣብሽ አላወቅሽም፤ እግዚአብሔርን ተቃውመሽዋልና ተገኝተሻል፤ ተይዘሽማል።'),
  ('35b9d7b9-8c4b-53a7-a8be-ed9b84a8f0e2', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 25, 25, 'የሠራዊት ጌታ እግዚአብሔር በከለዳውያን ምድር ይሠራ ዘንድ ሥራ አለውና እግዚአብሔር ዕቃ ቤቱን ከፍቶ የቍጣውን ዕቃ ጦር አውጥቶአል።'),
  ('31c8fad5-f942-5ecb-ace2-85155edf4f14', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 26, 26, 'ጊዜዋ ደርሶአልና ሣጥኖችዋን ከፍታችሁ እንደ ዋሻ በርብሯት፤ ጨርሳችሁም አጥፏት፥ ምንም አታስቀሩላት።'),
  ('0f34f887-8576-51eb-a2af-58c619f910a6', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 27, 27, 'ፍሬዋን ሁሉ አድርቁባት፤ ወደ መታረድም ይውረዱ፤ ቀናቸው ደርሳለችና፥ እነሱን የሚበቀሉበት ጊዜ ደርሷልና ወዮላቸው!'),
  ('3ac48ec0-9f89-5652-ab6c-3c75469b3b70', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 28, 28, 'የአምላካችንን የእግዚአብሔርን በቀል፥ የመቅደሱንም በቀል፥ በጽዮን ይነግሩ ዘንድ ሸሽተው ከባቢሎን ሀገር ያመለጡት ሰዎች ድምፅ ተሰምቶአል።'),
  ('7c7d9e55-f0a2-5e66-adc5-d506c1200cd3', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 29, 29, '“ቀስትን የሚገትሩ ቀስተኞችን ሁሉ በባቢሎን ላይ ጥሩአቸው፤ በዙሪያዋ ስፈሩባት፤ ከእርስዋም ሰዎች አንድ አያምልጥ፤ የእስራኤልን ቅዱስ እግዚአብሔርን ተቃውማለችና እንደ ሥራዋ መጠን መልሱላት፤ እንዳደረገችም ሁሉ አድርጉባት።'),
  ('716a5d56-4eeb-5eba-a219-9b01400a699a', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 30, 30, 'ስለዚህ ጐበዛዝቷ በአደባባይዋ ላይ ይወድቃሉ፤ በዚያም ቀን ሰልፈኞችዋ ሁሉ ይጠፋሉ ይላል እግዚአብሔር።'),
  ('8cc4d4ea-f5fb-5388-a9ab-85d3766ce199', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 31, 31, 'ትዕቢተኛ ሆይ! አንቺን የሚበቀሉበት ጊዜ፥ ቀንሽ ደርሶአልና እነሆ በአንቺ ላይ ነኝ፥ ይላል የሠራዊት ጌታ እግዚአብሔር።'),
  ('0f5c5e21-3994-520a-a70e-6645053733c9', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 32, 32, 'አንቺ ትዕቢተኛ ሆይ!፥ ትደክሚያለሽ፤ ትወድቂያለሽም፤ የሚያነሳሽም የለም፤ በዛፎችሽ ውስጥ እሳትን አነድዳለሁ፤ በዙሪያሽ ያለውንም ሁሉ ትበላለች።”'),
  ('15c63c2c-ca08-5ada-ac58-4c2ad82fab96', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 33, 33, 'የሠራዊት ጌታ እግዚአብሔር እንዲህ ይላል፥ “የእስራኤል ልጆችና የይሁዳ ልጆች በአንድነት ተገፍተዋል፤ የማረኩአቸውም ሁሉ በኀይል ይይዙአቸዋል፤ ይለቅቁአቸውም ዘንድ እንቢ ብለዋል።'),
  ('f80ddca1-0ccb-5cd9-af3a-c3be66196a28', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 34, 34, 'የሚቤዢአቸው ብርቱ ነው፤ ስሙም ሁሉን የሚገዛ እግዚአብሔር ነው፤ ምድርን ያሳርፍ ዘንድ፥ በባቢሎንም የሚኖሩትን ያውክ ዘንድ ጠላቶቹን ወቀሳ ይወቅሳቸዋል።'),
  ('6cea5738-616f-5a09-ab50-69508ad5bc0e', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 35, 35, 'ሰይፍ በከለዳውያንና በባቢሎን በሚኖሩ ላይ፥ በመሳፍንቶችዋና በጥበበኞችዋ ላይ አለ፥ ይላል እግዚአብሔር።'),
  ('6c0033cd-812a-5af4-a13a-0d418bb0a34a', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 36, 36, 'ሰይፍ በተዋጊዎችዋ ላይ አለ፤ እነርሱም ይደክማሉ። ሰይፍም በኀያላኖችዋ ላይ አለ፤ እነርሱም ይደነግጣሉ።'),
  ('4846f743-e659-5b2d-a217-cf825de36e17', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 37, 37, 'ሰይፍ በፈረሶቻቸውና በሰረገሎቻቸው ላይ፥ በመካከልዋም በተቀላቀሉ ሕዝብ ላይ አለ፤ እነርሱም እንደ ሴቶች ይሆናሉ፤ ሰይፍ በመዝገቦችዋ ላይ አለ፤ ይበተናሉም።'),
  ('99669d54-0daf-504b-ac2a-aa10e42966cb', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 38, 38, 'እርስዋ የተቀረጹ ምስሎች ምድር ናትና፥ እነርሱም በደሴቶችዋ ይመካሉና ሰይፍ በውኆችዋ ላይ አለ፤ እነርሱም ይደርቃሉ።'),
  ('7242c61e-a65f-58c5-a26a-75ef71dbd041', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 39, 39, 'ስለዚህ የዱር አራዊት ከተኵላዎች ጋር ይቀመጡባታል፤ ሰጎኖችም ይቀመጡባታል፤ ሰውም ከዚያ ወዲያ ለዘለዓለም አይቀመጥባትም፤ እስከ ልጅ ልጅም ድረስ የሚኖርባት የለም።'),
  ('4de1a409-638c-578a-a4e1-49d6620fb853', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 40, 40, 'ሰዶምንና ገሞራን፥ በአጠገባቸውም የነበሩትን ከተሞች እግዚአብሔር እንደ ገለበጣቸው፥ ይላል እግዚአብሔር፤ እንዲሁ ሰው በዚያ አይቀመጥም፤ የሰውም ልጅ አይኖርባትም።'),
  ('b7dcd981-d7f3-5ed7-a9cf-844afc9d59af', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 41, 41, '“እነሆ ሕዝብ ከሰሜን ይመጣል፤ ታላቅ ሕዝብና ብዙ ነገሥታትም ከምድር ዳርቻ ይነሣሉ።'),
  ('b5d1e33d-c121-5930-afd1-f27a2af313d1', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 42, 42, 'ቀስትና ጦርን ይይዛሉ፤ ጨካኞች ናቸው፤ ምሕረትም አያደርጉም፤ ድምፃቸው እንደ ባሕር ይተምማል፤ በፈረሶችም ላይ ይቀመጣሉ፤ የባቢሎን ሴት ልጅ ሆይ እንደ እሳት በአንቺ ላይ ይሰለፋሉ።'),
  ('d19ff503-364c-5e76-aaea-4c41f5fb802c', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 43, 43, 'የባቢሎን ንጉሥ ውካታቸውን ሰምቶአል፤ እጁም ደክማለች፤ ምጥ ወላድ ሴትን እንደሚይዛትም ጭንቀት ይዞታል፤'),
  ('7e28524c-f7c0-5c96-af09-9a5ed605119a', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 44, 44, 'እነሆ ከእርስዋ ዘንድ በቶሎ አባርራቸዋለሁና እንደ አንበሳ ከዮርዳኖስ ዳር ወደ ኤታም ምድር ይወጣል፤ ጐልማሶቹንም ሁሉ በእርስዋ ላይ እሾማለሁ፤ እንደ እኔ ያለ ማን ነው? ወይስ ለእኔ ጊዜን የሚወስን ማን ነው? ወይስ ፊቴን የሚቋቋም እረኛ ማን ነው?'),
  ('625fc60a-7146-5b74-a77b-1775256a4149', '1379d228-7112-5e61-ad94-a3dd038adfe1', '75d976b2-6794-5846-a70e-47db29f96430', 45, 45, 'ስለዚህ እግዚአብሔር በባቢሎን ላይ የመከረባትን ምክር፥ በከለዳውያንም ምድር ላይ ያሰባትን ዐሳብ ስሙ፤ በእውነት የበጎቻቸቸው ጠቦቶች ይጠፋሉ፤ በእውነት ማደሪያዎቻቸውም ባድማ ይሆናሉ።')
